'use client';
import React from 'react';
type MathRow={left:string;right?:string;cancelLeft?:boolean;cancelRight?:boolean;operatorLeft?:string;operatorRight?:string};
type Step={text:string;math?:string[];rows?:MathRow[];note?:string};
type Ex={q:string;steps:(string|Step)[];answer:string};
type S={title:string;body:string[];board?:string[];example?:Ex;examples?:Ex[]};
type Lesson={title:string;objectives:string[];sections:S[];mistakes:string[]};
function MathText({text}:{text:string}){const normalized=text.replaceAll('⁄','/');const re=/(\([^()]+\)|[₦+−-]?[A-Za-z0-9,.]+)\/(\([^()]+\)|[₦+−-]?[A-Za-z0-9,.]+)/g;const out:React.ReactNode[]=[];let last=0,m:RegExpExecArray|null;while((m=re.exec(normalized))){if(m.index>last)out.push(normalized.slice(last,m.index));out.push(<span className="true-fraction" key={m.index}><span className="fraction-top">{m[1]}</span><span className="fraction-bottom">{m[2]}</span></span>);last=m.index+m[0].length}if(last<normalized.length)out.push(normalized.slice(last));return <>{out}</>}
function CoreTopicVisual({topic,title}:{topic:string,title:string}){void topic;void title;return null}
function BearingDiagram({type}:{type:string}){const base={viewBox:"0 0 360 220",role:"img",className:"bearing-svg"} as const;if(type==="compass")return <svg {...base} aria-label="Compass showing eight directions"><line x1="180" y1="25" x2="180" y2="195"/><line x1="95" y1="110" x2="265" y2="110"/><line x1="120" y1="50" x2="240" y2="170"/><line x1="240" y1="50" x2="120" y2="170"/><circle cx="180" cy="110" r="5"/><text x="180" y="18">N</text><text x="275" y="115">E</text><text x="180" y="215">S</text><text x="78" y="115">W</text><text x="248" y="45">NE</text><text x="250" y="185">SE</text><text x="108" y="185">SW</text><text x="108" y="45">NW</text></svg>;
if(type==="clockwise")return <svg {...base} aria-label="Bearing measured clockwise from North"><line x1="100" y1="190" x2="100" y2="25"/><polygon points="100,15 94,29 106,29"/><line x1="100" y1="190" x2="270" y2="90" strokeWidth="3"/><path d="M100 75 A115 115 0 0 1 200 125" fill="none" strokeWidth="3"/><text x="112" y="30">N / 000°</text><text x="185" y="105">060° clockwise</text><text x="278" y="92">B</text></svg>;
if(type==="reverse")return <svg {...base} aria-label="Forward and reverse bearing"><line x1="70" y1="185" x2="70" y2="30"/><line x1="285" y1="35" x2="285" y2="190"/><line x1="70" y1="185" x2="285" y2="35" strokeWidth="3"/><text x="52" y="207">A</text><text x="296" y="40">B</text><text x="85" y="155">070°</text><text x="220" y="75">250°</text><text x="105" y="215">reverse differs by 180°</text></svg>;
if(type==="scale")return <svg {...base} aria-label="Bearing with scale distance"><line x1="75" y1="190" x2="75" y2="25"/><line x1="75" y1="190" x2="285" y2="75" strokeWidth="3"/><path d="M75 80 A110 110 0 0 1 180 130" fill="none" strokeWidth="3"/><circle cx="75" cy="190" r="5"/><circle cx="285" cy="75" r="5"/><text x="55" y="212">A</text><text x="296" y="80">B</text><text x="145" y="112">120°</text><text x="160" y="175">5 cm</text></svg>;
return <svg {...base} aria-label="Multi point bearing with parallel North lines"><line x1="65" y1="185" x2="65" y2="30"/><line x1="215" y1="185" x2="215" y2="30"/><line x1="65" y1="185" x2="215" y2="185" strokeWidth="3"/><line x1="215" y1="185" x2="285" y2="75" strokeWidth="3"/><text x="48" y="207">A</text><text x="205" y="207">B</text><text x="292" y="75">C</text><text x="75" y="45">N</text><text x="225" y="45">N</text><text x="105" y="175">090°</text><text x="235" y="135">bearing from B</text></svg>}
function BearingVisualForSection({title}:{title:string}){if(title.includes("Cardinal-point"))return <BearingDiagram type="compass"/>;if(title.includes("Three-digit")||title.includes("bearing tells"))return <BearingDiagram type="clockwise"/>;if(title.includes("Reverse")||title.includes("from A"))return <BearingDiagram type="reverse"/>;if(title.includes("Locate")||title.includes("distance together")||title.includes("Constructing"))return <BearingDiagram type="scale"/>;if(title.includes("Multi-point")||title.includes("Multi-stage"))return <BearingDiagram type="multi"/>;return null}

function LegacyStep({text}:{text:string}){const parts=text.split(/(?<=\.)\s+(?=[A-Z₦0-9(+−√])/).filter(Boolean);const looksMath=(s:string)=>/[=×÷<>≈√²³%]|\d\s*[+−-]\s*\d|[A-Za-z0-9)]\/[A-Za-z0-9(]/.test(s);const math=parts.filter(looksMath),prose=parts.filter(x=>!looksMath(x));if(!math.length)return <div className="math-line legacy-explanation"><MathText text={text}/></div>;return <div className="math-line math-teaching-step legacy-structured-step">{prose.length>0&&<div className="step-explanation">{prose.map((x,i)=><span key={i}>{x}{i<prose.length-1?' ':''}</span>)}</div>}<div className="vertical-working">{math.map((x,i)=><div className="vertical-equation" key={i}><MathText text={x}/></div>)}</div></div>}
const lessons:Record<string,Lesson>={
"Square Root of Numbers":{title:"Square Root of Numbers",objectives:["Explain what squaring a number means and connect a square to area","Identify perfect squares and distinguish them from non-perfect squares","Find squares of whole numbers and decimals","Explain square root as the inverse of squaring","Find square roots of perfect squares by inspection and by prime-factor method","Estimate the square root of a non-perfect square between consecutive whole numbers","Solve quantitative reasoning and real-life problems involving squares and square roots"],sections:[
{title:"1. Foundation: what does it mean to square a number?",body:["Before using the square-root sign, understand the idea that creates a square. If a square has side length 4 units, it contains 4 rows of 4 unit squares. Its area is 4 × 4 = 16 square units. We write this as 4² = 16.","The small raised 2 is called an exponent or index. It tells us to use the number as a factor twice. Therefore 7² means 7 × 7, not 7 × 2.","This gives a useful picture: squaring a positive number can be understood as finding the area of a square whose side is that number."] ,example:{q:"Find 12² and explain what the notation means.",steps:["12² means that 12 is used as a factor two times.","Write the multiplication explicitly: 12 × 12.","Multiply: 12 × 12 = 144.","Therefore 12² = 144.","Check the meaning: a square of side 12 units would have area 144 square units."],answer:"12² = 144"},examples:[{q:"Find 35².",steps:["35² means 35 × 35.","35 × 30 = 1,050 and 35 × 5 = 175.","1,050 + 175 = 1,225.","Check: the result lies between 30²=900 and 40²=1,600."],answer:"35² = 1,225"},{q:"Find 105².",steps:["105² = 105 × 105.","105 × 100 = 10,500.","105 × 5 = 525.","Add: 10,500 + 525 = 11,025."],answer:"105² = 11,025"}]},
{title:"2. Perfect squares: build the pattern instead of memorising blindly",body:["A perfect square is a number obtained by multiplying a whole number by itself. Examples are 1, 4, 9, 16 and 25 because they are 1², 2², 3², 4² and 5².","The sequence continues: 6²=36, 7²=49, 8²=64, 9²=81, 10²=100, 11²=121, 12²=144, 13²=169, 14²=196, 15²=225, 16²=256, 17²=289, 18²=324, 19²=361, 20²=400.","Numbers such as 50 and 70 are not perfect squares because no whole number multiplied by itself gives exactly 50 or 70. Knowing neighbouring perfect squares later helps us estimate their square roots."]},
{title:"3. Squaring larger numbers: make every operation visible",body:["When mental multiplication is not immediate, use a known multiplication method. The exponent does not change the multiplication rules."],example:{q:"Find 23².",steps:["23² means 23 × 23.","Split the second 23 into 20 + 3.","23 × 20 = 460.","23 × 3 = 69.","Add the two partial products: 460 + 69 = 529.","Therefore 23² = 529.","Check: 529 is larger than 20²=400 and smaller than 30²=900, so the size is reasonable."],answer:"23² = 529"}},
{title:"4. Decimal squares",body:["Decimals can also be squared. Multiply the number by itself and keep the place value correct. A useful check is size: if a positive number is less than 1, its square is even smaller."],example:{q:"Find 0.6².",steps:["0.6² means 0.6 × 0.6.","Ignoring the decimal points for a moment, 6 × 6 = 36.","There is one decimal place in each factor, so the product has two decimal places.","36 becomes 0.36.","Check: 0.6 is less than 1, so its square 0.36 should also be less than 1."],answer:"0.6² = 0.36"},examples:[{q:"Find 1.2².",steps:["1.2² = 1.2 × 1.2.","12 × 12 = 144.","There are two decimal places altogether, so write 1.44.","Check: since 1.2 is greater than 1, its square should be greater than 1."],answer:"1.2² = 1.44"},{q:"Find 0.04².",steps:["0.04 × 0.04 uses 4 × 4 = 16.","There are four decimal places altogether.","Write 0.0016.","Check: squaring a positive number below 1 makes it smaller."],answer:"0.04² = 0.0016"}]},
{title:"5. Square root: reverse the squaring process",body:["A square root asks the reverse question. If 9² = 81, then the positive square root of 81 is 9. We write √81 = 9.","The radical symbol √ means square root. At this level, when AVORA writes √81, we mean the principal, non-negative square root.","Do not confuse square root with dividing by 2. √36 is 6 because 6 × 6 = 36; 36 ÷ 2 = 18 answers a completely different question."],example:{q:"Find √169.",steps:["Ask: which positive whole number multiplied by itself gives 169?","Recall nearby perfect squares: 12²=144 and 13²=169.","Since 13 × 13 = 169, 13 is the positive number whose square is 169.","Therefore √169 = 13.","Check by reversing the operation: 13² = 169."],answer:"√169 = 13"}},
{title:"6. Why the prime-factor method works",body:["Inspection is easy for familiar perfect squares, but the curriculum also requires the factor method. First break the number completely into prime factors.","A perfect square contains prime factors in pairs. This happens because squaring duplicates every prime factor in the original number. If 12 = 2² × 3, then 12² = 2⁴ × 3². To undo the square, take one factor from each identical pair.","The pairing is not decoration: each pair is one factor multiplied by itself. Taking the square root reverses that squaring, so one member of each pair remains."],board:["Prime-factor square-root method","1. Factorise the number completely into primes.","2. Put identical prime factors into pairs.","3. Take ONE factor from each complete pair.","4. Multiply the factors you took.","5. Square the result to check that it returns the original number."]},
{title:"7. Prime-factor method — no jump in the working",body:["We will not jump from the number straight to its root. Factorise, pair, select one from each pair, multiply, then check."],example:{q:"Find √144 using the prime-factor method.",steps:["Start by breaking 144 into prime factors.","144 ÷ 2 = 72, so write one factor 2.","72 ÷ 2 = 36, so write another factor 2.","36 ÷ 2 = 18, so write another factor 2.","18 ÷ 2 = 9, so write another factor 2.","9 ÷ 3 = 3, and 3 ÷ 3 = 1.","Therefore 144 = 2 × 2 × 2 × 2 × 3 × 3.","Group identical factors into pairs: (2 × 2) × (2 × 2) × (3 × 3).","Square root removes one copy from each pair, so take 2 × 2 × 3.","2 × 2 × 3 = 12.","Check: 12 × 12 = 144."],answer:"√144 = 12"},examples:[{q:"Find √196 by prime factors.",steps:[{text:"Rewrite 196 completely as prime factors. Begin with the smallest prime that divides it and keep that division visible.",math:["196 ÷ 2 = 98","98 ÷ 2 = 49","49 ÷ 7 = 7","7 ÷ 7 = 1"]},{text:"Now display the factors and pair identical primes. Each pair is a perfect square.",math:["196 = 2 × 2 × 7 × 7","    = (2 × 2)(7 × 7)"]},{text:"Square root reverses squaring, so take ONE factor from each identical pair.",math:["√196 = 2 × 7","     = 14"]},{text:"Verify by squaring the result.",math:["14² = 14 × 14","    = 196 ✓"]}],answer:"√196 = 14"},{q:"Find √576 by prime factors.",steps:[{text:"Prime-factorise 576 completely and keep each division visible.",math:["576 ÷ 2 = 288","288 ÷ 2 = 144","144 ÷ 2 = 72","72 ÷ 2 = 36","36 ÷ 2 = 18","18 ÷ 2 = 9","9 ÷ 3 = 3","3 ÷ 3 = 1"]},{text:"Pair identical prime factors.",math:["576 = 2×2×2×2×2×2×3×3","= (2×2)(2×2)(2×2)(3×3)"]},{text:"Take one factor from each pair.",math:["√576 = 2×2×2×3","= 24"]},{text:"Verify.",math:["24² = 576 ✓"]}],answer:"√576 = 24"}]},
{title:"8. A larger factor-method example",body:["The same method works when several different prime factors occur. Keep the factors arranged so the pairs are visually obvious."],example:{q:"Find √900 using prime factors.",steps:[{text:"Break 900 into easy factors, then prime-factorise each part.",math:["900 = 9 × 100","9 = 3 × 3","100 = 2 × 2 × 5 × 5"]},{text:"Pair identical prime factors.",math:["900 = (2×2)(3×3)(5×5)"]},{text:"Take one factor from each pair.",math:["√900 = 2 × 3 × 5","= 30"]},{text:"Verify.",math:["30 × 30 = 900 ✓"]}],answer:"√900 = 30"}},
{title:"9. What if the number is not a perfect square?",body:["Not every number has a whole-number square root. For such a number, first find the perfect square immediately below it and the perfect square immediately above it.","Their roots tell us the two consecutive whole numbers between which the required square root lies. This is estimation, not pretending the root is exact."] ,example:{q:"Estimate the position of √50.",steps:["Look for perfect squares around 50.","7² = 49.","8² = 64.","Therefore 49 < 50 < 64.","Taking square roots preserves this positive order: 7 < √50 < 8.","Because 50 is only 1 greater than 49, √50 is only a little greater than 7.","So √50 is between 7 and 8; it is not exactly 7 because 7² is 49."],answer:"7 < √50 < 8"},examples:[{q:"Between which integers does √30 lie?",steps:["5²=25 and 6²=36.","25 < 30 < 36.","Therefore 5 < √30 < 6."],answer:"5 < √30 < 6"},{q:"Between which integers does √130 lie?",steps:["11²=121 and 12²=144.","121 < 130 < 144.","Therefore 11 < √130 < 12."],answer:"11 < √130 < 12"}]},
{title:"10. Estimation by testing a decimal",body:["When a decimal estimate is required, test sensible values by squaring them. Each test tells you whether to move the estimate upward or downward."],example:{q:"Estimate √70 to one decimal place.",steps:["8²=64 and 9²=81, so √70 lies between 8 and 9.","Test 8.3: 8.3² = 68.89, which is below 70.","Test 8.4: 8.4² = 70.56, which is above 70.","So √70 lies between 8.3 and 8.4.","70 is closer to 70.56 than to 68.89, so to one decimal place √70 ≈ 8.4."],answer:"√70 ≈ 8.4 to 1 decimal place"}},
{title:"11. Quantitative reasoning: recognise when a square root is needed",body:["A word problem may never say 'take the square root'. Decide from the relationship. If the area of a square is known and the side is unknown, area = side², so finding the side requires the square root."] ,example:{q:"A square classroom floor has area 324 m². Find the length of one side.",steps:["For a square, area = side × side.","Let the side be s metres. Then s² = 324.","To undo squaring, take the positive square root: s = √324.","18 × 18 = 324, so √324 = 18.","A length cannot be negative in this physical problem."],answer:"The side length is 18 m."},examples:[{q:"A square tile has area 441 cm². Find its side.",steps:["A square has equal sides, so its area is side×side, written side².","Here the area 441 is known but the side is unknown. We therefore need the operation that reverses squaring: square root.","Write side=√441.","Look for the positive number whose square is 441. Since 21×21=441, √441=21.","The side is a length, so attach the unit cm.","Check: 21 cm×21 cm=441 cm², which matches the given area."],answer:"Side = 21 cm"},{q:"A square garden has side 16 m. Find its area.",steps:["Here the side is known, so square it rather than taking a square root.","Area = 16² = 16 × 16 = 256."],answer:"Area = 256 m²"}]},
{title:"12. Multi-step application",body:["Some problems require a square root first and another operation afterward. Do not stop when you have found an intermediate value."],example:{q:"A square field has area 625 m². A fence will go around it. Find the total fence length.",steps:["The field is square, so first find its side from the area.","side = √625 = 25 m because 25 × 25 = 625.","The question asks for fence around the field, which means perimeter.","Perimeter of a square = 4 × side.","Perimeter = 4 × 25 m = 100 m.","Check: four equal sides of 25 m total 100 m."],answer:"100 m of fencing is required."}},
{title:"13. How to choose a method",body:["For a familiar perfect square such as 81 or 144, inspection can be efficient if you can justify it.","When the question specifically asks for the factor method, show the prime factorisation and pairs even if you already know the root.","For a non-perfect square, bracket it between neighbouring perfect squares and estimate if required. For a word problem, first identify the mathematical relationship before choosing the operation."]},
{title:"14. Mastery reasoning",body:["A learner has mastered this topic when they can explain the difference between a square and a square root, identify perfect squares, calculate squares, obtain roots by factor method, estimate non-perfect roots and recognise square-root relationships inside unfamiliar problems.","Every final answer should be checked when practical: square a proposed root and see whether you return to the original number."] ,example:{q:"A learner says √196 = 98 because 196 ÷ 2 = 98. Explain and correct the error.",steps:["The learner has confused square root with halving.","Square root asks for a number which, multiplied by itself, gives 196.","13² = 169, so the root is greater than 13.","14² = 14 × 14 = 196.","Therefore √196 = 14.","Check: 14 × 14 = 196; but 98 × 98 is nowhere near 196."],answer:"√196 = 14"}}
],mistakes:["Do not read a² as a × 2. It means a × a.","Square root does not mean divide by 2.","In the prime-factor method, pair identical prime factors and take one factor from every complete pair.","Do not call a non-perfect square root a whole number merely because it lies near one.","When a word problem asks for perimeter after giving area, finding the side is only an intermediate step.","Always distinguish an exact equality (=) from an estimate (≈)."]},
"Fractions":{title:"Fractions, Ratios, Decimals and Percentages",objectives:["Explain a fraction as equal parts of a whole or quantity and identify numerator and denominator","Recognise equivalent fractions and simplify fractions without changing their value","Convert fractions to decimals, percentages and ratios and explain why each conversion works","Convert decimals, percentages and ratios back to fractions where the comparison is valid","Distinguish part-to-whole from part-to-part comparisons","Solve quantitative aptitude and everyday problems involving fractions, ratios, decimals and percentages"],sections:[
{title:"1. Foundation: what is a fraction?",body:["A fraction describes equal parts. If one whole object is divided into 4 equal parts and you take 3 parts, you have three quarters, written 3/4.","The bottom number is the denominator. It tells us how many equal parts make one whole. The top number is the numerator. It tells us how many of those equal parts we are considering.","The word equal is essential. If a shape is cut into four pieces of different sizes, one piece is not automatically one quarter of the whole."],example:{q:"A loaf is cut into 8 equal slices and Tola eats 3. What fraction of the loaf did Tola eat?",steps:["The whole loaf has been divided into 8 equal parts, so the denominator is 8.","Tola ate 3 of those equal parts, so the numerator is 3.","Place the number eaten over the total equal parts: 3/8.","The remaining part would be 5/8 because 3/8 + 5/8 = 8/8 = 1 whole."],answer:"Tola ate 3/8 of the loaf."}},
{title:"2. A fraction is also division",body:["The fraction bar means division. Therefore a/b means a ÷ b, provided b is not zero.","This connection is the bridge from fractions to decimals. We are not using a new unrelated trick when we divide the numerator by the denominator; we are carrying out the division already written in the fraction."],example:{q:"Explain why 3/4 can be written as 0.75.",steps:["3/4 means 3 ÷ 4.","Because 3 is smaller than 4, the answer will be less than 1.","Write 3 as 3.00 so the division can continue into decimal places.","4 goes into 30 seven times: 7 × 4 = 28, leaving 2.","Bring down the next 0: 20 ÷ 4 = 5.","Therefore 3 ÷ 4 = 0.75.","Check: 0.75 × 4 = 3, so the division is correct."],answer:"3/4 = 0.75"}},
{title:"3. Equivalent fractions: same amount, different names",body:["Equivalent fractions look different but represent the same value. Multiplying or dividing the numerator and denominator by the same non-zero number preserves the fraction because we are effectively multiplying or dividing by 1.","For example, 1/2 × 2/2 = 2/4. Since 2/2 = 1, the value has not changed."],example:{q:"Show that 6/8 and 3/4 are equivalent.",steps:["Look for a number that divides both 6 and 8 exactly.","Both are divisible by 2.","6 ÷ 2 = 3.","8 ÷ 2 = 4.","So 6/8 = 3/4.","Check using division: 6 ÷ 8 = 0.75 and 3 ÷ 4 = 0.75."],answer:"6/8 = 3/4"}},
{title:"4. Simplifying a fraction completely",body:["To simplify a fraction, divide numerator and denominator by a common factor. To reach simplest form in one step, divide by their Highest Common Factor (HCF).","Why does the value stay unchanged? Because numerator and denominator are divided by the same non-zero number. We are reducing the number of equal parts and the number selected in the same proportion; the fraction gets a simpler name but represents the same amount.","A fraction is in simplest form when numerator and denominator have no common factor greater than 1."],board:["To simplify a fraction","1. Look for a factor common to numerator and denominator.","2. Divide BOTH by that same factor.","3. For one-step simplification, use their HCF.","4. Check whether any common factor greater than 1 remains.","5. If none remains, the fraction is in simplest form."],example:{q:"Simplify 18/30 completely.",steps:[{text:"The HCF of 18 and 30 is 6. Divide numerator and denominator by the SAME factor.",math:["18/30","= (18÷6)/(30÷6)","= 3/5"]},{text:"Check that the result cannot be reduced further.",math:["HCF(3,5)=1","3/5 is simplest ✓"]}],answer:"18/30 = 3/5"}},
{title:"5. Fraction to decimal — terminating examples",body:["To convert a fraction to a decimal, divide numerator by denominator. Some divisions end after a finite number of decimal places; these are terminating decimals.","Do not guess the decimal from the appearance of the fraction. Perform the division or create an equivalent fraction with denominator 10, 100, 1000 and so on when convenient."],example:{q:"Convert 7/8 to a decimal.",steps:[{text:"The fraction bar means division.",math:["7/8 = 7 ÷ 8"]},{text:"Continue the division into decimal places and keep each remainder visible.",math:["70 ÷ 8 = 8 remainder 6","60 ÷ 8 = 7 remainder 4","40 ÷ 8 = 5 remainder 0"]},{text:"Read the decimal digits in order.",math:["7 ÷ 8 = 0.875"]},{text:"Check.",math:["0.875 × 8 = 7 ✓"]}],answer:"7/8 = 0.875"},examples:[{q:"Convert 3/5 to a decimal.",steps:["3/5 means 3 ÷ 5.","30 tenths ÷ 5 = 6 tenths.","Therefore 3/5 = 0.6."],answer:"0.6"},{q:"Convert 5/16 to a decimal.",steps:["5/16 means 5 ÷ 16.","500 ÷ 16 = 31 remainder 4, giving 0.31 so far.","40 ÷ 16 = 2 remainder 8; 80 ÷ 16 = 5.","Therefore 5/16 = 0.3125."],answer:"0.3125"}]},
{title:"6. Fraction to percentage — understand 'per hundred'",body:["Percent means 'per hundred' or 'out of 100'. Therefore 35% means 35/100.","To convert a fraction to a percentage, find how many hundredths represent the same value. Multiplying by 100% works because 100% represents one whole: 100/100 = 1, so the value is not being changed."],example:{q:"Convert 7/20 to a percentage.",steps:[{text:"Percent means out of 100. Find the multiplier that changes denominator 20 into 100.",math:["20 × 5 = 100"]},{text:"Multiply numerator and denominator by that SAME number.",math:["7/20","= (7×5)/(20×5)","= 35/100"]},{text:"Now read the fraction per hundred as a percentage.",math:["35/100 = 35%"]}],answer:"7/20 = 35%"},examples:[{q:"Convert 3/8 to a percentage.",steps:[{text:"Percent means out of 100. Start by displaying the fraction as a fraction, not as a slash expression.",math:["3/8"]},{text:"Because 8 does not scale to 100 by a whole-number multiplier, first find the decimal value of the fraction.",math:["3 ÷ 8","= 0.375"]},{text:"Convert that decimal to percent by multiplying by 100%.",math:["0.375 × 100%","= 37.5%"]},{text:"Check that the fraction and percentage still represent the same value.",math:["37.5/100","= 0.375","= 3/8 ✓"]}],answer:"37.5%"},{q:"Convert 9/4 to a percentage.",steps:["An improper fraction can represent more than one whole.","9/4 × 100% = 225%.","A value greater than 100% is reasonable because 9/4 = 2.25 wholes."],answer:"225%"}]},
{title:"7. Percentage to fraction — reverse the meaning",body:["Because percent means out of 100, write the percentage number over 100, then simplify.","A percentage may be greater than 100. That simply represents more than one whole."],example:{q:"Convert 62.5% to a fraction in simplest form.",steps:[{text:"Percent means out of 100.",math:["62.5% = 62.5/100"]},{text:"Remove the decimal without changing the fraction value.",math:["62.5/100","= 625/1000"]},{text:"The HCF is 125. Divide numerator and denominator by 125.",math:["625/1000","= (625÷125)/(1000÷125)","= 5/8"]},{text:"Check by converting back.",math:["5 ÷ 8 = 0.625","0.625 × 100% = 62.5% ✓"]}],answer:"62.5% = 5/8"},examples:[{q:"Convert 45% to a fraction.",steps:["45% = 45/100.","Divide top and bottom by 5: 9/20."],answer:"9/20"},{q:"Convert 140% to a fraction.",steps:["140% = 140/100.","Divide by 20: 7/5.","The improper fraction is expected because 140% is more than one whole."],answer:"7/5"}]},
{title:"8. Decimal to fraction — place value tells the denominator",body:["A terminating decimal can be read as tenths, hundredths, thousandths and so on. That place value gives the denominator before simplification.","For example, 0.4 means four tenths, 0.37 means thirty-seven hundredths and 0.625 means six hundred twenty-five thousandths."],example:{q:"Convert 0.375 to a fraction in simplest form.",steps:["There are three digits after the decimal point, so 0.375 means 375 thousandths.","Write 0.375 = 375/1000.","Both numerator and denominator are divisible by 125.","375 ÷ 125 = 3.","1000 ÷ 125 = 8.","Therefore 0.375 = 3/8.","Check: 3 ÷ 8 = 0.375."],answer:"0.375 = 3/8"},examples:[{q:"Convert 0.06 to a fraction.",steps:["0.06 means 6 hundredths: 6/100.","Divide by 2: 3/50."],answer:"3/50"},{q:"Convert 1.25 to a fraction.",steps:["1.25 = 125/100.","Divide numerator and denominator by 25.","125÷25=5 and 100÷25=4."],answer:"5/4 or 1 1/4"}]},
{title:"9. Percentage and decimal — why the decimal point moves",body:["To change a decimal to a percentage, multiply by 100 because percentage asks how many hundredths the value contains. Multiplying by 100 shifts place values two positions to the left, which appears as the decimal point moving two places right.","To change a percentage to a decimal, divide by 100. Do not memorise 'move the point' without knowing that multiplication or division by 100 is the reason."],example:{q:"Convert 0.086 to a percentage, then convert 125% to a decimal.",steps:["For 0.086, multiply by 100: 0.086 × 100 = 8.6.","Attach the percent sign because the result is now expressed per hundred: 8.6%.","For 125%, remove the percent meaning by dividing by 100: 125 ÷ 100 = 1.25.","Notice that 125% is greater than 100%, so its decimal 1.25 is greater than 1. This is reasonable."],answer:"0.086 = 8.6%; 125% = 1.25"}},
{title:"10. Ratio: what exactly is being compared?",body:["A ratio compares quantities. The order matters: 2:5 means first quantity to second quantity is 2 to 5.","A fraction often describes part of a whole, while a ratio may compare part to part or part to whole. Therefore we must read the words before converting.","If boys:girls = 2:3, then boys/girls = 2/3, but the fraction of the whole class who are boys is 2/(2+3) = 2/5. These are different questions."],example:{q:"A class has boys:girls = 3:5. What fraction of the whole class are boys?",steps:["The ratio says 3 equal parts are boys and 5 equal parts are girls.","The whole class therefore contains 3 + 5 = 8 equal ratio parts.","Boys occupy 3 of those 8 total parts.","So the fraction of the whole class who are boys is 3/8.","Do not answer 3/5: that compares boys directly with girls, not boys with the whole class."],answer:"Boys are 3/8 of the class."}},
{title:"11. Fraction to ratio — state the comparison",body:["A fraction a/b can be written numerically as a:b when it is explicitly comparing the first quantity with the second quantity. But context determines whether b is another part or the whole.","When a fraction describes 'part of a whole', a useful part-to-part ratio may require finding the remaining part first."],example:{q:"3/7 of a group are prefects. Find the ratio of prefects to non-prefects.",steps:["The whole group is represented by 7 equal parts.","Prefects occupy 3 parts.","Non-prefects occupy the remaining 7 − 3 = 4 parts.","Therefore prefects : non-prefects = 3 : 4.","Notice that 3:7 would be prefects : whole group, not prefects : non-prefects."],answer:"3:4"}},
{title:"12. Ratio to fraction and percentage of a whole",body:["When a ratio gives two or more parts of one whole, add the ratio parts first to find the total number of equal shares. Then place the required part over that total.","Once the fraction of the whole is known, the same quantity can be converted to a decimal or percentage."],example:{q:"Red:blue counters = 2:3. What percentage of all the counters are blue?",steps:["Red uses 2 ratio parts and blue uses 3 ratio parts.","Total parts = 2 + 3 = 5.","Blue therefore represents 3/5 of the whole.","Convert 3/5 to a decimal: 3 ÷ 5 = 0.6.","Convert to percentage: 0.6 × 100% = 60%."],answer:"60% of the counters are blue."}},
{title:"13. Sharing a quantity in a ratio",body:["To share a total in a ratio, add the ratio terms to find the number of equal shares. Divide the total by that number to find the value of one share, then multiply by each ratio term.","Always check that the final shares add back to the original total."],example:{q:"Share ₦4,200 in the ratio 2:5.",steps:["Add the ratio parts: 2 + 5 = 7 parts.","The ₦4,200 is divided into 7 equal shares.","Value of one share = ₦4,200 ÷ 7 = ₦600.","First share = 2 × ₦600 = ₦1,200.","Second share = 5 × ₦600 = ₦3,000.","Check: ₦1,200 + ₦3,000 = ₦4,200, the original total."],answer:"₦1,200 and ₦3,000"},examples:[{q:"Share 96 in the ratio 5:3.",steps:["The ratio 5:3 means the whole quantity is divided into 5+3 equal ratio-parts.","Add the ratio numbers: 5+3=8 parts altogether.","The total quantity is 96, so find the value of one ratio-part: 96÷8=12.","The first share has 5 parts, so 5×12=60.","The second share has 3 parts, so 3×12=36.","Check both conditions: 60+36=96, and 60:36 simplifies to 5:3."],answer:"60 and 36"},{q:"Share ₦18,000 in the ratio 2:3:4.",steps:["Total parts = 2+3+4=9.","One part = ₦18,000÷9=₦2,000.","Shares are ₦4,000, ₦6,000 and ₦8,000.","Check total = ₦18,000."],answer:"₦4,000, ₦6,000 and ₦8,000"}]},
{title:"14. Finding a percentage of a quantity",body:["A percentage is a fraction of 100, so p% of a quantity means p/100 multiplied by that quantity.","The word 'of' signals multiplication here. Simplify before multiplying when that makes the arithmetic clearer."],example:{q:"Find 35% of 240.",steps:["35% means 35/100.","So 35% of 240 = 35/100 × 240.","Simplify 240/100 to 12/5, or divide 240 by 100 first: 240 ÷ 100 = 2.4.","2.4 × 35 = 84.","Alternative check: 30% of 240 = 72 and 5% = 12; 72 + 12 = 84."],answer:"35% of 240 = 84"},examples:[{q:"Find 12.5% of 320.",steps:["12.5% means 12.5 out of 100.","Write 12.5/100 and simplify: multiply top and bottom by 10 to get 125/1000.","125/1000 simplifies to 1/8.","So finding 12.5% of 320 is the same as finding 1/8 of 320.","Divide 320 into 8 equal parts: 320÷8=40.","Therefore 12.5% of 320=40."],answer:"40"},{q:"Find 7.5% of ₦48,000.",steps:["7.5%=7.5/100=0.075.","0.075×48,000=3,600."],answer:"₦3,600"}]},
{title:"15. Finding the whole when a fraction or percentage is known",body:["Sometimes the problem gives a part and asks for the whole. Do not multiply by the percentage again. Build an equation showing that the stated fraction or percentage of the whole equals the known part.","This reverse reasoning is important in quantitative aptitude."],example:{q:"30% of a number is 24. Find the number.",steps:["Let the whole number be x.","30% means 30/100 = 0.30.","The statement becomes 0.30 × x = 24.","To undo multiplication by 0.30, divide both sides by 0.30.","x = 24 ÷ 0.30 = 80.","Check: 30% of 80 = 0.30 × 80 = 24."],answer:"The number is 80."},examples:[{q:"15% of a number is 54. Find the number.",steps:["Let the number be x.","0.15x=54.","x=54÷0.15=360.","Check: 15% of 360=54."],answer:"360"},{q:"3/7 of a quantity is 24. Find the whole quantity.",steps:["3/7 × x = 24.","One seventh is 24÷3=8.","Seven sevenths = 8×7=56."],answer:"56"}]},
{title:"16. Percentage increase and decrease",body:["A percentage change is measured against the original quantity unless the question states another base. First find the actual change, then compare that change with the original.","After finding a percentage increase or decrease, distinguish the amount of change from the new final value."],example:{q:"A quantity rises from 40 to 50. Find the percentage increase.",steps:["Original quantity = 40.","New quantity = 50.","Increase = 50 − 40 = 10.","Compare the increase with the original: 10/40.","Convert to percentage: 10/40 × 100% = 25%.","Check: 25% of 40 = 10, and 40 + 10 = 50."],answer:"The percentage increase is 25%."},examples:[{q:"A price falls from ₦8,000 to ₦6,800. Find the percentage decrease.",steps:["Identify the original price, ₦8,000, and the new price, ₦6,800.","Because the new price is smaller, this is a decrease.","Find the actual decrease first: ₦8,000−₦6,800=₦1,200.","Percentage decrease compares the change with the ORIGINAL value, because that is the starting point.","Percentage decrease=(decrease÷original)×100%.","=(₦1,200÷₦8,000)×100%.","₦1,200÷₦8,000=0.15.","0.15×100%=15%.","Check: 15% of ₦8,000 is ₦1,200, and ₦8,000−₦1,200=₦6,800."],answer:"15% decrease"},{q:"Increase ₦12,000 by 18%.",steps:["18% of ₦12,000 = ₦2,160.","New amount = ₦12,000+₦2,160.","Alternatively multiply by 1.18."],answer:"₦14,160"},{q:"Decrease 450 by 12%.",steps:["12% of 450=54.","New value=450−54=396.","Equivalent multiplier: 0.88×450=396."],answer:"396"},{q:"After a 20% increase, a price is ₦9,600. Find the original price.",steps:["After a 20% increase, the new price is 120% of the original.","Let original=x: 1.20x=9,600.","x=9,600÷1.20=8,000."],answer:"₦8,000"},{q:"A value increases by 20% and then decreases by 20%. Does it return to its original value?",steps:["Use 100 as an easy original value.","Increase 20%: 100→120.","Decrease 20% of the new 120: 20%×120=24.","120−24=96.","The two percentages use different bases, so they do not cancel."],answer:"No. It ends at 96, which is 4% below the original."}]},
{title:"17. Mixed quantitative reasoning — choose the representation that helps",body:["Fractions, ratios, decimals and percentages are not four disconnected topics. They are different ways to express relationships. In a problem, convert to the form that makes the required reasoning clearest.","Before calculating, ask: What is the whole? What is the part? What two quantities are being compared? Is the question asking for a share, a percentage, a decimal or a ratio?"],example:{q:"In a club of 80 learners, 3/8 are in the science group. Of the remaining learners, boys:girls = 2:3. How many girls are among the remaining learners?",steps:["First find the science group: 3/8 of 80.","80 ÷ 8 = 10, then 10 × 3 = 30 learners in the science group.","Remaining learners = 80 − 30 = 50.","Among the remaining learners, boys:girls = 2:3.","Total ratio parts = 2 + 3 = 5.","One ratio part = 50 ÷ 5 = 10.","Girls occupy 3 parts, so girls = 3 × 10 = 30.","Check: boys would be 20; 20 + 30 = 50 remaining learners."],answer:"30 girls"}},
{title:"18. Mastery: prove that the forms agree",body:["A strong learner should be able to travel in both directions: fraction ↔ decimal, fraction ↔ percentage, percentage ↔ decimal, and ratio ↔ fraction when the comparison is clearly defined.","Do not accept an answer merely because it looks familiar. Verify it by converting through another representation or checking against the original quantities."],example:{q:"A learner says 3/5 = 0.6 = 6% = 3:5. Identify the error and correct the chain.",steps:["Check the fraction-to-decimal step: 3 ÷ 5 = 0.6, so that part is correct.","Convert 0.6 to a percentage by multiplying by 100: 0.6 × 100% = 60%.","Therefore 6% is wrong; 6% would equal 0.06.","For a direct first-to-second numerical comparison, 3/5 corresponds to 3:5.","The corrected chain is 3/5 = 0.6 = 60%, with 3:5 representing the stated first-to-second ratio."],answer:"Corrected: 3/5 = 0.6 = 60%; direct ratio 3:5."}}
],mistakes:["Do not treat unequal pieces as fractions of equal size.","Do not change only the numerator or only the denominator when making an equivalent fraction.","The fraction bar means division; do not invent a decimal from the digits.","Percent means per hundred. 0.6 is 60%, not 6%.","Always simplify a fraction when simplest form is required.","A part-to-part ratio such as boys:girls = 3:5 does not mean boys are 3/5 of the whole class; the whole has 8 ratio parts.","When sharing in a ratio, add the ratio parts before dividing the total.","Percentage change is normally compared with the original quantity, not the new quantity.","Distinguish the amount of a percentage change from the final amount after the change.","Check conversions by moving through another form or substituting back into the original problem."]},
"Commercial Arithmetic":{title:"Commercial Arithmetic",objectives:["Use arithmetic confidently in household, office and market situations","Interpret bills, receipts, budgets and simple financial records","Distinguish cost price, selling price, marked price, profit and loss","Calculate profit and loss amounts and percentages","Calculate discounts and final prices in direct and reverse problems","Calculate simple interest, principal, rate, time and total amount","Calculate commission and solve multi-step commercial problems"],sections:[
{title:"1. Why commercial arithmetic matters",body:["Commercial arithmetic is ordinary mathematics applied to money decisions in homes, offices and markets. The difficulty is often not multiplication itself but deciding what each number means and which quantity is the correct base.","Before calculating, identify the quantities, their units and the question being asked. Money answers should carry the correct currency symbol and should be checked for reasonableness."],examples:[{q:"A family receives ₦185,000 in a month and plans expenses of ₦42,000, ₦55,000, ₦28,000 and ₦36,000. Find the balance.",steps:["Total planned expenditure = 42,000+55,000+28,000+36,000 = ₦161,000.","Balance = income−expenditure = ₦185,000−₦161,000 = ₦24,000.","Because expenditure is below income, this is a surplus, not a deficit."],answer:"Balance = ₦24,000 surplus"},{q:"An office has ₦96,500 available but its planned expenses total ₦104,200. Find the deficit.",steps:["Deficit means planned expenditure exceeds available money.","Deficit = ₦104,200−₦96,500 = ₦7,700."],answer:"Deficit = ₦7,700"}]},
{title:"2. Bills and household arithmetic",body:["A bill records amounts owed for goods or services. Some bills use quantity × unit price; others combine fixed charges and usage charges. Read the structure before adding.","Always distinguish a subtotal from the final total when another charge or reduction still has to be applied."],examples:[{q:"A household buys 6 units of an item at ₦1,250 each and 4 units at ₦850 each. Find the total bill.",steps:["First item: 6×₦1,250=₦7,500.","Second item: 4×₦850=₦3,400.","Total bill=₦7,500+₦3,400=₦10,900."],answer:"₦10,900"},{q:"An electricity bill has a fixed charge of ₦1,500 plus ₦68 for each of 120 units used. Find the bill.",steps:["Usage charge=120×₦68=₦8,160.","Add fixed charge: ₦8,160+₦1,500=₦9,660."],answer:"₦9,660"}]},
{title:"3. Cost price, selling price, profit and loss",body:["Before using any formula, identify the two prices. Cost Price (CP) is what the trader paid for the article. Selling Price (SP) is what the trader receives when the article is sold.","Now compare them. If the selling price is greater, the trader received more than was spent, so the difference is profit. If the cost price is greater, the trader received less than was spent, so the difference is loss."],board:["If SP > CP:","Profit = Selling Price − Cost Price","Profit = SP − CP","","If CP > SP:","Loss = Cost Price − Selling Price","Loss = CP − SP"],examples:[{q:"A trader buys a bag for ₦24,000 and sells it for ₦30,000. Find the profit.",steps:["SP is greater than CP, so there is a profit.","Profit=SP−CP=₦30,000−₦24,000=₦6,000."],answer:"Profit = ₦6,000"},{q:"A phone bought for ₦85,000 is sold for ₦76,500. Find the loss.",steps:["CP is greater than SP, so there is a loss.","Loss=CP−SP=₦85,000−₦76,500=₦8,500."],answer:"Loss = ₦8,500"}]},
{title:"4. Profit and loss percentages — choose the correct base",body:["To find a profit percentage, we first need the actual profit. That is why Profit = SP − CP must already be established before the percentage formula is used.","Next ask: percentage of what? Profit or loss is compared with the Cost Price because CP is the original amount the trader invested. So the cost price becomes the denominator.","The same reasoning gives the loss-percentage formula. Do not divide by selling price unless a question explicitly defines a different comparison."],board:["Step 1: Find the gain or loss","Profit = SP − CP","Loss = CP − SP","","Step 2: Compare it with the original Cost Price","Profit % = (Profit ÷ CP) × 100%","Loss % = (Loss ÷ CP) × 100%"],examples:[{q:"An article costs ₦24,000 and sells for ₦30,000. Find profit percent.",steps:["First identify the prices: CP=₦24,000 and SP=₦30,000.","Because SP is greater than CP, this is a profit.","Find the profit before using a percentage: Profit=SP−CP.","Profit=₦30,000−₦24,000.","Profit=₦6,000.","Now compare that ₦6,000 profit with the original amount invested, the CP.","Profit %=(Profit÷CP)×100%.","Profit %=(₦6,000÷₦24,000)×100%.","₦6,000÷₦24,000=1/4.","1/4×100%=25%.","Check: 25% of ₦24,000 is ₦6,000, and ₦24,000+₦6,000=₦30,000."],answer:"25% profit"},{q:"A trader buys goods for ₦50,000 and sells them for ₦42,500. Find loss percent.",steps:["Identify the prices first: CP=₦50,000 and SP=₦42,500.","Because SP is below CP, money was lost rather than gained.","Find the loss amount before finding its percentage: Loss=CP−SP.","Loss=₦50,000−₦42,500.","Loss=₦7,500.","A loss percentage compares the loss with the original cost price, because CP is the amount originally invested.","Loss %=(Loss÷CP)×100%.","Loss %=(₦7,500÷₦50,000)×100%.","₦7,500÷₦50,000=0.15.","0.15×100%=15%.","Check: 15% of ₦50,000 is ₦7,500; subtracting it gives ₦42,500, the stated SP."],answer:"15% loss"},{q:"An item costs ₦8,400 and yields ₦1,260 profit. Find the profit percentage.",steps:["The profit amount is already given.","Profit%=1,260/8,400×100%.","1,260÷8,400=0.15."],answer:"15% profit"}]},
{title:"5. Finding selling price from a profit or loss percentage",body:["Start from the relationship already established: selling at a profit means the selling price is the cost price plus the profit. Selling at a loss means the selling price is the cost price minus the loss.","If the question gives a percentage rather than the naira profit or loss, first find that percentage of CP. Only after the learner understands this should the shorter percentage multiplier be introduced."],board:["At a profit:","Profit = (profit rate ÷ 100) × CP","SP = CP + Profit","","At a loss:","Loss = (loss rate ÷ 100) × CP","SP = CP − Loss","","Shortcut after understanding:","SP at p% profit = ((100 + p) ÷ 100) × CP","SP at p% loss = ((100 − p) ÷ 100) × CP"],examples:[{q:"A bicycle costs ₦64,000. Find the selling price for a 25% profit.",steps:[{text:"A 25% profit means 25% of COST PRICE. Find the profit first.",math:["Profit = 25/100 × ₦64,000","= 1/4 × ₦64,000","= ₦16,000"]},{text:"Selling at a profit means add the profit to cost price.",math:["SP = CP + Profit","= ₦64,000 + ₦16,000","= ₦80,000"]},{text:"Now the 125% shortcut can be checked.",math:["125/100 × ₦64,000 = ₦80,000 ✓"]}],answer:"₦80,000"},{q:"A machine costs ₦150,000 and is sold at 12% loss. Find SP.",steps:["Loss=12% of ₦150,000=₦18,000.","SP=₦150,000−₦18,000=₦132,000.","Check using 88% of CP: 0.88×150,000=132,000."],answer:"₦132,000"}]},
{title:"6. Reverse profit and loss problems",body:["If selling price is known after a percentage profit or loss, the selling price represents a percentage of the original cost price. Do not simply subtract the stated percentage from SP.","At 20% profit, SP=120% of CP. At 15% loss, SP=85% of CP."],examples:[{q:"An item is sold for ₦72,000 at 20% profit. Find its cost price.",steps:["The unknown is CP, so do not begin by subtracting 20% from the selling price. The 20% profit is based on CP.","CP itself represents 100% of CP. Adding a 20% profit makes the selling price 100%+20%=120% of CP.","Therefore SP=120% of CP.","Convert 120% to decimal form: 120÷100=1.20.","Substitute the known selling price: ₦72,000=1.20×CP.","To get CP alone, divide both sides by 1.20.","CP=₦72,000÷1.20.","CP=₦60,000.","Check: 20% of ₦60,000=₦12,000 and ₦60,000+₦12,000=₦72,000."],answer:"CP = ₦60,000"},{q:"An item is sold for ₦51,000 at a 15% loss. Find CP.",steps:["At 15% loss, SP=85% of CP.","0.85×CP=₦51,000.","CP=₦51,000÷0.85=₦60,000.","Check: 15% of 60,000=9,000; 60,000−9,000=51,000."],answer:"CP = ₦60,000"}]},
{title:"7. Marked price, discount and amount paid",body:["Marked Price (MP) is the price written on the item before any reduction. Discount is the amount removed from that marked price. The amount the customer finally pays is therefore what remains after the discount is removed.","When a discount rate is given, calculate the discount from the marked price first. This makes the meaning clear before introducing any shortcut."],board:["Discount = Marked Price − Selling Price","Selling Price = Marked Price − Discount","","Discount % = (Discount ÷ Marked Price) × 100%","","If discount rate is given:","Discount = (rate ÷ 100) × Marked Price"],examples:[{q:"A ₦40,000 item has a 15% discount. Find the discount and amount paid.",steps:["Discount=15/100×₦40,000=₦6,000.","Amount paid=₦40,000−₦6,000=₦34,000."],answer:"Discount ₦6,000; amount paid ₦34,000"},{q:"A shirt marked ₦18,000 is sold for ₦15,300. Find the discount percentage.",steps:["Discount=₦18,000−₦15,300=₦2,700.","Discount%=2,700/18,000×100%=15%."],answer:"15% discount"},{q:"After a 20% discount, a customer pays ₦28,000. Find the marked price.",steps:["The marked price is unknown. Let it be MP.","A 20% discount removes 20% of MP, so the customer pays the remaining 100%−20%=80% of MP.","Convert 80% to decimal form: 80÷100=0.80.","The amount paid is ₦28,000, so write 0.80×MP=₦28,000.","To isolate MP, undo multiplication by 0.80 by dividing both sides by 0.80.","MP=₦28,000÷0.80.","MP=₦35,000.","Check: 20% of ₦35,000 is ₦7,000; ₦35,000−₦7,000=₦28,000."],answer:"Marked price = ₦35,000"}]},
{title:"8. Simple interest — understand the quantities",body:["Establish every quantity before using the formula. Principal (P) is the original amount borrowed or invested. Rate (R) tells the percentage interest for each stated time period. Time (T) tells how many of those periods the money remains borrowed or invested.","For simple interest, each year's interest is calculated on the same original principal. One year's interest is R% of P. For T years, that yearly interest is repeated T times. This is what produces the compact formula below."],board:["Interest for 1 year = (R ÷ 100) × P","Interest for T years = (R ÷ 100) × P × T","","Therefore:","I = (P × R × T) ÷ 100","","Total Amount = Principal + Interest","A = P + I"],examples:[{q:"Find simple interest on ₦50,000 at 8% per annum for 3 years.",steps:["Identify what each number represents before substituting: Principal P=₦50,000, annual Rate R=8%, and Time T=3 years.","Because the rate is per annum and the time is already in years, no time conversion is needed.","One year’s interest is 8% of ₦50,000.","Interest for 3 years is therefore that same simple-interest amount repeated for 3 years.","Use I=(P×R×T)÷100.","I=(50,000×8×3)÷100.","50,000×8×3=1,200,000.","1,200,000÷100=₦12,000.","The question also requires the amount, so add the original principal: A=P+I.","A=₦50,000+₦12,000.","A=₦62,000."],answer:"Interest ₦12,000; amount ₦62,000"},{q:"Find the simple interest on ₦120,000 at 7.5% per annum for 2 years.",steps:["I=120,000×7.5×2/100.","7.5×2=15, so this is 15% of ₦120,000.","I=₦18,000."],answer:"₦18,000"}]},
{title:"9. Time conversions in simple interest",body:["The time unit must agree with the rate. If the rate is per annum and time is given in months, convert months to years before substitution.","12 months=1 year, so m months=m/12 years."],examples:[{q:"Find simple interest on ₦80,000 at 9% per annum for 8 months.",steps:["Convert time: 8 months=8/12 year=2/3 year.","I=80,000×9×(2/3)/100.","9×2/3=6.","I=6% of ₦80,000=₦4,800."],answer:"₦4,800"},{q:"Find interest on ₦36,000 at 10% per annum for 18 months.",steps:["18 months=18/12=1.5 years.","I=36,000×10×1.5/100.","10×1.5=15%, so I=15% of 36,000."],answer:"₦5,400"}]},
{title:"10. Reverse simple-interest problems",body:["The same formula can be rearranged when principal, rate or time is unknown. Keep the meaning visible rather than memorising several disconnected formulas.","From I=PRT/100: P=100I/(RT), R=100I/(PT), and T=100I/(PR)."],examples:[{q:"₦60,000 earns ₦9,000 simple interest in 3 years. Find the annual rate.",steps:["I=PRT/100.","9,000=60,000×R×3/100.","60,000×3/100=1,800, so 9,000=1,800R.","R=9,000÷1,800=5."],answer:"5% per annum"},{q:"At 6% simple interest, how long will ₦40,000 take to earn ₦7,200?",steps:["7,200=40,000×6×T/100.","40,000×6/100=2,400.","7,200=2,400T.","T=3 years."],answer:"3 years"}]},
{title:"11. Commission",body:["Commission is a payment earned for making sales or completing specified transactions. Before calculating, identify the sales value and the commission rate.","A rate of 5% means the salesperson receives 5 out of every 100 units of the sales value. That meaning gives the formula. If there is also a fixed salary, calculate commission separately and add it only when total earnings are requested."],board:["Commission = (Commission rate ÷ 100) × Total sales","","If fixed salary is also paid:","Total earnings = Fixed salary + Commission"],examples:[{q:"A salesperson earns 5% commission on ₦280,000 sales. Find commission.",steps:["Commission=5/100×₦280,000.","=0.05×₦280,000=₦14,000."],answer:"₦14,000"},{q:"A salesperson receives ₦45,000 salary plus 4% commission on ₦600,000 sales. Find total earnings.",steps:["Commission=4% of ₦600,000=₦24,000.","Total earnings=salary+commission=₦45,000+₦24,000."],answer:"₦69,000"},{q:"A salesperson earned ₦18,000 commission at 6%. Find the sales value.",steps:["0.06×sales=₦18,000.","sales=18,000÷0.06=₦300,000."],answer:"₦300,000"}]},
{title:"12. Multi-step commercial reasoning",body:["Real commercial questions often combine two or more ideas. Work in the order events occur and keep each base quantity clear.","A discount changes what the buyer pays; profit compares selling price with cost price. Those percentages may use different bases."],examples:[{q:"A trader buys an item for ₦48,000, marks it at ₦75,000 and gives a 20% discount. Find the actual selling price and profit percentage.",steps:["There are two different percentage bases here, so handle the events in order.","The discount is based on the marked price, ₦75,000.","Discount=(20÷100)×₦75,000.","Discount=₦15,000.","Subtract the discount from the marked price to obtain the actual selling price.","Actual SP=₦75,000−₦15,000.","Actual SP=₦60,000.","Now compare this selling price with the trader’s cost price of ₦48,000.","Profit=SP−CP=₦60,000−₦48,000.","Profit=₦12,000.","Profit percentage is based on CP, not marked price.","Profit %=(₦12,000÷₦48,000)×100%.","Profit %=25%."],answer:"SP ₦60,000; profit 25%"},{q:"A trader wants 20% profit after giving a 10% discount. If CP=₦45,000, what marked price is needed?",steps:["Required SP for 20% profit=120% of ₦45,000=₦54,000.","A 10% discount means actual SP is 90% of marked price.","0.90×MP=₦54,000.","MP=₦54,000÷0.90=₦60,000.","Check: 10% discount on 60,000 is 6,000, leaving 54,000."],answer:"Marked price = ₦60,000"}]},
{title:"13. Mastery and reasonableness checks",body:["Before accepting an answer, ask whether its direction makes sense: a discounted price should be below marked price; a selling price at a profit should be above cost price; a loss selling price should be below cost price; interest should reflect principal, rate and time.","A learner is ready when the unknown can move position—profit, CP, SP, rate, time, discount, marked price or commission—and the learner can reconstruct the relationship instead of depending on one memorised question form."]}],mistakes:["Do not calculate profit or loss before identifying CP and SP.","Profit/loss percentage normally uses cost price as its base.","Discount percentage uses marked price as its base.","Discount is the reduction, not the final amount paid.","A reverse percentage problem cannot usually be solved by simply subtracting the percentage from the final value.","For simple interest, make the time unit agree with the rate.","Amount in simple interest means principal plus interest.","Commission may need to be added to fixed salary when total earnings are requested.","In multi-step questions, identify which percentage applies to which base before calculating."]},
"Approximation":{title:"Approximation",objectives:["Explain approximation and distinguish an exact value from an approximate value","Round whole numbers and decimals to a stated place value or number of decimal places","Round numbers to a stated number of significant figures","Handle zeros and carrying correctly when rounding","Choose a suitable degree of accuracy from context","Estimate calculations and use approximation to check reasonableness","Solve quantitative aptitude problems involving decimal places and significant figures"],sections:[
{title:"1. Exact and approximate values",body:["An exact value is stated without deliberate rounding. An approximate value is close to the exact value but has been rounded or estimated to a chosen degree of accuracy.","The symbol = means exactly equal. The symbol ≈ means approximately equal. Approximation is useful when an exact value is unnecessary, unavailable or inconvenient."],examples:[{q:"A calculator gives 17.8462. Write this approximately to one decimal place.",steps:["One decimal place means keep the tenths digit.","In 17.8462, the tenths digit is 8.","The next digit, the hundredths digit, is 4.","Because 4 is below 5, keep 8 unchanged."],answer:"17.8462 ≈ 17.8"},{q:"Explain why 1/3 = 0.333... but 1/3 ≈ 0.33 to 2 decimal places.",steps:["0.333... continues indefinitely, so it represents the exact decimal value of 1/3.","0.33 stops after two decimal places.","Therefore 0.33 is a rounded approximation, not an exact equality."],answer:"Use ≈ for the rounded value: 1/3 ≈ 0.33"}]},
{title:"2. The rounding decision: keep one digit, inspect the next",body:["First locate the digit required by the question. That is the last digit you intend to keep. Then inspect the digit immediately to its right.","Why inspect that next digit? It tells us which neighbouring rounded value the original number is nearer to. Under the school convention, 0–4 leaves the retained digit at the lower choice, while 5–9 means the number has reached or passed halfway and the retained digit increases.","If the next digit is 0,1,2,3 or 4, the kept digit stays unchanged. If it is 5,6,7,8 or 9, increase the kept digit by 1. Digits after the rounding position are then removed or replaced by zeros when place value requires them."],board:["Every rounding question","1. Read the accuracy requested.","2. Locate the LAST digit that must remain.","3. Inspect the ONE digit immediately to its right.","4. 0–4: keep the retained digit unchanged.","5. 5–9: increase the retained digit by 1.","6. Remove later digits or replace them with place-value zeros.","7. Check that the answer is written to the requested accuracy."],examples:[{q:"Round 6,342 to the nearest hundred.",steps:["The question asks for the nearest hundred, so first locate the hundreds place. That is the last place allowed to remain exact.","The hundreds digit is 3. The digit immediately to its right is the tens digit, 4; this is the deciding digit.","Because 4 is below 5, the original number is closer to the lower hundred than the next hundred. Keep 3 unchanged.","Digits to the right no longer show exact tens or units, so replace them with zeros to preserve place value.","Read the final rounded number and check that it is a multiple of 100."],answer:"6,300"},{q:"Round 6,372 to the nearest hundred.",steps:["The hundreds digit is 3.","The next digit is 7.","7≥5, so increase 3 to 4.","Replace the remaining digits with zeros."],answer:"6,400"},{q:"Round 2,650 to the nearest hundred.",steps:["Keep the hundreds digit 6.","The tens digit is 5.","Using the school rounding convention, 5 rounds upward.","Increase 6 to 7 and replace the remaining places with zeros."],answer:"2,700"}]},
{title:"3. Rounding whole numbers to place value",body:["Questions may ask for the nearest ten, hundred, thousand or another place value. The same decision rule applies; what changes is the digit being kept.","Zeros after the rounded digit are important placeholders. 48,000 and 48 are completely different values."],examples:[{q:"Round 47,286 to the nearest ten.",steps:["The tens digit is 8.","Inspect the units digit 6.","6≥5, so 8 rounds to 9.","Replace the units digit with zero."],answer:"47,290"},{q:"Round 47,286 to the nearest thousand.",steps:["The thousands digit is 7.","Inspect the hundreds digit 2.","2<5, so keep 7.","Replace hundreds, tens and units with zeros."],answer:"47,000"},{q:"Round 685,499 to the nearest ten thousand.",steps:["The ten-thousands digit is 8.","Inspect the thousands digit 5.","5≥5, so increase 8 to 9.","Replace all following places with zeros."],answer:"690,000"}]},
{title:"4. Decimal places: count from the decimal point",body:["Decimal places (d.p.) count digits to the right of the decimal point. For 18.3764, 3 is the first decimal place, 7 the second, 6 the third and 4 the fourth.","Do not count digits before the decimal point when a question asks for decimal places."],examples:[{q:"Round 18.3764 to 2 decimal places.",steps:[{text:"Two decimal places means keep exactly two digits after the decimal point. Separate the retained part from the digits that will be discarded.",math:["18.37 | 64","     ↑ hundredths"]},{text:"The first digit after the divider is 6. Because 6≥5, increase the retained hundredths digit 7 by 1.",math:["7 + 1 = 8"]},{text:"Now discard the remaining digits and write the rounded value.",math:["18.3764 ≈ 18.38"]}],answer:"18.38"},{q:"Round 5.2431 to 3 decimal places.",steps:["Keep 5.243.","Inspect the fourth decimal digit 1.","1<5, so 3 stays unchanged."],answer:"5.243"},{q:"Round 0.008764 to 4 decimal places.",steps:["Count four places after the decimal: 0.0087.","The next digit is 6.","Increase the fourth decimal digit 7 to 8."],answer:"0.0088"}]},
{title:"5. Decimal rounding when carrying occurs",body:["Sometimes rounding a 9 upward creates 10. Then the extra 1 must carry into the digit to the left, just as in ordinary addition.","This may cross the decimal point and can even change the whole-number part."],examples:[{q:"Round 7.996 to 2 decimal places.",steps:["Keep 7.99 initially.","The next digit is 6, so the hundredths 9 must increase.","9+1=10, so write 0 and carry 1 to the tenths 9.","That 9 also becomes 10, so carry 1 to the units digit 7."],answer:"8.00"},{q:"Round 19.9952 to 2 decimal places.",steps:["Keep 19.99.","The next digit is 5, so round upward.","The two 9s carry through into the whole-number part.","Because the answer is required to 2 d.p., retain two decimal-place zeros."],answer:"20.00"}]},
{title:"6. What significant figures mean",body:["Significant figures (s.f.) count meaningful digits beginning with the first non-zero digit. This is different from decimal places, which begin immediately after the decimal point.","Leading zeros only locate the decimal point and are not significant. Zeros between non-zero digits are significant. Trailing zeros may be significant when the stated accuracy makes them part of the rounded value."],examples:[{q:"Identify the first three significant digits in 0.004072.",steps:["Ignore leading zeros before 4.","The first significant digit is 4.","The zero between 4 and 7 is significant, so it is the second.","7 is the third significant digit."],answer:"The first three significant digits are 4, 0, 7"},{q:"How many significant figures are shown in 5.060?",steps:["5 is significant.","The zero between 5 and 6 is significant.","6 is significant.","The final zero after the decimal is written to show precision, so it is significant."],answer:"5.060 shows 4 significant figures"}]},
{title:"7. Rounding decimals to significant figures",body:["Locate the first non-zero digit, count the required number of significant digits from there, then inspect the next digit.","A small number may have many decimal places but only a few significant figures because its leading zeros do not count."],examples:[{q:"Round 0.006482 to 2 significant figures.",steps:["Ignore the leading zeros.","The first significant digit is 6 and the second is 4.","The next digit is 8, so round 4 upward to 5.","Keep the decimal position unchanged."],answer:"0.0065"},{q:"Round 0.040759 to 3 significant figures.",steps:["The first non-zero digit is 4.","Count 4,0,7 as the first three significant digits.","The next digit is 5, so 7 rounds to 8."],answer:"0.0408"},{q:"Round 3.14159 to 4 significant figures.",steps:["The first four significant digits are 3,1,4,1.","The next digit is 5.","Increase the fourth significant digit from 1 to 2."],answer:"3.142"}]},
{title:"8. Rounding large numbers to significant figures",body:["For large whole numbers, count significant figures from the first non-zero digit on the left. After rounding, replace unused place-value positions with zeros.","Those zeros preserve the size of the number even when they are not counted as additional significant figures in the stated approximation."],examples:[{q:"Round 53,782 to 2 significant figures.",steps:["The first two significant digits are 5 and 3.","The next digit is 7, so 3 rounds to 4.","The remaining positions become zeros."],answer:"54,000"},{q:"Round 704,621 to 3 significant figures.",steps:["The first three significant digits are 7,0,4.","The next digit is 6, so increase 4 to 5.","Replace the remaining digits with zeros."],answer:"705,000"},{q:"Round 9,965,000 to 3 significant figures.",steps:["The first three significant digits are 9,9,6.","The next digit is 5, so 6 rounds to 7.","Retain the correct million-scale place values."],answer:"9,970,000"}]},
{title:"9. Decimal places versus significant figures",body:["The same number can produce different answers depending on whether the instruction says decimal places or significant figures. Always read the requested accuracy before rounding.","For numbers below 1, this distinction is especially important because leading zeros count as decimal places but not as significant figures."],examples:[{q:"Round 0.004786 to 3 decimal places and to 3 significant figures.",steps:["For 3 d.p., keep three digits after the decimal: 0.004. The next digit is 7, so round the third decimal digit 4 to 5: 0.005.","For 3 s.f., ignore leading zeros and count 4,7,8. The next digit is 6, so 8 rounds to 9.","The two instructions measure accuracy differently."],answer:"3 d.p.: 0.005; 3 s.f.: 0.00479"},{q:"Round 12.468 to 2 d.p. and 2 s.f.",steps:["For 2 decimal places, count two digits to the right of the decimal point. The last retained digit is 6 in 12.46.","Inspect the next digit, 8. Since 8≥5, increase 6 to 7. This gives 12.47.","Now start again from the original number for 2 significant figures.","Significant figures begin at the first non-zero digit. In 12.468, the first two significant digits are 1 and 2.","Inspect the next significant digit, 4. Since 4<5, keep the 2 unchanged.","Digits after the retained units digit are removed, so the 2-s.f. value is 12.","The two answers differ because decimal places and significant figures measure accuracy in different ways."],answer:"2 d.p.: 12.47; 2 s.f.: 12"}]},
{title:"10. Choosing a sensible degree of accuracy",body:["The required accuracy should suit the context. Reporting a classroom length measured with an ordinary tape to ten decimal places would suggest a precision the measurement does not have.","When a question explicitly states the required accuracy, follow it. When it does not, consider the measuring instrument and purpose."],examples:[{q:"A road distance is measured as 12,684 m. Express it to the nearest kilometre.",steps:["1 km=1,000 m.","12,684 m=12.684 km.","To the nearest kilometre, inspect the tenths digit 6.","6≥5, so 12 km rounds to 13 km."],answer:"13 km"},{q:"A mass is 4.376 kg. Give it to the nearest 0.1 kg.",steps:["Nearest 0.1 kg means one decimal place.","Keep 4.3 and inspect the hundredths digit 7.","Round the tenths digit upward."],answer:"4.4 kg"}]},
{title:"11. Estimating calculations",body:["Approximation can make a difficult calculation quick enough to perform mentally. Round each number to convenient values, calculate the estimate, and clearly label it as an estimate.","An estimate is especially useful before an exact calculation because it provides a benchmark for detecting calculator or transcription errors."],examples:[{q:"Estimate 49.8 × 19.7.",steps:["Round 49.8≈50 and 19.7≈20.","50×20=1,000.","Because both rounded values are close to the originals, 1,000 is a sensible estimate."],answer:"Approximately 1,000"},{q:"Estimate 598 ÷ 19.8.",steps:["Use convenient nearby values: 598≈600 and 19.8≈20.","600÷20=30."],answer:"Approximately 30"},{q:"Estimate (31.2×4.9)/10.1.",steps:["Round to convenient values: 31.2≈30, 4.9≈5, 10.1≈10.","30×5=150.","150÷10=15."],answer:"Approximately 15"}]},
{title:"12. Using estimation to check an answer",body:["If an exact calculation is very far from a sensible estimate, investigate before accepting it. The estimate does not prove the exact answer, but it can expose misplaced decimal points and unreasonable calculator entries.","Compare orders of magnitude as well as the digits."],examples:[{q:"A learner calculates 39.7×5.1=2,024.7. Use approximation to assess the answer.",steps:["39.7≈40 and 5.1≈5.","40×5=200.","An exact answer should be near 200, not near 2,000.","The learner's answer is therefore unreasonable.","Indeed, 39.7×5.1=202.47."],answer:"2,024.7 is unreasonable; the correct value is 202.47"},{q:"A calculator entry gives 802÷3.98=20.15. Is this reasonable?",steps:["802≈800 and 3.98≈4.","800÷4=200.","20.15 is about ten times too small, so it is not reasonable."],answer:"No; the answer should be around 200"}]},
{title:"13. Quantitative aptitude: work backwards from a rounded value",body:["A rounded answer represents a range of possible original values. For whole-number rounding, values up to halfway below and halfway above the rounded value belong to that rounding interval, with the upper endpoint excluded under the usual convention.","This reasoning tests whether the learner understands approximation rather than merely performing it."],examples:[{q:"A whole number rounds to 3,500 to the nearest hundred. Give the smallest and largest possible whole numbers.",steps:["Half of 100 is 50.","Numbers from 3,450 round up to 3,500.","The next boundary is 3,550, which rounds to 3,600.","Therefore the largest whole number still rounding to 3,500 is 3,549."],answer:"Smallest 3,450; largest 3,549"},{q:"A measurement rounds to 7.4 cm to the nearest 0.1 cm. Describe its possible range.",steps:["Half of 0.1 is 0.05.","Lower boundary=7.4−0.05=7.35.","Upper boundary=7.4+0.05=7.45.","7.45 itself would round to 7.5 under the usual convention, so the upper boundary is not included."],answer:"7.35 cm ≤ value < 7.45 cm"}]},
{title:"14. Mixed approximation reasoning",body:["Exam questions may combine place value, decimal places, significant figures and estimation. First identify what the instruction measures, then apply the correct method.","A strong learner should also be able to explain why two different stated accuracies produce different approximations of the same number."],examples:[{q:"A population is recorded as 486,739. Give it to the nearest thousand and to 2 significant figures.",steps:["Nearest thousand: keep 486 thousand and inspect 739; the hundreds digit is 7, so round to 487,000.","For 2 s.f., keep 4 and 8; the next digit is 6, so 48 rounds to 49.","Restore place value: 490,000."],answer:"Nearest thousand: 487,000; 2 s.f.: 490,000"},{q:"A learner says 0.00795 to 2 s.f. is 0.0079. Correct the reasoning.",steps:["Ignore leading zeros; significant digits begin at 7.","The first two significant digits are 7 and 9.","The next digit is 5, so the second significant digit must round upward.","Rounding 9 upward causes carrying: 79 becomes 80 at this place."],answer:"0.00795 ≈ 0.0080 to 2 significant figures"}]},
{title:"15. Mastery standard",body:["You have mastered approximation when you can identify the required accuracy, locate the correct rounding digit, handle zeros and carrying, distinguish decimal places from significant figures, estimate calculations, judge reasonableness and solve reverse or mixed approximation problems.","Do not treat the rule '5 or more, round up' as the whole topic. The real skill is knowing which digit is being kept, what its place value means, and whether the resulting approximation makes sense."]}],mistakes:["Do not confuse an exact equality (=) with an approximation (≈).","For decimal places, count from the decimal point; for significant figures, begin at the first non-zero digit.","Leading zeros are not significant figures.","Zeros between non-zero digits are significant.","When rounding a whole number, preserve its place value with zeros.","If a 9 rounds upward, carry correctly into the digit to the left.","Do not give an estimate as though it were an exact answer.","When checking a calculation, an answer far from a sensible estimate should be investigated.","Always read whether the question asks for a place value, decimal places or significant figures before rounding."]},
"Multiplication and Division of Directed Numbers":{title:"Multiplication and Division of Directed Numbers",objectives:["Explain directed numbers as quantities with both size and direction","Interpret positive and negative values in practical situations","Derive and use the sign rules for multiplication of directed numbers","Derive and use the sign rules for division of directed numbers","Evaluate expressions containing several directed-number factors or quotients","Use square and square-root tables correctly and check table values for reasonableness","Interpret mathematical information in tables, charts, records and schedules","Solve quantitative and real-life problems involving directed numbers"],sections:[
{title:"1. Foundation: a number can tell us size and direction",body:["A directed number has two pieces of information: its numerical size and its direction from zero. The + or − sign tells us the direction.","In everyday situations, positive may represent a rise, deposit, height above a reference point or movement in one chosen direction. Negative may represent a fall, debt, depth below a reference point or movement in the opposite direction.","The meaning depends on the reference chosen in the question, so read the context before calculating."],board:["+6  means 6 units in the positive direction","−6  means 6 units in the negative direction","","On a number line:","← negative values     0     positive values →"],examples:[{q:"A lift is 4 floors below ground level. Represent its position as a directed number.",steps:["Take ground level as 0.","Below ground is the negative direction.","Four floors below ground is therefore −4."],answer:"−4"},{q:"A bank account changes by a deposit of ₦7,500 and later a withdrawal of ₦2,000. Represent the two changes.",steps:["A deposit increases the balance, so represent it by a positive number: +₦7,500.","A withdrawal decreases the balance, so represent it by a negative number: −₦2,000."],answer:"+₦7,500 and −₦2,000"}]},
{title:"2. Prerequisite bridge: moving with directed numbers",body:["Before multiplying and dividing directed numbers, recall how positive and negative changes behave on a number line. This foundation prevents sign rules from becoming disconnected facts.","Adding a positive number moves to the right; adding a negative number moves to the left. Subtracting a positive moves left. Subtracting a negative reverses that direction and is equivalent to adding the corresponding positive number."],board:["Add +a  → move right a units","Add −a  → move left a units","Subtract +a → move left a units","Subtract −a → move right a units"],examples:[{q:"Evaluate (−4)+(+9).",steps:["Start at −4.","Adding +9 means move 9 units to the right.","You arrive at +5."],answer:"+5"},{q:"Evaluate 6−(−3).",steps:["Start at +6.","Subtracting a negative reverses the negative movement.","So 6−(−3)=6+3.","Move 3 units right from 6."],answer:"+9"},{q:"Evaluate (−5)+(−4)−(−3).",steps:["Start with −5.","Add −4: move 4 units left to −9.","Subtract −3: move 3 units right.","−9+3=−6."],answer:"−6"}]},
{title:"3. Before multiplying: separate magnitude from sign",body:["When multiplying directed numbers, first calculate the magnitude using the ordinary multiplication facts you already know. Then determine the sign of the product.","For example, in (−4)×(+3), the magnitudes are 4 and 3, so the magnitude of the product is 12. The remaining question is whether that 12 is positive or negative. We establish that sign rule next.","We are not throwing the signs away. We are separating two jobs so the learner can see them: ordinary multiplication determines the size; the directed signs determine the direction of that size."],board:["For every directed-number multiplication","1. Read the sign of EACH factor.","2. Multiply the magnitudes to find the size.","3. Decide the sign from the sign relationship.","4. Attach that sign to the magnitude.","5. Check that the result follows the sign rule already established."],examples:[{q:"What is the magnitude of (−8)×(+7) before deciding its sign?",steps:["Ignore the signs only for the magnitude step.","8×7=56.","Now keep 56 ready while the sign is determined."],answer:"Magnitude = 56"}]},
{title:"3. Why positive × negative is negative",body:["Multiplication can represent repeated equal changes. Three groups of a change of −4 means the negative change occurs three times.","That gives (−4)+(−4)+(−4)=−12. Therefore a positive number of groups of a negative quantity gives a negative product."],board:["(+3) × (−4)","= (−4) + (−4) + (−4)","= −12","","So:  positive × negative = negative"],examples:[{q:"Calculate (+5)×(−6).",steps:["The magnitude is 5×6=30.","Five groups of −6 move 6 units negatively five times.","Therefore the product has a negative sign."],answer:"(+5)×(−6)=−30"},{q:"A temperature changes by −2°C each hour for 6 hours. What is the total change?",steps:["Each hourly change is −2°C.","There are 6 equal changes, so calculate 6×(−2).","Magnitude: 6×2=12.","Positive number of negative changes gives a negative result."],answer:"Total change = −12°C"}]},
{title:"4. Why negative × positive is negative",body:["The order of factors does not change a product. Since (+3)×(−4)=−12, reversing the factors gives (−4)×(+3)=−12.","You can also see the pattern by decreasing the first factor one step at a time while multiplying by +3."],board:["(+2)×(+3)=+6","(+1)×(+3)=+3","0×(+3)=0","(−1)×(+3)=−3","(−2)×(+3)=−6","","So:  negative × positive = negative"],examples:[{q:"Calculate (−9)×(+4).",steps:["Multiply magnitudes: 9×4=36.","The signs are different: negative and positive.","Different signs give a negative product."],answer:"−36"},{q:"Evaluate −15×3.",steps:["Read both factors before calculating. One factor is negative and the other is positive, so their signs are different.","First find the magnitude using ordinary multiplication: 15×3=45.","Now determine direction. The established sign rule says different signs give a negative product.","Attach the negative sign to the magnitude 45.","Therefore the product is −45. As a check, this agrees with the negative×positive pattern already derived."],answer:"−45"}]},
{title:"5. Why negative × negative is positive",body:["This rule should not appear as something to memorise without reason. Continue a multiplication pattern while the first factor decreases by 1.","Each line below must decrease by the same amount. Because the second factor is −3, decreasing the first factor by 1 makes the product increase by 3. The pattern therefore passes from 0 to positive values."],board:["(+2)×(−3)=−6","(+1)×(−3)=−3","0×(−3)=0","(−1)×(−3)=+3","(−2)×(−3)=+6","","Therefore:  negative × negative = positive"],examples:[{q:"Calculate (−7)×(−8).",steps:["Multiply magnitudes: 7×8=56.","Both factors have the same negative sign.","Negative × negative gives a positive product."],answer:"+56"},{q:"Evaluate (−12)(−5).",steps:["Brackets written side by side mean multiplication.","Magnitude: 12×5=60.","Both signs are negative, so the product is positive."],answer:"60"}]},
{title:"6. Multiplication sign rules — now state the complete rule",body:["Only after seeing why the cases behave as they do do we collect them into one rule. Same signs give a positive product; different signs give a negative product.","The sign rule does not replace multiplication. Determine the sign and still multiply the magnitudes accurately."],board:["(+ ) × (+ ) = +","(+ ) × (− ) = −","(− ) × (+ ) = −","(− ) × (− ) = +","","Same signs → positive","Different signs → negative"],examples:[{q:"Evaluate (−14)×(+6).",steps:[{text:"Decide the sign first. The factors have different signs, so the product is negative.",math:["(−) × (+) = (−)"]},{text:"Now multiply the magnitudes.",math:["14 × 6 = 84"]},{text:"Attach the sign already determined.",math:["(−14) × (+6)","= −84"]}],answer:"−84"},{q:"Evaluate (−25)×(−4).",steps:["Signs are the same, so the answer is positive.","25×4=100."],answer:"+100"},{q:"Evaluate (+18)×(+7).",steps:["Both signs are positive, so the product is positive.","18×7=126."],answer:"+126"}]},
{title:"7. Division is the inverse of multiplication",body:["Division asks a multiplication question in reverse. For example, 24÷6 asks: 6 multiplied by what number gives 24?","We use that inverse relationship to establish the signs in division rather than introducing another unexplained table of rules."],board:["24 ÷ 6 = 4  because  6 × 4 = 24","","For directed numbers:","Dividend ÷ Divisor = Quotient","because","Divisor × Quotient = Dividend"],examples:[{q:"Find −24÷(+6) by thinking backwards.",steps:["Ask: (+6) multiplied by what number gives −24?","6×4 has magnitude 24.","To make the product negative, the missing factor must be negative.","(+6)×(−4)=−24."],answer:"−24÷(+6)=−4"},{q:"Find −35÷(−7) by thinking backwards.",steps:["Ask: (−7) multiplied by what number gives −35?","7×5=35.","A negative product from −7 requires a positive second factor.","(−7)×(+5)=−35."],answer:"−35÷(−7)=+5"}]},
{title:"8. Division sign rules — derived from multiplication",body:["Because division reverses multiplication, it follows the same sign pattern: same signs give a positive quotient and different signs give a negative quotient.","Always divide the magnitudes as well as determining the sign."],board:["(+ ) ÷ (+ ) = +","(+ ) ÷ (− ) = −","(− ) ÷ (+ ) = −","(− ) ÷ (− ) = +","","Same signs → positive","Different signs → negative"],examples:[{q:"Evaluate −84÷12.",steps:["The signs are different, so the quotient is negative.","84÷12=7."],answer:"−7"},{q:"Evaluate −84÷(−12).",steps:["The signs are the same, so the quotient is positive.","84÷12=7."],answer:"+7"},{q:"Evaluate 144÷(−9).",steps:["The signs are different, so the answer is negative.","144÷9=16."],answer:"−16"}]},
{title:"9. More than two factors: determine the final sign carefully",body:["For several factors, work from left to right or count negative factors. Every pair of negative factors contributes a positive sign.","An even number of negative factors gives a positive product. An odd number gives a negative product. This shortcut comes from repeatedly applying the two-factor rule."],board:["Two negative factors → positive","Three negative factors → negative","Four negative factors → positive","","Even number of negative factors → +","Odd number of negative factors → −"],examples:[{q:"Evaluate (−2)×(−3)×(+5).",steps:[{text:"Work from left to right. Decide the sign of the first pair, then multiply their magnitudes.",math:["(−2)×(−3)","same signs → positive","2×3 = 6","= +6"]},{text:"Replace the first pair by +6 and continue.",math:["(+6)×(+5)","same signs → positive","6×5 = 30","= +30"]},{text:"Check the overall sign.",math:["2 negative factors → even → positive ✓"]}],answer:"+30"},{q:"Evaluate (−2)×(−3)×(−4).",steps:["First: (−2)×(−3)=+6.","Then: +6×(−4)=−24.","There are three negative factors, an odd number, so the final sign is negative."],answer:"−24"},{q:"Evaluate (−120)÷(−5)÷(−3).",steps:[{text:"Division operations have equal priority, so work from left to right.",math:["(−120) ÷ (−5)","same signs → positive","120 ÷ 5 = 24","= +24"]},{text:"Now divide the result by −3.",math:["(+24) ÷ (−3)","different signs → negative","24 ÷ 3 = 8","= −8"]}],answer:"−8"}]},
{title:"10. Brackets and operation order",body:["Brackets help show which signed numbers belong together. A negative sign attached to a number is part of that number.","When an expression contains several operations, calculate multiplication and division before addition and subtraction unless brackets require another order."],board:["Brackets first","Then multiplication and division","Then addition and subtraction"],examples:[{q:"Evaluate 8+(−3)×4.",steps:[{text:"Multiplication has higher priority, so calculate the product first.",math:["(−3) × (+4)","different signs → negative","3 × 4 = 12","= −12"]},{text:"Put that result back into the original expression.",math:["8 + (−12)","= 8 − 12","= −4"]}],answer:"−4"},{q:"Evaluate (−18÷3)×(−2).",steps:["Work inside the bracket: −18÷3=−6.","Then multiply: (−6)×(−2).","Same signs give positive; 6×2=12."],answer:"+12"}]},
{title:"11. Directed numbers in records and schedules",body:["The curriculum also expects learners to interpret information from tables, charts, records and schedules. First read the heading, unit and reference point. Then decide what positive and negative values mean in that particular record.","Do not invent a sign meaning. A negative temperature, negative balance change and negative height may all use the same symbol but describe different situations."],examples:[{q:"A temperature record shows −4°C at 6 a.m. and +8°C at noon. Find the rise.",steps:["Initial temperature=−4°C.","Final temperature=+8°C.","Change=final−initial.","=8−(−4).","Subtracting a negative gives 8+4=12."],answer:"Temperature rose by 12°C"},{q:"A record shows changes of +₦5,000, −₦2,500, −₦1,000 and +₦3,000. Find the net change.",steps:["Add positive changes: ₦5,000+₦3,000=₦8,000.","Add the magnitudes of negative changes: ₦2,500+₦1,000=₦3,500.","Net change=₦8,000−₦3,500=+₦4,500."],answer:"Net increase = ₦4,500"}]},
{title:"12. Interpreting a table before calculating",body:["A table organises information in rows and columns. Locate the correct row and column and check the unit before using a value.","When comparing two entries, decide whether the question asks for a difference, total, rate, product or quotient."],examples:[{q:"A store record shows Monday change −6 units, Tuesday +9 units, Wednesday −3 units and Thursday +12 units. What is the total change?",steps:["Write the directed sum: −6+9−3+12.","−6+9=+3.","+3−3=0.","0+12=+12."],answer:"Total change = +12 units"},{q:"A machine loses 4 units of value each month for 7 months. Represent the total change.",steps:["Each month is a change of −4 units.","Seven months means seven equal negative changes.","7×(−4)=−28."],answer:"Total change = −28 units"}]},
{title:"13. Squares and square roots: recall before using a table",body:["The curriculum includes obtaining squares and square roots from tables. A table is a lookup tool; it does not replace the meaning already learned.","A square means multiplying a number by itself. A square root reverses that operation. Knowing this lets you detect a wrong table entry or a value read from the wrong row."],board:["Square:  a² = a × a","","Square root:","If a² = b, then √b = a  for the positive root used here"],examples:[{q:"Before using a table, estimate where √50 should lie.",steps:["7²=49 and 8²=64.","50 lies between 49 and 64.","Therefore √50 must lie between 7 and 8.","Any table value outside that interval must have been read incorrectly."],answer:"7 < √50 < 8"},{q:"A table gives √144. What exact value should you expect?",steps:["Recall that 12×12=144.","Therefore 144 is a perfect square.","Its positive square root is exactly 12."],answer:"√144=12"}]},
{title:"14. How to use a square or square-root table",body:["Printed mathematical tables differ slightly in layout, so follow the headings of the actual table provided. The general method is stable: identify the number required, locate its row and column according to the table headings, read the corresponding value, then check whether its size is reasonable.","If the table gives an approximate decimal, copy only the precision required by the question and do not pretend the table value is exact when it has been rounded."],board:["1. Identify the number required.","2. Read the table headings.","3. Locate the correct row/column.","4. Read the square or square-root entry.","5. Check its size using known nearby squares."],examples:[{q:"A square-root table gives √70≈8.367. How can you quickly check the entry?",steps:["8²=64 and 9²=81.","Since 70 lies between 64 and 81, √70 must lie between 8 and 9.","8.367 lies between 8 and 9, so its size is reasonable.","A more precise multiplication check would give a value close to 70."],answer:"The table value is reasonable"},{q:"A learner reads √35 as 6.42 from a table. Show why the reading must be wrong.",steps:["5²=25 and 6²=36.","Since 35 is below 36, √35 must be below 6.","6.42 is above 6, so it cannot be √35.","The learner should return to the table headings and locate the correct entry."],answer:"6.42 is impossible for √35"}]},
{title:"15. Quantitative reasoning: choose the operation from the situation",body:["A directed-number problem may not tell you to multiply or divide. Look for repeated equal changes when multiplication is appropriate, or ask how many equal signed groups are contained in a total when division is appropriate.","Translate the words into a directed-number statement before calculating."],examples:[{q:"A diver descends 3 m each minute for 8 minutes. Represent the total change in position.",steps:["Choose upward as positive, so downward is negative.","Each minute's change is −3 m.","Eight equal changes give 8×(−3).","Magnitude=8×3=24; signs give a negative result."],answer:"−24 m"},{q:"A total change of −42 points occurred equally over 6 rounds. Find the change per round.",steps:["Total directed change=−42.","Six equal rounds means divide by +6.","−42÷+6 has different signs, so the quotient is negative.","42÷6=7."],answer:"−7 points per round"},{q:"A debt changes by −₦2,500 each week for 4 weeks. What directed change does this represent?",steps:["Each weekly change is −₦2,500.","Four equal changes: 4×(−₦2,500).","Magnitude=₦10,000 and the direction is negative."],answer:"−₦10,000"}]},
{title:"16. Mixed mastery: explain, calculate and check",body:["Mastery means more than reciting 'same signs positive'. You should be able to explain why the sign rule applies, calculate the magnitude correctly, interpret the result in context and reverse the operation to check it.","For division, multiply the quotient by the divisor to see whether you recover the dividend. For multiplication, divide the product by one non-zero factor to recover the other."],examples:[{q:"A learner says (−48)÷(−6)=−8 because 'the number being divided is negative.' Correct the reasoning.",steps:["The sign of only one number does not determine the quotient.","Division uses both signs.","The dividend −48 and divisor −6 have the same sign.","Same signs in division give a positive quotient.","48÷6=8.","Check: (−6)×(+8)=−48."],answer:"(−48)÷(−6)=+8"},{q:"Evaluate (−5)×(+4)×(−3) and verify.",steps:["First (−5)×(+4)=−20.","Then (−20)×(−3)=+60.","Check by reversing the last multiplication: +60÷(−3)=−20, which matches the intermediate result."],answer:"+60"}]}
],mistakes:["Do not treat the sign as decoration; it carries direction.","Do not use addition/subtraction sign rules as though they were multiplication rules.","Establish the sign rule before relying on it: same signs give positive, different signs give negative for multiplication and division.","When several factors occur, do not lose a negative sign between steps.","Work multiplication and division in the correct order when other operations are present.","Read headings and units before interpreting tables, charts, records or schedules.","A square/square-root table is a lookup tool; check table entries against nearby known squares.","Do not report a rounded table value as exact.","In a word problem, define what positive and negative directions mean before calculating."]},
"Algebraic Expressions":{title:"Algebraic Expressions",objectives:["Explain variables, constants, coefficients, terms, factors and like terms","Translate words and number patterns into algebraic expressions","Simplify expressions by collecting like terms correctly","Expand algebraic expressions using the distributive law","Expand products of two binomials systematically","Factorise expressions by identifying the highest common numerical and algebraic factor","Connect expansion and factorisation as inverse processes","Use an area/quadratic box to organise products and simple quadratic expressions","Simplify algebraic fractions with monomial denominators by cancelling factors only","Substitute given values into expressions and evaluate accurately","Model JSS2 word and quantitative-reasoning problems algebraically","Check algebraic work by re-expansion or substitution"],sections:[
{title:"1. Foundation: algebra is arithmetic with quantities we may not yet know",body:["Arithmetic works with known numbers. Algebra lets a letter stand for a number that may be unknown, changing, or simply more convenient to describe with a symbol.","A letter does not mean 'nothing'. If x represents a number, every legal arithmetic rule still applies to x. For example, 3x means 3 multiplied by x; it does not mean 3+x.","Before manipulating an expression, learn to read what each part means."],board:["x = a variable","7 = a constant","5x = 5 × x","5 = coefficient of x","","Expression:  5x + 7"],examples:[{q:"In 8p−11, identify the variable, coefficient and constant.",steps:["Read the expression as 8p+(−11). It has two terms: 8p and −11.","The letter p can represent different numerical values, so p is the variable.","In 8p, the number 8 tells us how many copies of p are being multiplied/collected: 8p means 8×p. Therefore 8 is the coefficient.","The term −11 contains no variable, so its value does not change when p changes. That makes −11 the constant term.","Keep the negative sign with 11; the constant is −11, not merely 11."],answer:"Variable p; coefficient 8; constant −11"},{q:"What does 4ab mean?",steps:["Letters written beside a number represent multiplication.","4ab means 4×a×b."],answer:"4×a×b"}]},
{title:"2. Terms, signs and factors",body:["Terms are separated by addition or subtraction signs. The sign immediately before a term belongs to that term.","Factors are quantities multiplied together inside one term. Distinguishing terms from factors is essential later when simplifying fractions: factors can sometimes cancel; separate added terms cannot."],board:["Expression:  6x² − 3xy + 5","","Terms:","6x²","−3xy","+5","","Factors of −3xy include −3, x and y"],examples:[{q:"List the terms of 4a²−7a+9.",steps:["Look for the + and − signs that separate the expression.","Keep each sign with the term following it."],answer:"4a², −7a, +9"},{q:"What is the coefficient of xy in −12xy?",steps:["−12 is the numerical factor multiplying xy.","The negative sign is part of the coefficient."],answer:"−12"}]},
{title:"3. Like terms: why some terms can be collected and others cannot",body:["Like terms represent the same kind of algebraic quantity. They must have exactly the same variable part with the same powers.","Think of 3x+5x as 3 groups of x plus 5 groups of x. That makes 8 groups of x. But 3x+5x² cannot be combined because x and x² are different quantities."],board:["3x + 5x = 8x","","4a² + 7a² = 11a²","","3x + 5x²  cannot be combined"],examples:[{q:"Simplify 7x+4x−3.",steps:[{text:"Identify the like terms first. 7x and 4x both contain x to the same power, while −3 is a constant.",math:["7x + 4x − 3","↳ like x-terms"]},{text:"Combine only the coefficients of the like terms and keep x.",math:["7x + 4x","= (7 + 4)x","= 11x"]},{text:"Bring down the constant because it is not like an x-term.",math:["7x + 4x − 3","= 11x − 3"]},{text:"Verify with x=2.",math:["7(2)+4(2)−3 = 19","11(2)−3 = 19","19 = 19 ✓"]}],answer:"11x−3"},{q:"Simplify 6a²−2a+5a²+7a.",steps:["Collect a² terms: 6a²+5a²=11a².","Collect a terms: −2a+7a=5a.","The powers are different, so keep the two groups separate."],answer:"11a²+5a"},{q:"Simplify 9xy−4x+3xy+7x.",steps:["9xy and 3xy are like: 12xy.","−4x and +7x are like: +3x.","xy-terms and x-terms are not like terms."],answer:"12xy+3x"}]},
{title:"4. Translating words into algebra",body:["Algebraic modelling begins by deciding what the letter represents. Then translate one phrase at a time.","Order matters. '5 less than x' means x−5, while '5 minus x' means 5−x. Reading language accurately is part of the mathematics."],board:["a number n increased by 7  → n+7","5 less than x → x−5","5 minus x → 5−x","three times y → 3y","half of p → p/2"],examples:[{q:"Write an expression for 'four more than three times a number n'.",steps:["Three times n is 3n.","Four more means add 4."],answer:"3n+4"},{q:"A boy is x years old. His sister is 3 years younger. Write her age.",steps:["Younger means subtract from the boy's age.","Three years younger than x is x−3."],answer:"x−3 years"},{q:"Write the total cost of x notebooks at ₦450 each and one pen costing ₦800.",steps:["Cost of x notebooks=450×x=450x.","Add the fixed cost of the pen, ₦800."],answer:"₦(450x+800)"}]},
{title:"5. Substitution: replacing a variable by its given value",body:["To evaluate an expression, replace each variable with its stated value. Use brackets around negative substituted values so their signs do not get lost.","Follow the normal order of operations after substitution."],examples:[{q:"Evaluate 3x²−2x+5 when x=4.",steps:["Substitute x=4: 3(4²)−2(4)+5.","Calculate the power first: 4²=16.","3×16=48.","2×4=8.","48−8+5=45."],answer:"45"},{q:"Evaluate 2a−3b when a=−4 and b=5.",steps:["Substitute using brackets: 2(−4)−3(5).","2(−4)=−8.","3(5)=15.","−8−15=−23."],answer:"−23"}]},
{title:"6. Expansion begins with the distributive law",body:["Expansion removes brackets without changing the value of an expression. The factor outside the bracket must multiply every term inside.","This works because multiplication distributes over addition and subtraction. Missing even one term changes the expression."],board:["a(b+c) = ab+ac","a(b−c) = ab−ac","","The outside factor multiplies EVERY term."],examples:[{q:"Expand 5(x+3).",steps:[{text:"The outside 5 must multiply EVERY term inside the bracket. Show both distribution paths.",math:["5(x + 3)","↙       ↘","5×x     5×3"]},{text:"Calculate each product.",math:["5×x = 5x","5×3 = 15"]},{text:"Join the products.",math:["5(x+3)","= 5x + 15"]},{text:"Check with x=2.",math:["5(2+3)=25","5(2)+15=25","25=25 ✓"]}],answer:"5x+15"},{q:"Expand 4(3x−5).",steps:["4×3x=12x.","4×(−5)=−20."],answer:"12x−20"},{q:"Expand −3(2x−7).",steps:["−3×2x=−6x.","−3×(−7)=+21 because negative×negative is positive."],answer:"−6x+21"}]},
{title:"7. Expand first, then collect like terms",body:["Some expressions require two different skills. First distribute into every bracket. Only after the brackets are removed should you collect terms that are truly alike.","Keeping those stages separate reduces sign errors."],examples:[{q:"Simplify 3(x+4)+2x.",steps:["Expand: 3(x+4)=3x+12.","So the expression becomes 3x+12+2x.","Collect x-terms: 3x+2x=5x."],answer:"5x+12"},{q:"Simplify 5(2a−3)−2(a+4).",steps:["First bracket: 5(2a−3)=10a−15.","Second bracket is multiplied by −2: −2(a+4)=−2a−8.","Now collect like terms: 10a−2a=8a.","Constants: −15−8=−23."],answer:"8a−23"},{q:"Simplify 4(2x−1)−3(x−5).",steps:["4(2x−1)=8x−4.","−3(x−5)=−3x+15.","Collect x-terms: 8x−3x=5x.","Constants: −4+15=11."],answer:"5x+11"}]},
{title:"8. Multiplying two binomials: every term must meet every term",body:["When both factors contain two terms, each term in the first bracket multiplies each term in the second. That produces four products before like terms are collected.","An area or quadratic box is useful because it makes the four required products visible and prevents one from being omitted."],board:["(a+b)(c+d)","","Products required:","a×c     a×d","b×c     b×d","","Then collect like terms."],examples:[{q:"Expand (x+3)(x+5).",steps:["We have two brackets multiplied together. To expand them completely, every term in the first bracket must multiply every term in the second bracket.","Start with the first term of the first bracket: +x.","Multiply +x by the first term in the second bracket, +x: (+x)×(+x)=+x².","Still using +x, multiply it by the second term, +5: (+x)×(+5)=+5x.","Now we have finished using the first term +x. Move to the second term of the first bracket: +3.","Multiply +3 by +x: (+3)×(+x)=+3x.","Then multiply +3 by +5: (+3)×(+5)=+15.","All four required products are now present: x²+5x+3x+15.","5x and 3x are like terms because both contain x to the first power. Add their coefficients: 5+3=8.","So the expanded expression is x²+8x+15."],answer:"x²+8x+15"},{q:"Expand (x−4)(x+6).",steps:["Again, every term in the first bracket must multiply both terms in the second bracket.","Begin with +x from the first bracket. Multiply it by +x, giving +x².","Use the same +x again and multiply it by +6, giving +6x.","Now move to −4, the second term in the first bracket. Its negative sign must travel with it.","Multiply −4 by +x, giving −4x.","Then multiply −4 by +6, giving −24.","Write all four products before simplifying: x²+6x−4x−24.","The middle terms are like terms: 6x−4x=2x.","Therefore the expansion is x²+2x−24."],answer:"x²+2x−24"},{q:"Expand (2x+3)(x−5).",steps:["There are two terms in each bracket, so we expect four products before collecting like terms.","Take the first term 2x. Multiply 2x by +x: 2x×x=2x².","Still using 2x, multiply it by −5: 2x×(−5)=−10x.","Now take the second term +3. Multiply +3 by +x: 3×x=3x.","Then multiply +3 by −5: 3×(−5)=−15.","Now write the four products together: 2x²−10x+3x−15.","Only −10x and +3x are like terms. Their coefficients give −10+3=−7.","So the final expansion is 2x²−7x−15."],answer:"2x²−7x−15"}]},
{title:"9. Sign-rich bracket expansion: make the route explicit",body:["When a bracket contains subtraction, treat the negative sign as part of the term. Do not drop it while moving from one multiplication to the next.","For (2−x)(3−x), the first bracket contains +2 and −x; the second contains +3 and −x. We will deliberately finish both multiplications for +2 before moving to −x."],board:["(2−x)(3−x)","","First term from first bracket: +2","(+2)(+3) = +6","(+2)(−x) = −2x","","Second term from first bracket: −x","(−x)(+3) = −3x","(−x)(−x) = +x²","","Now collect: 6−2x−3x+x²","= x²−5x+6"],examples:[{q:"Expand (2−x)(3−x).",steps:["First identify the terms. The first bracket contains +2 and −x. The second bracket contains +3 and −x.","Start with +2. It must multiply BOTH terms in the second bracket.","First: (+2)×(+3)=+6.","Second: (+2)×(−x)=−2x.","We have now finished using +2. Next take −x from the first bracket. Keep its negative sign attached.","Multiply −x by +3: (−x)×(+3)=−3x.","Then multiply −x by −x. A negative times a negative is positive, while x×x=x², so (−x)(−x)=+x².","Put all four products together before simplifying: 6−2x−3x+x².","−2x and −3x are like terms. Together they make −5x.","Write in descending powers of x: x²−5x+6."],answer:"x²−5x+6"},{q:"Expand (4−x)(2+x).",steps:["The first bracket contains +4 and −x; the second contains +2 and +x.","Use +4 first: (+4)(+2)=+8, then (+4)(+x)=+4x.","Now use −x: (−x)(+2)=−2x, then (−x)(+x)=−x².","Write every product: 8+4x−2x−x².","Collect the like x-terms: 4x−2x=2x.","In descending powers, the result is −x²+2x+8."],answer:"−x²+2x+8"}]},
{title:"9. The quadratic/area box: organise the four products",body:["A quadratic box is not a new algebra rule. It is a visual organiser for the same distributive multiplication.","Place one binomial across the top and the other down the side. Fill each cell with the product of its row and column headings, then collect like terms."],board:["Example: (x+2)(x+7)","","        x      +7","x      x²      7x","+2     2x      14","","x²+7x+2x+14","= x²+9x+14"],examples:[{q:"Use the box idea to expand (x+4)(x−3).",steps:["Four products are x², −3x, +4x and −12.","The middle products are like terms.","−3x+4x=+x."],answer:"x²+x−12"},{q:"What four entries belong in the box for (2x−1)(x+5)?",steps:["2x×x=2x².","2x×5=10x.","−1×x=−x.","−1×5=−5."],answer:"2x², 10x, −x, −5"}]},
{title:"10. Factorisation is expansion in reverse",body:["Expansion starts with a product and produces a sum. Factorisation starts with a sum of terms and rewrites it as a product.","To factorise by a common factor, find the greatest factor shared by every term, divide every term by it, and place the quotients inside a bracket."],board:["Expansion:","6x(2x+3) → 12x²+18x","","Factorisation reverses it:","12x²+18x → 6x(2x+3)"],examples:[{q:"Factorise 8x+12.",steps:["HCF of 8 and 12 is 4.","Both terms are divisible by 4.","8x÷4=2x.","12÷4=3."],answer:"4(2x+3)"},{q:"Factorise 12x²+18x.",steps:["HCF of 12 and 18 is 6.","Both terms contain x; the lowest power common to both is x.","Common factor=6x.","12x²÷6x=2x.","18x÷6x=3."],answer:"6x(2x+3)"},{q:"Factorise 15a²b−20ab².",steps:["HCF of 15 and 20 is 5.","Both terms contain a and b.","Lowest common powers are a¹ and b¹, giving common algebraic factor ab.","Common factor=5ab.","15a²b÷5ab=3a.","−20ab²÷5ab=−4b."],answer:"5ab(3a−4b)"}]},
{title:"11. Check factorisation by expanding again",body:["A factorised answer can be checked immediately: expand it. If expansion does not reproduce the original expression exactly, the factorisation is wrong.","This check is especially useful when negative terms or powers are involved."],examples:[{q:"Check whether 7x(2x−3) is a factorisation of 14x²−21x.",steps:["Expand 7x(2x−3).","7x×2x=14x².","7x×(−3)=−21x.","The expansion matches the original expression exactly."],answer:"Yes, it is correct"},{q:"A learner writes 18x²+12x=6(3x²+2x). Is this fully factorised?",steps:["The expansion is correct, but both terms inside the bracket still contain x.","The greatest common factor of the original terms is 6x, not merely 6.","Divide by 6x: 18x²÷6x=3x and 12x÷6x=2."],answer:"No; fully factorised form is 6x(3x+2)"}]},
{title:"12. Connecting simple quadratic expressions to their factors",body:["The NERDC quadratic-box work connects a quadratic expression with the two brackets that produce it. At this stage, the goal is to recognise and verify straightforward factor pairs—not to jump ahead into advanced quadratic methods.","For a monic expression x²+bx+c, look for two numbers whose product is c and whose sum is b, then verify by expansion."],board:["x² + bx + c","","Find m and n such that:","m × n = c","m + n = b","","Then test:","(x+m)(x+n)"],examples:[{q:"Factorise x²+7x+12.",steps:["We need two numbers with product 12 and sum 7.","3×4=12 and 3+4=7.","So try (x+3)(x+4).","Check by expansion: x²+4x+3x+12=x²+7x+12."],answer:"(x+3)(x+4)"},{q:"Factorise x²−x−12.",steps:["We need two numbers with product −12 and sum −1.","−4×3=−12 and −4+3=−1.","Try (x−4)(x+3).","Expand to check: x²+3x−4x−12=x²−x−12."],answer:"(x−4)(x+3)"},{q:"Which factors produce x²+2x−15?",steps:["Need product −15 and sum +2.","+5 and −3 satisfy both conditions.","Check: (x+5)(x−3)=x²−3x+5x−15=x²+2x−15."],answer:"(x+5)(x−3)"}]},
{title:"13. Algebraic fractions: understand what cancellation really means",body:["Cancellation is division by a common non-zero factor in the numerator and denominator. It is not crossing out symbols that merely look alike.","Factor first. Only quantities that multiply the whole numerator and denominator can be cancelled."],board:["12x²y / 18xy²","","12/18 = 2/3","x²/x = x","y/y² = 1/y","","Result:  2x/(3y)"],examples:[{q:"Simplify 12x²y/(18xy²).",steps:["Numerical fraction: 12/18=2/3.","x²/x=x.","y/y²=1/y.","Combine the remaining factors."],answer:"2x/(3y)"},{q:"Simplify 20a³b²/(5ab).",steps:["20÷5=4.","a³÷a=a².","b²÷b=b."],answer:"4a²b"},{q:"Simplify 18m²n/(24mn²).",steps:["18/24 reduces to 3/4.","m²/m=m.","n/n²=1/n."],answer:"3m/(4n)"}]},
{title:"14. Why you cannot cancel terms across addition",body:["In (x+4)/x, the numerator is a sum. x is not a factor of the entire numerator, so the x symbols cannot simply be crossed out.","Compare this with x(x+4)/x: here x multiplies the entire bracket, so x is a common factor and can be divided out, provided x≠0."],board:["WRONG:  (x+4)/x  →  4","","Why? x is only one TERM of the numerator.","It is not a factor of the whole numerator.","","VALID:  x(x+4)/x = x+4,  x≠0"],examples:[{q:"Can x be cancelled in (x+5)/x?",steps:["The numerator is x+5, an addition of two terms.","x does not multiply the entire numerator.","Therefore there is no common x factor to cancel."],answer:"No"},{q:"Simplify 6x(x−2)/(3x).",steps:["6/3=2.","x/x=1 for x≠0.","The remaining bracket x−2 stays intact."],answer:"2(x−2), x≠0"}]},
{title:"16. Algebraic fractions with monomial denominators",body:["A monomial denominator has one term. Simplify by identifying numerical and variable factors, reducing each common factor carefully, and retaining anything that does not cancel.","When several variables occur, compare powers of the same variable only."],examples:[{q:"Simplify 28x³y²/(35x²y).",steps:["28/35=4/5.","x³/x²=x.","y²/y=y."],answer:"4xy/5"},{q:"Simplify −24a²b³/(18ab).",steps:["−24/18=−4/3.","a²/a=a.","b³/b=b²."],answer:"−4ab²/3"},{q:"Simplify 45p⁴q/(15p²q).",steps:["45÷15=3.","p⁴÷p²=p².","q/q=1."],answer:"3p²"}]},
{title:"16. Word modelling with perimeter, area and cost",body:["Word problems test whether algebra can describe a relationship before numbers are known. Define the variable, write the mathematical relationship, substitute the algebraic quantities, then simplify.","Units remain important: perimeter is a length; area uses square units; money expressions keep their currency meaning."],examples:[{q:"A rectangle has length (x+4) cm and width x cm. Write its area.",steps:["Area=length×width.","=(x+4)x.","Distribute x: x×x=x² and x×4=4x."],answer:"x²+4x cm²"},{q:"A rectangle has length (2x+3) cm and width (x−1) cm. Write its area.",steps:["Area=(2x+3)(x−1).","2x×x=2x².","2x×(−1)=−2x.","3×x=3x.","3×(−1)=−3.","Combine −2x+3x=+x."],answer:"2x²+x−3 cm²"},{q:"A school buys x textbooks at ₦2,400 each and y exercise books at ₦650 each. Write the total cost.",steps:["Textbook cost=2400x.","Exercise-book cost=650y.","Add the two costs."],answer:"₦(2400x+650y)"}]},
{title:"17. Number patterns and quantitative reasoning",body:["An algebraic expression can describe every term of a numerical pattern. Look for what changes regularly and what stays fixed.","Test a proposed rule with several term numbers rather than trusting one match."],examples:[{q:"The sequence is 5, 8, 11, 14, ... Write the nth term.",steps:["The sequence increases by 3, so begin with 3n.","For n=1, 3n gives 3 but the first term is 5.","Add 2: 3n+2.","Check n=2: 3(2)+2=8."],answer:"3n+2"},{q:"Matchsticks form a row of joined squares: 1 square uses 4 sticks, 2 use 7, 3 use 10. Write a rule for n joined squares.",steps:["Each new square adds 3 sticks because one side is shared.","The pattern is 4,7,10,... with common difference 3.","Use 3n then adjust: at n=1, 3n=3, so add 1."],answer:"3n+1"}]},
{title:"19. Mixed multi-step algebra",body:["JSS2 mastery requires deciding which operation comes next rather than following a single memorised routine. Read the structure: brackets suggest expansion, repeated variable forms suggest collecting like terms, and a common factor suggests factorisation.","Write one legal transformation per line so signs and powers remain visible."],examples:[{q:"Simplify 3(2x−5)+4(x+2)−x.",steps:["Expand first bracket: 6x−15.","Expand second bracket: 4x+8.","Expression becomes 6x−15+4x+8−x.","Collect x-terms: 6x+4x−x=9x.","Collect constants: −15+8=−7."],answer:"9x−7"},{q:"Factorise 24x³y−36x²y².",steps:["HCF of 24 and 36 is 12.","Lowest common power of x is x².","Lowest common power of y is y.","Common factor=12x²y.","First quotient: 24x³y÷12x²y=2x.","Second quotient: −36x²y²÷12x²y=−3y."],answer:"12x²y(2x−3y)"},{q:"Evaluate 2x²−3xy+y² when x=−2 and y=3.",steps:["Substitute with brackets: 2(−2)²−3(−2)(3)+3².","(−2)²=4, so first term=8.","−3(−2)(3)=+18.","3²=9.","8+18+9=35."],answer:"35"}]},
{title:"19. Reverse reasoning: recover missing algebraic structure",body:["Harder questions may give a result and ask for a missing coefficient or factor. Work backwards using the same expansion and factorisation relationships already learned.","Do not guess from appearance; compare corresponding terms."],examples:[{q:"If 5(2x+k)=10x+35, find k.",steps:["Expand the left: 5(2x+k)=10x+5k.","Compare with 10x+35.","The constant terms must match, so 5k=35.","k=7."],answer:"7"},{q:"Complete: 18x²−30x = 6x(3x−___).",steps:["6x×3x=18x², so the first term matches.","For the second term, 6x multiplied by the missing negative number must give −30x.","30÷6=5."],answer:"5"},{q:"If (x+4)(x+k)=x²+9x+20, find k.",steps:["The constant term is 4k=20, so k=5.","Check the middle term: x·k+4x=(k+4)x=9x when k=5."],answer:"5"}]},
{title:"20. Mastery checks: explain and verify, not merely produce an answer",body:["A strong algebra answer should survive a check. Re-expand a factorised expression; substitute a convenient value into two supposedly equivalent expressions; or compare every term after expansion.","These checks catch missing bracket terms, wrong signs, illegal cancellation and incomplete factorisation."],examples:[{q:"A learner claims 4(x−3)+2x=6x−3. Diagnose the error.",steps:["Expand 4(x−3).","4 multiplies both x and −3.","That gives 4x−12, not 4x−3.","Then 4x−12+2x=6x−12."],answer:"The learner failed to multiply −3 by 4; correct result is 6x−12"},{q:"Are 3x(x+2) and 3x²+6x equivalent?",steps:["Expand 3x(x+2).","3x×x=3x².","3x×2=6x.","This exactly matches 3x²+6x."],answer:"Yes"},{q:"A learner simplifies (2x+6)/(2x) to 3. Explain why this is invalid.",steps:["The numerator is a sum, not one product.","2x is not a factor of the entire numerator 2x+6.","Factor the numerator if useful: 2(x+3)/(2x)=(x+3)/x for x≠0.","That is not generally equal to 3."],answer:"Cancellation across addition is invalid; simplified form is (x+3)/x, x≠0"}]}
],mistakes:["Do not treat a variable as decoration; it represents a number or quantity.","Keep the sign attached to its term, especially a negative coefficient.","Combine only like terms with identical variable parts and powers.","When expanding, multiply the outside factor by every term inside the bracket.","With two binomials, account for all four products before collecting like terms.","Factorisation reverses expansion; check by expanding your answer.","Use the greatest common numerical and algebraic factor when fully factorising.","Do not cancel terms joined by addition or subtraction; cancel common factors only.","Use brackets when substituting negative values.","Translate wording carefully: 'less than' can reverse the apparent order.","Keep units in word problems and distinguish length from area.","For quadratic-box work, verify proposed factors by expansion rather than guessing."]},
"Simple Equations":{title:"Simple Equations",objectives:["Explain an equation as a statement that two expressions have equal value","Identify the unknown, coefficient, constant and operations acting on the unknown","Explain why the same operation must be performed on both sides of an equation","Use inverse operations to solve one-step and two-step equations in one variable","Solve equations with the unknown on both sides when they reduce to a simple one-variable equation","Model real-world situations in equation form and solve them","Check every proposed solution by substitution"],sections:[
{title:"1. Foundation: an equation says two quantities are equal",body:["An equation is a mathematical statement containing an equals sign. The equals sign does not mean 'the answer comes next'; it says the expression on the left and the expression on the right have the same value.","Think of the two sides as a balanced scale. If both sides are equal and we change only one side, the balance is usually destroyed. To preserve equality, whatever valid operation we perform on one side must also be performed on the other side."],board:["Left side = Right side","If a = b, then:","a + c = b + c","a − c = b − c","a × c = b × c","a ÷ c = b ÷ c   (c ≠ 0)"],examples:[{q:"Why is 8+4=15−3 an equation?",steps:["Calculate the left side: 8+4=12.","Calculate the right side: 15−3=12.","Both expressions have the same value, so the equals sign is true.","Therefore 8+4=15−3 is an equation."],answer:"Both sides have value 12."},{q:"If x+5=12, why may we subtract 5 from both sides?",steps:["The two sides are equal before we begin.","The +5 is attached to x, so subtracting 5 will undo that addition.","If we subtract 5 from only the left side, we would change one side without making the same change to the other.","Subtract 5 from BOTH sides to preserve equality: x+5−5=12−5.","The +5 and −5 cancel to 0, leaving x=7."],answer:"The same subtraction preserves the equality."}]},
{title:"2. Meet the parts of a simple equation",body:["Before solving, read the equation. A letter such as x or y represents the unknown value we want to find. A number multiplying the unknown is its coefficient. A number standing alone is a constant.","For example, in 3x−4=17, x is the unknown, 3 is the coefficient of x, −4 is a constant term and 17 is the value on the other side. Also remember that 3x means 3×x."],examples:[{q:"Identify the important parts of 5y+7=32.",steps:["The letter y is the unknown because its value has not yet been found.","5y means 5×y, so 5 is the coefficient of y.","+7 is a constant term because it contains no variable.","32 is the expression on the right side of the equality."],answer:"Unknown y; coefficient 5; constant +7."}]},
{title:"3. Inverse operations: how we undo an operation",body:["Solving an equation means finding the value of the unknown that makes the equality true. To get the unknown alone, undo operations using inverse operations.","Addition and subtraction are inverse operations. Multiplication and division are inverse operations. We do not simply say a term 'crosses the equals sign and changes sign'; the real reason is that we perform the same inverse operation on both sides."],board:["Operation on the unknown      Inverse used to undo it","+ a                          − a","− a                          + a","× a                          ÷ a","÷ a                          × a"],examples:[{q:"What operation should undo x−9?",steps:["The expression x−9 means 9 has been subtracted from x.","The inverse of subtracting 9 is adding 9.","So, in an equation containing x−9, add 9 to both sides when you want to remove −9."],answer:"Add 9 to both sides."},{q:"What operation should undo 6x?",steps:["6x means 6×x.","The inverse of multiplying by 6 is dividing by 6.","So divide both sides by 6 when isolating x."],answer:"Divide both sides by 6."}]},
{title:"4. One-step equations involving addition and subtraction",body:["A one-step equation needs one inverse operation to isolate the unknown. First identify what has been done to the unknown, then undo it on both sides."],examples:[{q:"Solve x+8=21.",steps:[{text:"The goal is to leave x alone. Because 8 was added to x, subtract 8 from BOTH sides.",math:["x + 8 = 21","    − 8   − 8","───────────","x     = 13"],note:"The +8 and −8 cancel on the left; the same subtraction on the right preserves equality."},{text:"Verify in the original equation.",math:["13 + 8","= 21 ✓"]}],answer:"x = 13"},{q:"Solve y−12=25.",steps:[{text:"12 has been subtracted from y. Undo that subtraction by adding 12 to BOTH sides.",math:["y − 12 = 25","   + 12   + 12","────────────","y      = 37"]},{text:"Check the original equation.",math:["37 − 12","= 25 ✓"]}],answer:"y = 37"}]},
{title:"5. One-step equations involving multiplication and division",body:["When the unknown is multiplied by a non-zero number, divide both sides by that number. When the unknown is divided by a non-zero number, multiply both sides by that number."],examples:[{q:"Solve 7x=56.",steps:[{text:"7x means 7×x. Undo multiplication by 7 by dividing BOTH sides by 7.",rows:[{left:"7x",right:"56"},{left:"7x/7",right:"56/7",cancelLeft:true},{left:"x",right:"8"}],note:"The visible cancellation shows 7÷7=1, leaving one x."},{text:"Verify in the original equation.",math:["7 × 8","= 56 ✓"]}],answer:"x = 8"},{q:"Solve y/5=9.",steps:["y/5 means y has been divided by 5.","Undo division by 5 by multiplying both sides by 5.","5×(y/5)=9×5.","On the left, multiplication by 5 cancels division by 5, leaving y.","9×5=45.","Check: 45÷5=9."],answer:"y = 45"}]},
{title:"6. Two-step equations: undo operations in reverse order",body:["In a two-step equation, more than one operation acts on the unknown. Undo the outer operation first, then the operation closest to the unknown. This is the reverse of the order in which the expression was built.","For 3x−4, x is first multiplied by 3 and then 4 is subtracted. To reverse that process, first undo −4, then undo ×3."],board:["3x − 4 = 17","","First undo −4:","3x − 4 + 4 = 17 + 4","3x = 21","","Then undo ×3:","3x ÷ 3 = 21 ÷ 3","x = 7"],examples:[{q:"Solve 3x−4=17.",steps:[{text:"Read the left side: 3x means 3×x, then 4 is subtracted. Undo −4 first by adding 4 to BOTH sides.",math:["3x − 4 = 17","     + 4   + 4","────────────","3x      = 21"]},{text:"Now divide BOTH sides by 3 and show what cancels.",rows:[{left:"3x",right:"21"},{left:"3x/3",right:"21/3",cancelLeft:true},{left:"x",right:"7"}],note:"3÷3=1, so one x remains."},{text:"Verify in the original equation.",math:["3(7) − 4","= 21 − 4","= 17 ✓"]}],answer:"x = 7"},{q:"Solve 5y+6=41.",steps:[{text:"Undo +6 by subtracting 6 from BOTH sides.",math:["5y + 6 = 41","     − 6   − 6","────────────","5y      = 35"]},{text:"Now divide BOTH sides by 5 and show what cancels.",rows:[{left:"5y",right:"35"},{left:"5y/5",right:"35/5",cancelLeft:true},{left:"y",right:"7"}]},{text:"Verify.",math:["5(7)+6","=35+6","=41 ✓"]}],answer:"y = 7"}]},
{title:"7. Equations with negative constants",body:["A negative constant does not require a new rule. Read the sign carefully and use the inverse operation. If an equation has +(-6), undo it by adding 6; if it has +6, undo it by subtracting 6."],examples:[{q:"Solve 4x−9=27.",steps:[{text:"Undo −9 by adding 9 to BOTH sides.",math:["4x − 9 = 27","     + 9   + 9","────────────","4x      = 36"]},{text:"Divide BOTH sides by 4.",rows:[{left:"4x",right:"36"},{left:"4x/4",right:"36/4",cancelLeft:true},{left:"x",right:"9"}]},{text:"Verify.",math:["4(9)−9","=36−9","=27 ✓"]}],answer:"x = 9"},{q:"Solve 6y+11=−7.",steps:[{text:"Undo +11 by subtracting 11 from BOTH sides.",math:["6y + 11 = −7","     − 11   −11","─────────────","6y       = −18"]},{text:"Divide BOTH sides by 6.",rows:[{left:"6y",right:"−18"},{left:"6y/6",right:"−18/6",cancelLeft:true},{left:"y",right:"−3"}]},{text:"Verify.",math:["6(−3)+11","=−18+11","=−7 ✓"]}],answer:"y = −3"}]},
{title:"8. When the unknown appears on both sides",body:["Some simple equations place variable terms on both sides. We can still preserve equality by subtracting the same variable term from both sides. Choose a move that leaves the variable terms together and keeps the arithmetic clear.","After variable terms are collected, continue with ordinary inverse operations."],examples:[{q:"Solve 5x+2=3x+18.",steps:[{text:"Subtract 3x from BOTH sides so the variable terms collect on the left.",math:["5x + 2 = 3x + 18","−3x       −3x","──────────────","2x + 2 = 18"]},{text:"Undo +2 by subtracting 2 from BOTH sides.",math:["2x + 2 = 18","     − 2   − 2","───────────","2x      = 16"]},{text:"Divide BOTH sides by 2.",rows:[{left:"2x",right:"16"},{left:"2x/2",right:"16/2",cancelLeft:true},{left:"x",right:"8"}]},{text:"Check the original equation.",math:["Left: 5(8)+2 = 42","Right: 3(8)+18 = 42","42 = 42 ✓"]}],answer:"x = 8"},{q:"Solve 7y−5=4y+16.",steps:[{text:"Subtract 4y from BOTH sides.",math:["7y − 5 = 4y + 16","−4y       −4y","──────────────","3y − 5 = 16"]},{text:"Add 5 to BOTH sides.",math:["3y − 5 = 16","     + 5   + 5","───────────","3y      = 21"]},{text:"Divide BOTH sides by 3.",rows:[{left:"3y",right:"21"},{left:"3y/3",right:"21/3",cancelLeft:true},{left:"y",right:"7"}]},{text:"Check both sides.",math:["Left: 7(7)−5 = 44","Right: 4(7)+16 = 44","44 = 44 ✓"]}],answer:"y = 7"}]},
{title:"9. Equations containing brackets",body:["When a bracket is multiplied by a number, first use the distributive law so every term inside the bracket is multiplied. Then solve the resulting equation using the balance method already learned.","Do not multiply only the first term in the bracket."],examples:[{q:"Solve 3(x+2)=21.",steps:[{text:"Expand first. The outside 3 multiplies BOTH terms.",math:["3(x+2)=21","3×x + 3×2 = 21","3x + 6 = 21"]},{text:"Subtract 6 from BOTH sides.",math:["3x + 6 = 21","     − 6   − 6","───────────","3x      = 15"]},{text:"Divide BOTH sides by 3.",rows:[{left:"3x",right:"15"},{left:"3x/3",right:"15/3",cancelLeft:true},{left:"x",right:"5"}]},{text:"Verify.",math:["3(5+2)","=3×7","=21 ✓"]}],answer:"x = 5"},{q:"Solve 2(y−4)+3=13.",steps:["First expand 2(y−4). The 2 multiplies y and −4.","2(y−4)=2y−8, so the equation becomes 2y−8+3=13.","Combine the constants on the left: −8+3=−5, giving 2y−5=13.","Add 5 to both sides: 2y=18.","Divide both sides by 2: y=9.","Check: 2(9−4)+3=2×5+3=13."],answer:"y = 9"}]},
{title:"10. Fractions in simple equations",body:["A fraction bar represents division. If the unknown is divided by a number, multiplication by that number can remove the denominator. If several terms form a fraction, treat the numerator as one grouped quantity."],examples:[{q:"Solve x/4+3=8.",steps:[{text:"Read the equation before changing it. x/4 means one quarter of x, and 3 has then been added.",math:["x/4 + 3 = 8"]},{text:"First get the x/4 term by itself. Because 3 was added, use the inverse operation −3 on BOTH sides.",math:["x/4 + 3 = 8","        − 3   − 3","──────────────","x/4       = 5"],note:"The +3 and −3 cancel on the left. Equality is preserved because the same subtraction was made on both sides."},{text:"Now x is still divided by 4. Write x over 4 as a true fraction. Multiply BOTH sides by 4.",rows:[{left:"x/4",right:"5"},{left:"4 × x/4",right:"5 × 4",cancelLeft:true},{left:"x",right:"20"}],note:"The visible cancellation shows the factor 4 above and the denominator 4 cancelling because 4÷4=1. What remains on the left is x."},{text:"Check in the ORIGINAL equation, not only the last line.",math:["20/4 + 3","= 5 + 3","= 8 ✓"],note:"The check returns the original right-hand side, so x=20 is correct."}],answer:"x = 20"},{q:"Solve (y+2)/3=6.",steps:[{text:"The fraction bar groups y+2 together. The whole numerator is being divided by 3.",math:["(y + 2)/3 = 6"]},{text:"Undo ÷3 by multiplying BOTH sides by 3.",math:["(y + 2)/3 = 6","× 3          × 3","──────────────","y + 2      = 18"],note:"The ×3 and ÷3 cancel, so the grouped numerator y+2 remains."},{text:"Now undo +2 by subtracting 2 from BOTH sides.",math:["y + 2 = 18","    − 2   − 2","───────────","y     = 16"]},{text:"Verify with the original fraction.",math:["(16 + 2)/3","= 18/3","= 6 ✓"]}],answer:"y = 16"}]},
{title:"11. From words to equations",body:["The curriculum requires learners to model real-world situations in equation form. Do not rush straight to arithmetic. First decide what is unknown, give it a letter, translate each relationship, then solve and interpret the result in the original situation.","Useful language includes: 'sum' or 'more' for addition, 'difference' or 'less' for subtraction, 'times' or 'of' for multiplication, and 'shared/divided' for division. Context still matters, so read the complete sentence."],board:["1. State the unknown.","2. Let a letter represent it.","3. Translate the relationship into an equation.","4. Solve by equal operations on both sides.","5. Check the solution in the equation.","6. Answer in the original context."],examples:[{q:"A number is doubled and 5 is added. The result is 23. Find the number.",steps:["The unknown is the number. Let it be x.","'Doubled' means multiply x by 2, giving 2x.","'5 is added' gives 2x+5.","'The result is 23' tells us this expression equals 23: 2x+5=23.","Subtract 5 from both sides: 2x=18.","Divide both sides by 2: x=9.","Check: double 9 is 18; add 5 and we get 23."],answer:"The number is 9."},{q:"Three exercise books of the same price and a ₦500 pen cost ₦3,200 altogether. Find the price of one exercise book.",steps:["The unknown is the price of one exercise book. Let it be x naira.","Three books at x naira each cost 3x.","Adding the ₦500 pen gives total cost 3x+500.","The total is ₦3,200, so form the equation 3x+500=3,200.","Subtract 500 from both sides: 3x=2,700.","Divide both sides by 3: x=900.","Check: 3×₦900+₦500=₦2,700+₦500=₦3,200."],answer:"One exercise book costs ₦900."}]},
{title:"12. A real-life 'before and after' equation",body:["Some situations describe an original amount, a change, and a final amount. Represent the original amount by a letter, translate every change in the order it occurs, and set the resulting expression equal to the final amount."],examples:[{q:"Ade had some oranges. He received 15 more, then gave 6 away. He now has 22 oranges. How many did he have at first?",steps:["The unknown is Ade's original number of oranges. Let it be x.","Receiving 15 increases the amount, so after receiving them he has x+15.","Giving 6 away decreases that amount, so he then has x+15−6.","The final number is 22, so write x+15−6=22.","Combine the known changes: +15−6=+9, giving x+9=22.","Subtract 9 from both sides: x=13.","Check the story: start with 13, receive 15 to get 28, give away 6 to get 22."],answer:"Ade had 13 oranges at first."},{q:"A class collected an equal amount from each of 8 learners and then received an extra ₦2,000 donation. The total was ₦10,000. How much did each learner contribute?",steps:["Let each learner's contribution be x naira.","Eight equal contributions total 8x.","Add the ₦2,000 donation: 8x+2,000.","The final total is ₦10,000, so 8x+2,000=10,000.","Subtract ₦2,000 from both sides: 8x=8,000.","Divide both sides by 8: x=1,000.","Check: 8×₦1,000+₦2,000=₦10,000."],answer:"Each learner contributed ₦1,000."}]},
{title:"13. Equations are solved, not guessed",body:["Guessing may accidentally find a small answer, but it does not provide a reliable method for unfamiliar numbers. The balance method explains every transformation and works systematically.","Mental checking is useful after solving, but it should not replace a method when the question asks you to solve an equation."],examples:[{q:"A learner says x=6 for 4x+3=31 because 6 'looks close'. Test and correct the answer.",steps:["Substitute the guess x=6 into the left side: 4(6)+3=24+3=27.","27 is not equal to 31, so x=6 is not a solution.","Now solve systematically. Subtract 3 from both sides: 4x=28.","Divide both sides by 4: x=7.","Check: 4(7)+3=28+3=31."],answer:"x = 7"}]},
{title:"14. Quantitative reasoning: reverse the relationship",body:["A strong learner should be able to form an equation even when the unknown is the original quantity rather than the final result. Ask what happened to the unknown and write those operations in order."],examples:[{q:"After ₦1,500 was added to three times an amount, the result was ₦9,000. Find the amount.",steps:["Let the unknown amount be x.","Three times the amount is 3x.","Adding ₦1,500 gives 3x+1,500.","The result is ₦9,000, so 3x+1,500=9,000.","Subtract 1,500 from both sides: 3x=7,500.","Divide both sides by 3: x=2,500.","Check: 3×₦2,500+₦1,500=₦9,000."],answer:"₦2,500"},{q:"Five times a number is 14 more than twice the same number. Find the number.",steps:["Let the number be x.","Five times the number is 5x.","Fourteen more than twice the number is 2x+14.","The statement says these are equal, so 5x=2x+14.","Subtract 2x from both sides: 3x=14.","Divide both sides by 3: x=14/3.","The answer is not a whole number, and that is acceptable unless the question requires one.","Check: 5(14/3)=70/3 and 2(14/3)+14=28/3+42/3=70/3."],answer:"x = 14/3 or 4⅔"}]},
{title:"15. Mastery: always verify the solution",body:["A solution is not complete merely because x has been isolated. Substitute the value into the ORIGINAL equation. If both sides become equal, the value satisfies the equation; if they do not, revisit the working.","Checking the original equation can reveal arithmetic mistakes that would be hidden if you checked only the final simplified line."],examples:[{q:"Verify x=−2 for 4x+7=−1.",steps:["Start with the original left side: 4x+7.","Substitute x=−2: 4(−2)+7.","Multiply first: 4(−2)=−8.","Then add 7: −8+7=−1.","The right side of the original equation is also −1.","Both sides are equal, so x=−2 is verified."],answer:"x = −2 satisfies the equation."}]}
],mistakes:["Do not 'move' a term across the equals sign as an unexplained shortcut; state the inverse operation performed on both sides.","Do not divide only one side of an equation.","Remember that 3x means 3×x.","When brackets are present, multiply every term inside the bracket before solving.","Define the unknown before forming an equation from words.","Check the final value in the original equation, not only in an intermediate line."]},
"Linear Inequalities":{title:"Linear Inequalities",objectives:["Explain an inequality as a comparison rather than an equality","Read and use <, >, ≤ and ≥ correctly","Distinguish equations from inequalities and identify linear inequalities in one variable","Test whether a given value satisfies an inequality","Solve one-step and multi-step linear inequalities while preserving order","Explain and apply the sign-reversal rule when multiplying or dividing by a negative number","Represent solution sets accurately on a number line using open and closed boundary points","Translate everyday statements such as at most, at least, more than and less than into inequalities","Form, solve and interpret one-variable inequality word problems","Check a solution set using boundary and sample values"],sections:[
{title:"1. Foundation: equality and inequality are different ideas",body:["An equation says two expressions have exactly the same value. An inequality compares two quantities and tells us that one is smaller, larger, or possibly equal to the other.","For example, x=4 names one exact value. But x<4 describes every number less than 4: 3, 0, −2, 3.9 and infinitely many others. That is why an inequality answer is usually a set or range of values, not one number.","The central question in this topic is therefore not only ‘what is x?’ but ‘which values of x make this comparison true?’"],examples:[{q:"Compare x=5 and x<5.",steps:[{text:"Read each mathematical statement in words.",math:["x = 5 → x is exactly 5","x < 5 → x is any number less than 5"]},{text:"Test a few values to see the difference.",math:["4 < 5 ✓","0 < 5 ✓","−7 < 5 ✓","5 < 5 ✗"]}],answer:"An equation may identify one value; an inequality usually describes a range."},{q:"Is 7<10 an equation or an inequality?",steps:[{text:"The symbol < compares two unequal quantities; it does not say they are equal.",math:["7 < 10"]}],answer:"It is an inequality."}]},
{title:"2. The four inequality symbols and what the boundary means",body:["The symbols < and > are strict: the boundary value itself is not included. The symbols ≤ and ≥ include equality, so the boundary value is allowed.","Read the symbol from left to right. x<6 means x is less than 6. x>6 means x is greater than 6. x≤6 means x is less than or equal to 6. x≥6 means x is greater than or equal to 6."],board:["x < 6   → less than 6","x > 6   → greater than 6","x ≤ 6   → less than or equal to 6","x ≥ 6   → greater than or equal to 6"],examples:[{q:"Which statement includes 12: x<12 or x≤12?",steps:[{text:"Test the boundary x=12 in each statement.",math:["12 < 12 ✗","12 ≤ 12 ✓"]}],answer:"x ≤ 12 includes 12."},{q:"Write ‘n is at least 9’ using a symbol.",steps:[{text:"‘At least 9’ means 9 is allowed and every larger value is allowed.",math:["n ≥ 9"]}],answer:"n ≥ 9"}]},
{title:"3. Identify a linear inequality in one variable",body:["A linear inequality in one variable contains one unknown whose highest power is 1, and it uses an inequality sign. Examples include 3x+2<14 and 7−2y≥5.","x²<9 is not linear because the variable is squared. x+y>6 has two variables, so it is not a linear inequality in one variable."],examples:[{q:"Which is a linear inequality in one variable: 4x−3≤9, x²>4, or x+y<8?",steps:[{text:"Check the number of variables and the highest power.",math:["4x−3≤9 → one variable, power 1 ✓","x²>4 → power 2 ✗","x+y<8 → two variables ✗"]}],answer:"4x−3≤9"}]},
{title:"4. Solution sets: test values before learning a procedure",body:["A value is a solution if substituting it makes the inequality true. Testing values helps a learner understand that the final answer represents many possible numbers."],examples:[{q:"Does x=3 satisfy 2x+1<9?",steps:[{text:"Substitute 3 for x.",math:["2(3)+1 < 9","6+1 < 9","7 < 9 ✓"]}],answer:"Yes, x=3 satisfies the inequality."},{q:"Does x=5 satisfy 2x+1<9?",steps:[{text:"Substitute 5.",math:["2(5)+1 < 9","11 < 9 ✗"]}],answer:"No."}]},
{title:"5. The balance principle still works",body:["As with equations, we may add or subtract the same number on both sides without changing which side is larger. We may also multiply or divide both sides by the same positive number without changing the inequality direction.","This lets us isolate the variable one operation at a time. The special case involving a negative multiplier or divisor is taught separately because its direction must reverse."],example:{q:"Solve x+7<15.",steps:[{text:"Undo +7 by subtracting 7 from BOTH sides.",math:["x + 7 < 15","    − 7   − 7","──────────","x     < 8"]},{text:"Check one allowed value and the boundary.",math:["x=7: 7+7<15 → 14<15 ✓","x=8: 8+7<15 → 15<15 ✗"]}],answer:"x < 8"}},
{title:"6. One-step inequalities: addition and subtraction",body:["When a number has been added to or subtracted from the variable, use the inverse operation on both sides. Addition and subtraction do not reverse the inequality sign."],examples:[{q:"Solve x−9≥4.",steps:[{text:"Undo −9 by adding 9 to both sides.",math:["x − 9 ≥ 4","    + 9   + 9","─────────","x     ≥ 13"]}],answer:"x ≥ 13"},{q:"Solve y+12≤20.",steps:[{text:"Subtract 12 from both sides.",math:["y + 12 ≤ 20","    − 12  − 12","──────────","y      ≤ 8"]}],answer:"y ≤ 8"}]},
{title:"7. One-step inequalities: multiplication or division by a positive number",body:["If the variable is multiplied or divided by a positive number, use the inverse operation on both sides. Because the number is positive, the inequality sign keeps its direction."],examples:[{q:"Solve 5x<35.",steps:[{text:"Divide both sides by positive 5. The sign does not reverse.",rows:[{left:"5x",right:"35"},{left:"5x/5",right:"35/5",cancelLeft:true},{left:"x",right:"7"}]}],answer:"x < 7"},{q:"Solve y/4≥6.",steps:[{text:"Multiply both sides by positive 4.",math:["y/4 ≥ 6","4 × y/4 ≥ 6 × 4","y ≥ 24"]}],answer:"y ≥ 24"}]},
{title:"8. Why multiplying or dividing by a negative reverses the sign",body:["This rule should not be memorised without meaning. On a number line, multiplying by −1 reflects every number across zero. Reflection reverses left and right, so it reverses order.","Start with a true comparison such as 2<5. Multiply both numbers by −1. We obtain −2 and −5. But −2 is greater than −5, so the new true statement is −2>−5."],board:["2 < 5","×(−1)   ×(−1)","−2 > −5"],example:{q:"Why can we not keep < after multiplying 2<5 by −1?",steps:[{text:"Keeping the old sign would produce a false statement.",math:["2 < 5 ✓","−2 < −5 ✗","−2 > −5 ✓"]}],answer:"A negative multiplication reverses order, so the inequality sign must reverse."}},
{title:"9. Solve when the variable coefficient is negative",body:["First isolate the variable as usual. At the exact step where both sides are multiplied or divided by a negative number, reverse < to >, > to <, ≤ to ≥, or ≥ to ≤."],examples:[{q:"Solve −2x≥10.",steps:[{text:"x is multiplied by −2. Divide both sides by −2.",rows:[{left:"−2x",right:"10"},{left:"−2x/−2",right:"10/−2",cancelLeft:true},{left:"x",right:"−5"}],note:"Because we divided by a negative number, ≥ reverses to ≤."},{text:"Check an allowed value x=−6.",math:["−2(−6)=12","12 ≥ 10 ✓"]}],answer:"x ≤ −5"},{q:"Solve −4y<20.",steps:[{text:"Divide by −4 and reverse < to >.",math:["−4y < 20","y > 20/−4","y > −5"]},{text:"Check y=0, which should be allowed.",math:["−4(0)<20","0<20 ✓"]}],answer:"y > −5"}]},
{title:"10. Two-step inequalities",body:["Undo addition or subtraction first, then undo multiplication or division. Keep the same-operation-on-both-sides discipline used for equations."],examples:[{q:"Solve 3x+5≤20.",steps:[{text:"Subtract 5 from both sides.",math:["3x + 5 ≤ 20","     − 5   − 5","───────────","3x      ≤ 15"]},{text:"Divide by positive 3, so the sign stays ≤.",rows:[{left:"3x",right:"15"},{left:"3x/3",right:"15/3",cancelLeft:true},{left:"x",right:"5"}]}],answer:"x ≤ 5"},{q:"Solve 7−2x>15.",steps:[{text:"Subtract 7 from both sides.",math:["7 − 2x > 15","−7       −7","──────────","−2x > 8"]},{text:"Divide by −2. This is the step that reverses > to <.",math:["−2x/−2 < 8/−2","x < −4"]}],answer:"x < −4"}]},
{title:"11. Variables on both sides",body:["Collect variable terms on one side and constants on the other. If the final division is by a negative number, reverse the sign at that final step."],examples:[{q:"Solve 5x−3>2x+9.",steps:[{text:"Subtract 2x from both sides.",math:["5x−3 > 2x+9","−2x     −2x","────────────","3x−3 > 9"]},{text:"Add 3 to both sides.",math:["3x−3 > 9","+3      +3","────────","3x > 12"]},{text:"Divide by positive 3.",math:["x > 4"]}],answer:"x > 4"},{q:"Solve 2x+7≤5x−8.",steps:[{text:"Subtract 5x from both sides. This choice produces a negative coefficient, which is acceptable.",math:["2x+7 ≤ 5x−8","−5x      −5x","────────────","−3x+7 ≤ −8"]},{text:"Subtract 7.",math:["−3x ≤ −15"]},{text:"Divide by −3 and reverse ≤ to ≥.",math:["x ≥ 5"]}],answer:"x ≥ 5"}]},
{title:"12. Brackets and simplification before solving",body:["If brackets appear, expand them carefully before isolating the variable. If like terms can be collected, simplify them first. The inequality rules are then applied to the simplified statement."],examples:[{q:"Solve 3(x+2)<18.",steps:[{text:"Expand the bracket.",math:["3(x+2)<18","3x+6<18"]},{text:"Subtract 6, then divide by positive 3.",math:["3x<12","x<4"]}],answer:"x < 4"},{q:"Solve 2(3−x)≥10.",steps:[{text:"Expand both terms inside the bracket.",math:["2(3−x)≥10","6−2x≥10"]},{text:"Subtract 6.",math:["−2x≥4"]},{text:"Divide by −2 and reverse ≥ to ≤.",math:["x≤−2"]}],answer:"x ≤ −2"}]},
{title:"13. Number-line representation: boundary first, direction second",body:["A number line makes the whole solution set visible. First locate the boundary number. Use an open circle for < or > because the boundary is excluded. Use a filled circle for ≤ or ≥ because the boundary is included.","Then shade or draw an arrow toward the values that satisfy the inequality: left for smaller values and right for larger values."],board:["x < 3   : open circle at 3, shade left","x ≤ 3   : filled circle at 3, shade left","x > 3   : open circle at 3, shade right","x ≥ 3   : filled circle at 3, shade right"],examples:[{q:"Represent x≤2 on a number line.",steps:[{text:"The boundary is 2. Because equality is included, use a filled point.",math:["boundary: 2 → ●"]},{text:"x is less than or equal to 2, so shade toward smaller numbers.",math:["←══════●","       2"]}],answer:"Filled point at 2, shaded to the left."},{q:"Represent x>−1 on a number line.",steps:[{text:"The boundary −1 is excluded, so use an open point and shade right.",math:["○══════→","−1"]}],answer:"Open point at −1, shaded to the right."}]},
{title:"14. Read a number line back into an inequality",body:["Reading a graph is the reverse process. Identify the boundary, decide whether the point is open or filled, and observe the direction of the shaded ray."],examples:[{q:"A number line has an open circle at 4 and is shaded left. Write the inequality.",steps:[{text:"Open means 4 is excluded; left means values smaller than 4.",math:["x < 4"]}],answer:"x < 4"},{q:"A number line has a filled point at −3 and is shaded right.",steps:[{text:"Filled includes −3; right means values greater than it.",math:["x ≥ −3"]}],answer:"x ≥ −3"}]},
{title:"15. Language used in word problems",body:["Words that describe limits must be translated accurately. ‘At most’ means no more than, so use ≤. ‘At least’ means not less than, so use ≥. ‘More than’ means >. ‘Less than’ means <.","Also distinguish a comparison from an operation. ‘5 more than x’ is x+5, while ‘x is more than 5’ is x>5."],board:["at most / no more than → ≤","at least / not less than → ≥","more than → >","less than → <"],example:{q:"Translate: A learner must score at least 50 marks.",steps:[{text:"Let s be the score. ‘At least 50’ includes 50 and every score above it.",math:["s ≥ 50"]}],answer:"s ≥ 50"}},
{title:"16. Form and solve word problems",body:["Use a consistent modelling process: define the unknown, translate the condition into an inequality, solve it, then interpret the mathematical answer in the real situation."],examples:[{q:"A bus can carry at most 54 people. There are already 38 aboard. If x more enter, how many can still enter?",steps:[{text:"Let x be the number of additional passengers. ‘At most 54’ gives the capacity inequality.",math:["38+x ≤ 54"]},{text:"Subtract 38 from both sides.",math:["38+x−38 ≤ 54−38","x ≤ 16"]},{text:"Interpret the result in context.",math:["maximum additional passengers = 16"]}],answer:"At most 16 more people can enter."},{q:"Ada has ₦1,200 and wants to save at least ₦2,000. If she saves ₦200 each week for w weeks, find the minimum number of weeks.",steps:[{text:"Her final savings must be at least ₦2,000.",math:["1200+200w ≥ 2000"]},{text:"Subtract 1200.",math:["200w ≥ 800"]},{text:"Divide by positive 200.",math:["w ≥ 4"]}],answer:"She needs at least 4 weeks."},{q:"A hall charges ₦5,000 plus ₦800 per chair. A group can spend no more than ₦17,800. Find the greatest number of chairs c.",steps:[{text:"Fixed charge plus chair cost must not exceed the budget.",math:["5000+800c ≤ 17800"]},{text:"Subtract ₦5,000.",math:["800c ≤ 12800"]},{text:"Divide by positive 800.",math:["c ≤ 16"]}],answer:"The greatest possible number is 16 chairs."}]},
{title:"17. Integer answers and real-life interpretation",body:["Sometimes algebra gives a decimal boundary, but the real quantity must be a whole number. People, books, buses and chairs are counted in whole numbers, so interpret the solution in context rather than reporting an impossible fraction of an object."],example:{q:"Tickets cost ₦700 each. You have at most ₦5,000. What is the greatest number of tickets t you can buy?",steps:[{text:"Form the spending limit.",math:["700t ≤ 5000"]},{text:"Divide by 700.",math:["t ≤ 5000/700","t ≤ 7.142..."]},{text:"Tickets must be whole. Eight tickets would exceed the budget, so use the greatest whole number allowed.",math:["t = 7 maximum"]}],answer:"7 tickets"}},
{title:"18. Verification: boundary test and sample-value test",body:["A strong solution is checked, especially when a negative sign reversal occurred. Test the boundary when equality is included or excluded, and test one value from the claimed solution side.","For a strict inequality such as x<4, x=4 should fail while a nearby allowed value such as x=3 should work. For x≤4, both x=4 and x=3 should work."],example:{q:"Check the solution x>−5 for −4x<20.",steps:[{text:"Test the excluded boundary x=−5.",math:["−4(−5)<20","20<20 ✗"]},{text:"Test an allowed value, x=0.",math:["−4(0)<20","0<20 ✓"]}],answer:"The checks support x > −5."}},
{title:"19. Quantitative reasoning and mastery mix",body:["A learner is ready to move on when the symbols, algebra, number-line direction and word interpretation all agree. Do not rely on a memorised arrow rule without understanding the comparison."],examples:[{q:"A learner solves −3x≤12 as x≤−4. Diagnose the error.",steps:[{text:"The learner divided by −3 but failed to reverse the sign.",math:["−3x ≤ 12","÷(−3)   ÷(−3)","x ≥ −4"]},{text:"Test x=0 to confirm the corrected side.",math:["−3(0)≤12","0≤12 ✓"]}],answer:"Correct solution: x ≥ −4."},{q:"Which is stronger: x<5 or x≤5?",steps:[{text:"Both allow every number below 5, but only one includes the boundary.",math:["x<5 excludes 5","x≤5 includes 5"]}],answer:"x<5 is more restrictive because 5 itself is excluded."}]}
],mistakes:["Do not treat < and ≤ as the same symbol; equality changes whether the boundary is included.","Reverse the inequality only when multiplying or dividing both sides by a negative number—not merely because a negative number appears somewhere.","Do not reverse the sign when adding or subtracting a negative number.","An open point excludes the boundary; a filled point includes it.","After solving, make the number-line shading agree with the inequality direction.","Translate ‘at most’ as ≤ and ‘at least’ as ≥.","In word problems, define the variable and interpret whether the answer must be a whole number.","Check sign-reversal answers with substitution so an incorrect direction is caught."]},
"Graph":{title:"Graphs and the Cartesian Plane",objectives:["Identify axes, origin and quadrants","Plot and read ordered pairs","Use a consistent graph scale","Prepare tables of values","Plot linear equations in two variables","Interpret linear graphs","Plot graphs from real-life situations","Solve quantitative reasoning problems"],sections:[
{title:"1. Cartesian plane foundation",body:["The Cartesian plane uses two perpendicular number lines. The horizontal line is the x-axis, the vertical line is the y-axis, and they meet at the origin (0,0).","Positive x is to the right, negative x to the left, positive y upward and negative y downward."],board:["             +y","              ↑","−x  ←────── (0,0) ──────→ +x","              ↓","             −y"]},
{title:"2. Ordered pairs and quadrants",body:["A point is written (x,y): move horizontally using x first, then vertically using y. Quadrants I, II, III and IV have sign patterns (+,+), (−,+), (−,−), (+,−). Points on axes are not in quadrants."],examples:[{q:"Plot the idea of (−3,2).",steps:[{text:"x=−3 means move 3 left.",math:["(0,0) → (−3,0)"]},{text:"y=2 means move 2 up.",math:["(−3,0) → (−3,2)"]}],answer:"Quadrant II."},{q:"Where is (0,−5)?",steps:[{text:"x=0 means no horizontal movement.",math:["(0,−5) → negative y-axis"]}],answer:"On the y-axis."}]},
{title:"3. Scale and accurate plotting",body:["Read the scale before plotting. Equal intervals on one axis must represent equal numerical changes. The x- and y-axes may use different scales if each is clearly labelled.","Choose a scale that uses the graph space sensibly, then label axes and units."],example:{q:"An axis reads 0,10,20,30 at equal intervals. Find one interval.",steps:[{text:"Compare neighbouring labels.",math:["20−10=10"]}],answer:"10 units."}},
{title:"4. Prepare a table of values",body:["Choose suitable x-values and substitute each into the linear equation to obtain y. Each completed pair becomes a point."],example:{q:"For y=2x+1, use x=−2,−1,0,1,2.",steps:[{text:"Substitute one value at a time.",math:["x=−2 → y=−3","x=−1 → y=−1","x=0 → y=1","x=1 → y=3","x=2 → y=5"]},{text:"Form ordered pairs.",math:["(−2,−3),(−1,−1),(0,1),(1,3),(2,5)"]}],answer:"Five points are ready to plot."}},
{title:"5. Draw a linear graph",body:["Plot the calculated points accurately and use a ruler to draw the straight line through them. Several points provide an accuracy check."],example:{q:"Find three points on y=x+2 for x=−2,0,2.",steps:[{text:"Substitute the known value into the stated rule because a coordinate on the graph must satisfy that relationship. Keep the replacement visible before simplifying.",math:["x=−2 → (−2,0)","x=0 → (0,2)","x=2 → (2,4)"]}],answer:"Plot and join the three points with a straight line."}},
{title:"6. Check whether a point lies on a line",body:["A point lies on the graph when its coordinates satisfy the equation."],examples:[{q:"Does (3,7) lie on y=2x+1?",steps:[{text:"Substitute x=3.",math:["2(3)+1=7 ✓"]}],answer:"Yes."},{q:"Does (2,6) lie on the same line?",steps:[{text:"Substitute x=2.",math:["2(2)+1=5","5≠6"]}],answer:"No."}]},
{title:"7. Read values and intercepts",body:["To read y for a known x, move from x to the line and across to y. The y-intercept occurs where x=0; the x-intercept occurs where y=0."],example:{q:"Find the intercepts of y=x−3.",steps:[{text:"To find where the graph meets the y-axis, use x=0 because every point on the y-axis has zero horizontal displacement. Substitute 0 before simplifying.",math:["y=−3 → (0,−3)"]},{text:"To find where the graph meets the x-axis, use y=0 because every point on the x-axis has zero vertical displacement. Substitute 0 and then solve for x.",math:["0=x−3","x=3 → (3,0)"]}],answer:"(0,−3) and (3,0)."}},
{title:"8. Real-life linear graphs",body:["Real-life axes must name quantities and units. Examples include distance against time, cost against quantity and savings against weeks. A straight line represents constant change when scales are uniform."],example:{q:"A cyclist travels 30 km in 2 h at constant speed. Find the rate.",steps:[{text:"Compare change in distance with change in time.",math:["rate=30 km/2 h","=15 km/h"]}],answer:"15 km/h"}},
{title:"9. Build a graph from a real-life rule",body:["If a service has a fixed ₦500 charge plus ₦200 per kilometre, cost C and distance d satisfy C=500+200d."],example:{q:"Find points for d=0,1,2,3.",steps:[{text:"Substitute each distance.",math:["d=0 → C=500","d=1 → C=700","d=2 → C=900","d=3 → C=1100"]},{text:"Write distance first.",math:["(0,500),(1,700),(2,900),(3,1100)"]}],answer:"These points form a straight-line cost graph."}},
{title:"10. Compare two linear graphs",body:["At the same horizontal value, compare the vertical values. An intersection represents a pair of values shared by both relationships."],example:{q:"A=300+100n and B=600+50n. Compare at n=6.",steps:[{text:"Evaluate both.",math:["A=900","B=900"]}],answer:"They are equal at n=6."}},
{title:"11. Quantitative reasoning",body:["If points expected to form a straight line do not align, check the table, signs and scale before drawing. The graph should help detect a wrong value."],example:{q:"For y=2x−1, which is wrong: (0,−1),(1,1),(2,2)?",steps:[{text:"Check by substitution.",math:["x=0 → −1 ✓","x=1 → 1 ✓","x=2 → 3"]}],answer:"(2,2) should be (2,3)."}},
{title:"12. Mastery standard",body:["A complete graph solution includes labelled axes, units where needed, a consistent scale, accurate points, a suitable straight line and an interpretation. NERDC expects learners to plot, read, interpret and apply linear graphs, not merely recognise axes."]}
,
{title:"13. Full table-to-graph workflow",body:["For y=2x−3, do not jump straight to a line. Choose x-values, substitute one at a time, record ordered pairs, choose a scale that contains every point, plot, then draw the straight line."],example:{q:"Complete y=2x−3 for x=−2,−1,0,1,2.",steps:[{text:"Substitute each x-value.",math:["x=−2 → y=−7","x=−1 → y=−5","x=0 → y=−3","x=1 → y=−1","x=2 → y=1"]},{text:"Write the coordinate pairs.",math:["(−2,−7),(−1,−5),(0,−3),(1,−1),(2,1)"]}],answer:"Plot these five points and join them with a straight line."}},
{title:"14. Reading a real-life graph",body:["A coordinate on a real-life graph must be translated back into the quantities and units on the axes. Reading two numbers without interpreting them is incomplete."],example:{q:"On a distance-time graph, what does (3,45) mean if x is hours and y is kilometres?",steps:[{text:"Read x first: 3 hours."},{text:"Read y second: 45 kilometres."}],answer:"After 3 hours, the distance is 45 km."}},
{title:"15. Constant rate from a straight graph",body:["A straight distance-time relationship can represent a constant rate. Compare changes in distance with changes in time."],example:{q:"A line passes through (1,20) and (4,80), where x is time in hours and y is distance in kilometres. Find the rate.",steps:[{text:"Read what each coordinate means. At 1 hour the distance is 20 km; at 4 hours it is 80 km. Rate compares how much the distance changed with how much the time changed."},{text:"Find the distance increase by subtracting the earlier distance from the later distance.",math:["distance change=80 km−20 km","=60 km"]},{text:"Find the corresponding time increase in the same way.",math:["time change=4 h−1 h","=3 h"]},{text:"Rate means distance change per unit time, so divide the 60 km change by the 3-hour change.",math:["rate=60 km/3 h","=20 km/h"]},{text:"Check the interpretation: at 20 km each hour, 3 additional hours produce 3×20=60 km, exactly the increase shown by the two graph points.",math:["3×20 km=60 km ✓"]}],answer:"The constant rate is 20 km/h."}},
{title:"16. Intercepts in context",body:["The y-intercept is the output when x=0. In a real situation, explain what that starting value means."],example:{q:"For C=500+200d, interpret the y-intercept.",steps:[{text:"Set d=0.",math:["C=500+200(0)=500"]}],answer:"₦500 is the starting cost before the distance charge."}},
{title:"17. Comparing two linear graphs",body:["An intersection represents a pair of values satisfying both relationships. This can answer when two costs, distances or other quantities become equal."],example:{q:"A costs 400+100d and B costs 200+150d. When are they equal?",steps:[{text:"Equate the costs.",math:["400+100d=200+150d","200=50d","d=4"]},{text:"Find the common cost.",math:["400+100(4)=800"]}],answer:"At d=4, both cost ₦800."}},
{title:"18. Build a graph rule from words",body:["Separate a fixed starting amount from the amount added per unit. Write the equation before making the table."],example:{q:"A taxi charges ₦600 plus ₦250 per kilometre. Write the rule and find 5 km cost.",steps:[{text:"Let d be distance and C be cost.",math:["C=600+250d"]},{text:"Substitute 5.",math:["C=600+250(5)=1850"]}],answer:"C=600+250d; 5 km costs ₦1,850."}},
{title:"19. Quantitative reasoning with a missing coordinate",body:["A point on a line must satisfy its equation. Substitute the known coordinate and solve for the missing one."],example:{q:"(k,11) lies on y=2x+3. Find k.",steps:[{text:"Because the point lies on the line, its x- and y-coordinates must make the equation true. Here x=k and y=11, so replace y by 11 and x by k.",math:["11=2k+3"]},{text:"We need k alone. The expression adds 3 after 2k, so undo that addition by subtracting 3 from both sides.",math:["11−3=2k+3−3","8=2k"]},{text:"Now 2k means 2×k. Undo multiplication by 2 by dividing both sides by 2.",math:["8/2=2k/2","4=k"]},{text:"Check by substituting x=4 into the original rule.",math:["y=2(4)+3","=8+3","=11 ✓"]}],answer:"k=4"}},
{title:"20. Detect a wrongly plotted point",body:["Test coordinates by substitution instead of trusting the drawing."],example:{q:"Which point is not on y=2x+1: (0,1),(1,3),(2,5),(3,8)?",steps:[{text:"Test each input.",math:["0→1 ✓","1→3 ✓","2→5 ✓","3→7, not 8"]}],answer:"(3,8)"}},
{title:"21. Graph verification checklist",body:["Check axis names and units, origin, uniform scale, table arithmetic, x-then-y plotting, point alignment and requested readings. A suspicious point should be recalculated rather than forced onto the line."]},
{title:"22. Mastery task",body:["Mastery means completing the whole chain: variables → equation → table → scale → coordinates → graph → reading → interpretation → quantitative problem."],example:{q:"A tank starts with 100 L and gains 25 L each minute. Give four graph points.",steps:[{text:"Write the rule.",math:["V=100+25t"]},{text:"Use t=0,2,4,6.",math:["(0,100),(2,150),(4,200),(6,250)"]}],answer:"The four points can be plotted to form the linear graph."}},{title:"23. Deep mastery: table, plot and interpretation",body:["A complete graph problem is not finished when points are plotted. Build the table correctly, choose and label axes and scales, plot ordered pairs, join only when the relationship supports it, then read what slope, intercepts and selected coordinates mean in context."],examples:[{q:"For y=3x−2, prepare values for x=−1,0,1,2.",steps:[{text:"Substitute each x separately so one arithmetic error does not contaminate the whole table.",math:["x=−1: y=3(−1)−2=−5","x=0: y=3(0)−2=−2","x=1: y=3(1)−2=1","x=2: y=3(2)−2=4"]},{text:"Pair each input with its output before plotting.",math:["(−1,−5),(0,−2),(1,1),(2,4)"]}],answer:"Plot the four ordered pairs and draw the straight line through them."},{q:"A distance-time graph rises from (1 h,18 km) to (4 h,72 km). Interpret the rate.",steps:[{text:"Distance increased by the later distance minus the earlier distance.",math:["72−18=54 km"]},{text:"The matching time increase is 4−1=3 hours.",math:["4−1=3 h"]},{text:"Rate compares these changes.",math:["54/3=18 km/h"]}],answer:"The constant rate is 18 km/h."}]}],mistakes:["Do not reverse (x,y).","Points on axes are not in quadrants.","Do not change scale along an axis.","Show substitution carefully for negative x-values.","Label real-life axes with quantities and units.","Check a suspicious point before drawing the line."]},
"Plane Figure/ Shapes":{title:"Plane Figures, Shapes and Scale Drawing",objectives:["Identify and describe common plane figures","State and use properties of parallelogram, rhombus and kite","Compare shapes using sides, angles, parallel lines and diagonals","Explain scale as a drawing-to-actual relationship","Convert units before using scale","Convert actual lengths to drawing lengths and drawing lengths to actual lengths","Make and interpret accurate scale drawings","Solve quantitative problems involving plane figures and scale"],sections:[
{title:"1. Plane figures are two-dimensional",body:["A plane figure is a flat shape with length and width. Classification should depend on mathematical properties, not on how a drawing happens to look.","Important properties include number of sides, equal sides, parallel sides, angle relationships, diagonals and symmetry."]},
{title:"2. Parallelogram",body:["A parallelogram has two pairs of opposite sides parallel. Opposite sides are equal, opposite angles are equal, adjacent angles add to 180°, and the diagonals bisect each other.","Its diagonals are not generally equal and do not generally meet at 90°, so those must not be assumed."],example:{q:"One angle of a parallelogram is 68°. Find an adjacent angle.",steps:[{text:"Adjacent angles are supplementary.",math:["68°+x=180°","x=112°"]}],answer:"112°"}},
{title:"3. Rhombus",body:["A rhombus is a parallelogram with all four sides equal. Opposite sides are parallel and opposite angles are equal. Its diagonals bisect each other at right angles and bisect opposite angles.","A square satisfies the properties of a rhombus, but a general rhombus need not have four right angles."],example:{q:"A rhombus has one angle 110°. Find the adjacent angle.",steps:[{text:"Adjacent angles in a parallelogram family sum to 180°.",math:["180°−110°=70°"]}],answer:"70°"}},
{title:"4. Kite",body:["A kite has two pairs of adjacent equal sides. In the usual convex kite, one pair of opposite angles is equal, the diagonals meet at right angles, and one diagonal bisects the other and acts as an axis of symmetry.","The equal sides are adjacent, not opposite. This distinguishes a kite description from a parallelogram description."]},
{title:"5. Compare the three shapes",body:["Parallelogram: opposite sides equal and parallel. Rhombus: all sides equal and opposite sides parallel. Kite: two pairs of adjacent equal sides.","Use several properties together when identifying a shape; one visible feature alone may not be enough."],board:["Parallelogram → opposite sides equal + parallel","Rhombus → all four sides equal + opposite sides parallel","Kite → two pairs of adjacent equal sides"]},
{title:"6. Meaning of scale drawing",body:["A scale drawing represents a real object using proportional lengths. A scale 1:100 means 1 unit on the drawing represents 100 of the same units in reality.","Before calculating, put drawing and actual lengths in the same unit. This prevents common factor-of-100 or factor-of-1000 errors."]},
{title:"7. Actual length to drawing length",body:["For a numerical scale 1:n, drawing length = actual length ÷ n after unit conversion."],examples:[{q:"At scale 1:200, represent a 10 m wall.",steps:[{text:"The scale ratio compares like units, so convert metres to centimetres first. Use 1 m=100 cm and show the multiplication before applying the scale.",math:["10 m=1000 cm"]},{text:"In a 1:n scale, n actual units are represented by 1 drawing unit. Therefore divide the actual length by n to find how many drawing units are needed.",math:["drawing=1000/200","=5 cm"]}],answer:"5 cm"},{q:"At scale 1:500, represent 35 m.",steps:[{text:"Convert and divide.",math:["35 m=3500 cm","3500/500=7 cm"]}],answer:"7 cm"}]},
{title:"8. Drawing length to actual length",body:["Actual length = drawing length × scale denominator. Convert the result to a sensible real-life unit."],examples:[{q:"On a 1:500 plan, two points are 7.2 cm apart. Find the actual distance.",steps:[{text:"The drawing uses scale 1:500, so each drawing centimetre represents 500 actual centimetres. Multiply the measured drawing length by 500 to recover the real length.",math:["7.2×500=3600 cm"]},{text:"The real length is currently in centimetres. Since 100 cm=1 m, divide by 100 so the final answer is expressed in metres as requested.",math:["3600/100=36 m"]}],answer:"36 m"},{q:"A road is 12 cm on a 1:25,000 map. Find its actual distance.",steps:[{text:"Multiply first.",math:["12×25,000=300,000 cm"]},{text:"Convert to kilometres.",math:["300,000 cm=3,000 m=3 km"]}],answer:"3 km"}]},
{title:"9. Statement scales",body:["A statement scale such as 1 cm represents 2 km can be used directly. Divide actual distance by 2 km to find drawing centimetres, or multiply drawing centimetres by 2 km to find actual distance."],example:{q:"Using 1 cm : 2 km, what map distance represents 14 km?",steps:[{text:"Every centimetre represents 2 km.",math:["14/2=7 cm"]}],answer:"7 cm"}},
{title:"10. Constructing a scale drawing",body:["State the scale, convert all measurements, draw a suitable base accurately, measure required angles with a protractor, mark scaled lengths, and label the completed figure.","Measurement from a scale drawing is meaningful only when the drawing itself is accurate. Keep pencil lines fine and read the ruler from zero."]},
{title:"11. Multi-step scale problem",body:["Some questions require both drawing and interpretation. Keep actual and drawing quantities clearly separated."],example:{q:"A rectangular field is 60 m by 40 m. Drawn at 1 cm : 10 m, what dimensions should appear on paper?",steps:[{text:"Convert each actual dimension using the statement scale.",math:["60/10=6 cm","40/10=4 cm"]}],answer:"6 cm by 4 cm"}},
{title:"12. Quantitative reasoning",body:["Check whether the answer is sensible. A scale 1:500 makes the drawing much smaller than reality; therefore a calculated drawing longer than the actual object signals an error.","NERDC expects learners to identify properties and apply scale drawing to actual lengths and distances, not merely memorise shape names."]}
,{title:"13. Property reasoning, not memorising names",body:["Use properties to identify an unknown quadrilateral. Ask about parallel sides, equal sides and angle relationships before naming the shape."],example:{q:"A quadrilateral has four equal sides and opposite sides parallel. What family does it belong to?",steps:[{text:"Start from the information, not from appearance. ‘Four equal sides’ means every side has the same length."},{text:"A rhombus is a quadrilateral whose four sides are equal; its opposite sides are also parallel. Both given properties therefore match a rhombus."},{text:"Do not automatically call it a square. A square would additionally require four right angles, and no right-angle information was given."}],answer:"The information identifies a rhombus; a square cannot be concluded without right-angle information."}},
{title:"14. Mixed-unit scale drawing",body:["Convert actual and drawing lengths to compatible units before using a numerical scale. A scale such as 1:500 does not mean 1 cm represents 500 m; it means one unit represents 500 of the same unit."],example:{q:"At scale 1:500, represent 35 m.",steps:[{text:"A scale of 1:500 compares lengths in the same unit: 1 cm on the drawing represents 500 cm in reality. The actual length is given in metres, so convert it to centimetres before using the ratio.",math:["1 m=100 cm","35 m=35×100 cm","=3500 cm"]},{text:"Now ask how many groups of 500 cm are contained in 3500 cm. Each group becomes 1 cm on the drawing.",math:["drawing length=3500/500 cm","=7 cm"]},{text:"Check by reversing the scale: 7 cm on the drawing should represent 7×500=3500 cm, which is 35 m.",math:["7×500=3500 cm","3500 cm=35 m ✓"]}],answer:"Draw 7 cm."}},
{title:"15. Recovering an actual dimension",body:["When the drawing is given, reverse the scale by multiplying by the scale denominator, then convert to the requested real-life unit."],example:{q:"A wall is 8.4 cm on a 1:250 plan. Find actual length in metres.",steps:[{text:"Multiply by 250.",math:["8.4×250=2100 cm"]},{text:"The real length is currently in centimetres. Since 100 cm=1 m, divide by 100 so the final answer is expressed in metres as requested.",math:["2100 cm=21 m"]}],answer:"21 m"}},
{title:"16. Scale drawing of a rectangular space",body:["A complete scale task requires every dimension to be converted, a suitable labelled drawing to be made, and measurements interpreted back in context."],example:{q:"Draw a 24 m by 15 m court at 1 cm:3 m. What dimensions go on paper?",steps:[{text:"Divide each actual dimension by 3 m per centimetre.",math:["24/3=8 cm","15/3=5 cm"]}],answer:"8 cm by 5 cm"}},
{title:"17. Quantitative aptitude with scale",body:["Some questions combine shape properties and scale. Solve the geometry first or the scale first according to what is unknown, then continue to the requested quantity."],example:{q:"A square park is 6 cm per side on a 1:400 drawing. Find its actual perimeter.",steps:[{text:"Recover one actual side.",math:["6×400=2400 cm=24 m"]},{text:"A square has four equal sides.",math:["perimeter=4×24=96 m"]}],answer:"96 m"}},
{title:"18. Mastery check for plane figures",body:["You should be able to identify parallelograms, rhombi and kites from properties, distinguish properties they share, convert scales in both directions, construct a scale representation and solve an unfamiliar quantitative problem."]},{title:"19. Deep mastery: properties and scale as separate skills",body:["First identify a shape from defining properties; then handle scale drawing as a measurement relationship. Do not use appearance as proof and do not mix units inside a numerical scale."],examples:[{q:"A quadrilateral has four equal sides but no right-angle information. What can you conclude?",steps:[{text:"Four equal sides satisfy the defining side property of a rhombus."},{text:"A square also has four equal sides, but a square additionally requires four right angles. Since right angles were not stated, do not assume them."}],answer:"It can be identified as a rhombus; there is not enough information to conclude it is a square."},{q:"A room is 12 m by 8 m. Draw it at 1 cm:2 m.",steps:[{text:"Each drawing centimetre represents 2 real metres, so divide each real dimension by 2.",math:["12÷2=6 cm","8÷2=4 cm"]},{text:"Check by reversing the scale.",math:["6×2=12 m","4×2=8 m"]}],answer:"Draw a 6 cm by 4 cm rectangle."}]}],mistakes:["Do not classify shapes only by appearance.","A rhombus need not have four right angles.","A kite's equal sides are adjacent pairs.","Convert units before applying a numerical scale.","Do not multiply when converting actual length to a 1:n drawing; divide by n.","State and use the scale consistently.","A rough sketch is not an accurate scale drawing."]},
"Angles":{title:"Angles, Polygons, Elevation and Depression",objectives:["Use triangle and quadrilateral angle sums","Derive and use polygon interior-angle sums","Solve missing-angle problems","Find angles of regular polygons","Distinguish elevation and depression","Measure angles from a horizontal reference","Use scale drawings for heights and distances","Solve quantitative angle problems"],sections:[
{title:"1. Angle foundation",body:["An angle measures turning between two rays at a vertex. A straight angle is 180° and a complete turn is 360°. These facts support the JSS2 polygon work."]},
{title:"2. Triangle and quadrilateral sums",body:["The interior angles of a triangle total 180°. A quadrilateral can be split into two triangles, so its interior angles total 360°."],examples:[{q:"A triangle has angles 48° and 67°. Find the third.",steps:[{text:"Add the known angles, then subtract from 180°.",math:["48°+67°=115°","180°−115°=65°"]}],answer:"65°"},{q:"A quadrilateral has 85°,110°,72° and x. Find x.",steps:[{text:"Use the 360° total.",math:["85+110+72=267°","x=360−267","=93°"]}],answer:"93°"}]},
{title:"3. Why polygon sum is (n−2)×180°",body:["From one vertex of a convex n-sided polygon, diagonals divide it into n−2 triangles. Each triangle contributes 180°, giving sum=(n−2)×180°.","The equivalent form (2n−4) right angles means (2n−4)×90°, which gives the same total."]},
{title:"4. Polygon interior-angle sums",body:["Identify the number of sides n, subtract 2, then multiply by 180°."],examples:[{q:"Find the sum for a hexagon.",steps:[{text:"n=6.",math:["(6−2)×180°","=720°"]}],answer:"720°"},{q:"Find the sum for a decagon.",steps:[{text:"n=10.",math:["(10−2)×180°","=1440°"]}],answer:"1440°"}]},
{title:"5. Missing angle in a polygon",body:["Find the polygon total first. Add the known interior angles and subtract their sum from the total."],example:{q:"A pentagon has 100°,120°,95°,110° and x. Find x.",steps:[{text:"Find the pentagon total.",math:["(5−2)×180°=540°"]},{text:"Add known angles and subtract.",math:["100+120+95+110=425°","x=540−425=115°"]}],answer:"115°"}},
{title:"6. Regular polygons",body:["A regular polygon has equal sides and equal interior angles. Divide the total interior-angle sum by n to find one interior angle."],example:{q:"Find one interior angle of a regular hexagon.",steps:[{text:"Find total and divide by six.",math:["total=720°","720°/6=120°"]}],answer:"120°"}},
{title:"7. Practical angle construction and measurement",body:["The school scheme includes practical work with angles such as 75°,105°,120° and135°. Put the protractor centre on the vertex, align the baseline with the starting arm and read from the correct zero.","Check whether the result should be acute, right or obtuse so a wrong protractor scale is noticed."]},
{title:"8. Horizontal reference line",body:["Elevation and depression are measured from a horizontal reference through the observer, never from a vertical object.","Elevation is measured upward from the horizontal. Depression is measured downward from the horizontal."]},
{title:"9. Angle of elevation",body:["When a person at a lower level views the top of a taller object, the angle between the horizontal reference and the upward viewing direction is the angle of elevation."],board:["top •","     /","    /","person •──────── horizontal"]},
{title:"10. Angle of depression",body:["When a person at a higher level views an object below, the angle between the horizontal reference and the downward viewing direction is the angle of depression.","Parallel horizontal references explain why the corresponding elevation and depression angles in the usual diagram are equal."]},
{title:"11. Scale-drawing method",body:["At JSS2, use the required measurement method: choose the stated scale, draw the known distance, construct the given angle, complete the geometric figure, measure the requested length, then convert back using the scale.","Do not replace a requested scale drawing with a later-class trigonometric method."]},
{title:"12. Convert a measured scale result",body:["The final ruler measurement is still a drawing length and must be converted to the actual length."],example:{q:"At scale 1 cm : 5 m, a measured height is 6.4 cm. Find the actual height.",steps:[{text:"Multiply by the real distance represented by each centimetre.",math:["6.4×5 m","=32 m"]}],answer:"32 m"}},
{title:"13. Quantitative reasoning",body:["Check the polygon type, number of sides, correct total, whether a regular-polygon division is required, whether the angle is elevation or depression, and whether a scale conversion remains.","A diagram is not assumed to be accurately scaled unless the question states that it is."]}
,{title:"14. Why the polygon formula works",body:["From one vertex of a convex n-sided polygon, diagonals can divide the polygon into n−2 triangles. Each triangle contributes 180°, so the interior-angle sum is (n−2)×180°. This is the same as (2n−4) right angles because one right angle is 90°."],board:["(n−2)×180° = (2n−4)×90°"]},
{title:"15. Constructing and recognising larger angles",body:["The school scheme includes angles such as 75°, 105°, 120° and 135°. Learners should recognise whether the angle is acute or obtuse, construct or measure it accurately, and verify it with a protractor."],examples:[{q:"Classify 75°.",steps:[{text:"75° is less than 90°."}],answer:"Acute angle."},{q:"Classify 135°.",steps:[{text:"135° is greater than 90° but less than 180°."}],answer:"Obtuse angle."}]},
{title:"16. Find number of sides from angle sum",body:["The polygon formula can be used in reverse. Form an equation with the given interior-angle sum and solve for n."],example:{q:"A convex polygon has interior-angle sum 1260°. How many sides?",steps:[{text:"Let n represent the unknown number of sides. A convex n-sided polygon can be divided from one vertex into n−2 triangles, and each triangle contributes 180°. Therefore its interior-angle sum is (n−2)×180°.",math:["(n−2)×180°=1260°"]},{text:"Undo the multiplication by 180 by dividing both sides by 180. This isolates n−2.",math:["n−2=1260/180","n−2=7"]},{text:"Undo the subtraction of 2 by adding 2 to both sides.",math:["n=7+2","n=9"]},{text:"Check by substituting 9 back into the formula.",math:["(9−2)×180°","=7×180°","=1260° ✓"]}],answer:"The polygon has 9 sides."}},
{title:"17. Regular polygon unknown angle",body:["For a regular polygon all interior angles are equal. First find the total interior-angle sum, then divide by the number of angles."],example:{q:"Find each interior angle of a regular octagon.",steps:[{text:"Find the total.",math:["(8−2)×180=1080°"]},{text:"Divide by 8.",math:["1080/8=135°"]}],answer:"135°"}},
{title:"18. Elevation scale-drawing method",body:["For an elevation problem, draw a horizontal baseline to scale, construct the given upward angle from the observer, and locate where that sight line meets the vertical object. Measure the vertical drawing length and convert it back using the scale."],example:{q:"A tree is 20 m horizontally from an observer. Using 1 cm:5 m, what baseline length is drawn?",steps:[{text:"Convert distance with the stated scale.",math:["20/5=4 cm"]}],answer:"Draw a 4 cm horizontal baseline before constructing the elevation angle."}},
{title:"19. Depression and corresponding elevation",body:["A horizontal line through the observer and a horizontal line through the lower object are parallel. The angle of depression and the corresponding angle of elevation are equal as alternate interior angles when the sight line crosses them."],example:{q:"The angle of depression from a tower to a car is 32°. What is the corresponding angle of elevation from the car?",steps:[{text:"The horizontal reference lines are parallel."},{text:"The sight line is a transversal, giving equal alternate angles."}],answer:"32°"}},
{title:"20. Quantitative angle reasoning",body:["Do not mix polygon-angle rules with elevation/depression methods. First identify the diagram type and the relationship being tested, then select the rule."],example:{q:"Three angles of a quadrilateral are 92°,88°,105°. Find the fourth.",steps:[{text:"Quadrilateral total is 360°.",math:["x=360−(92+88+105)","=360−285","=75°"]}],answer:"75°"}},{title:"21. Deep mastery: polygon and sight-line reasoning",body:["Angle work must identify the governing total before calculation. Elevation and depression additionally require a horizontal reference line and a correctly drawn line of sight."],examples:[{q:"A pentagon has four angles 110°,95°,120°,105°. Find the fifth.",steps:[{text:"A pentagon has n=5 sides, so its interior-angle sum is (5−2)×180°.",math:["3×180°=540°"]},{text:"Add the four known angles.",math:["110+95+120+105=430°"]},{text:"The missing angle is the remainder of the required 540° total.",math:["540−430=110°"]},{text:"Check that all five now total 540°."}],answer:"110°"},{q:"Why can an angle of depression from a tower equal the angle of elevation from the ground point?",steps:[{text:"Draw a horizontal through the observer at the top and another horizontal through the ground point. These horizontals are parallel."},{text:"The same line of sight crosses both parallel lines, forming equal alternate interior angles."}],answer:"The corresponding elevation and depression angles are equal because the horizontals are parallel and the sight line is a transversal."}]}],mistakes:["Triangle angles total 180° and quadrilateral angles 360°.","Use (n−2)×180° for a convex polygon's interior-angle sum.","Do not confuse the total with one regular-polygon angle.","Measure elevation and depression from horizontal.","Read the correct protractor scale.","Convert scale-drawing measurements back to actual units."]},
"Bearing":{title:"Bearings and Distances",objectives:["Identify major and minor cardinal points","Read and write three-digit bearings","Use compass bearings","Locate objects from a stated point","Measure distances using scale drawing","Find reverse bearings","Solve multi-point bearing problems"],sections:[
{title:"1. Cardinal-point foundation",body:["North, East, South and West are the major cardinal points. NE, SE, SW and NW are minor or intercardinal points. Every location statement needs a reference point."],board:["        N","   NW   ↑   NE","W  ←    +    →  E","   SW   ↓   SE","        S"]},
{title:"2. What a bearing tells us",body:["A bearing tells the direction of one object from another. The starting point matters. Distance tells how far apart the objects are, so many practical questions combine bearing and scale distance."]},
{title:"3. Three-digit bearings",body:["Measure clockwise from North at the starting point. Write three digits: North 000°/360°, East 090°, South 180°, West 270°. Thus 45° is written 045°."],example:{q:"Write a clockwise turn of 70° from North as a three-digit bearing.",steps:[{text:"The angle is below 100°, so include the leading zero.",math:["70° → 070°"]}],answer:"070°"}},
{title:"4. Compass bearings",body:["Compass notation states the reference direction and the direction of turn. N30°E means start from North and turn 30° toward East; S40°W means start from South and turn 40° toward West."],examples:[{q:"Convert N30°E to three-digit bearing.",steps:[{text:"From North the 30° turn toward East is clockwise.",math:["030°"]}],answer:"030°"},{q:"Convert S40°W.",steps:[{text:"South is 180°. Turning 40° toward West increases the clockwise angle.",math:["180°+40°=220°"]}],answer:"220°"}]},
{title:"5. Locate an object from bearing and distance",body:["Draw a North reference at the starting point. Measure the bearing clockwise, draw the direction ray, convert the actual distance with the stated scale, then mark the endpoint accurately."],example:{q:"A clinic is 6 km from a school on bearing 060°. Scale 1 cm : 2 km. Find the drawing distance.",steps:[{text:"Convert actual distance to drawing length.",math:["6 km ÷ 2 km per cm","=3 cm"]},{text:"Measure 060° clockwise from North and mark 3 cm along that ray."}],answer:"3 cm along bearing 060°."}},
{title:"6. Scale-distance conversion",body:["For 1 cm : 5 km, multiply a measured drawing length by 5 km to recover actual distance; divide an actual distance by 5 km to obtain drawing centimetres."],example:{q:"Two points measure 4.6 cm apart at 1 cm : 5 km. Find actual distance.",steps:[{text:"Each centimetre represents 5 km.",math:["4.6×5 km=23 km"]}],answer:"23 km"}},
{title:"7. Reverse bearings",body:["The reverse direction between the same two points differs by 180°. Add 180° when the original bearing is below 180°; subtract 180° when it is 180° or above."],examples:[{q:"B is on bearing 070° from A. Find A from B.",steps:[{text:"A reverse bearing points in the opposite direction, which is half a full turn away. Half of 360° is 180°, so add 180° when the original bearing is below 180°.",math:["070°+180°=250°"]}],answer:"250°"},{q:"Q is on bearing 235° from P. Find P from Q.",steps:[{text:"For a bearing above 180°, move half a turn in the opposite direction by subtracting 180°. This keeps the reverse bearing within 000°–359°.",math:["235°−180°=055°"]}],answer:"055°"}]},
{title:"8. Multi-point scale drawing",body:["Complete each position before using it as the reference for the next. Draw parallel North references at all points from which a bearing is measured."],example:{q:"B is 8 km from A on 090°. C is 6 km from B on 180°. Scale 1 cm : 2 km. Find drawing lengths.",steps:[{text:"Convert each distance.",math:["AB=8/2=4 cm","BC=6/2=3 cm"]}],answer:"AB=4 cm and BC=3 cm."}},
{title:"9. Measure bearing from a completed drawing",body:["At the requested starting point draw North, centre the protractor there, align zero with North and measure clockwise to the joining line. Report the answer with three digits."]},
{title:"10. Mastery and verification",body:["Check the reference point, clockwise direction, three-digit notation and distance scale. NERDC expects learners to locate objects and calculate distances between them, not merely recite cardinal points."]}
,{title:"11. Converting three-digit to compass bearing",body:["Compass bearings describe the acute or obtuse turn from North or South toward East or West. First locate the three-digit direction in the correct quadrant, then measure its angle from the nearer North/South reference."],examples:[{q:"Convert 130° to compass form.",steps:[{text:"130° lies between East 090° and South 180°."},{text:"Measure back from South.",math:["180°−130°=50°"]}],answer:"S50°E"},{q:"Convert 310°.",steps:[{text:"310° lies between West and North."},{text:"Measure from North toward West.",math:["360°−310°=50°"]}],answer:"N50°W"}]},
{title:"12. Bearing and distance together",body:["A full bearing problem has two independent pieces of information: direction from the bearing and separation from the distance. Construct the direction first, then mark the scaled distance on that ray."],example:{q:"B is 15 km from A on bearing 120°. Scale 1 cm:3 km. How is B located?",steps:[{text:"Convert distance.",math:["15/3=5 cm"]},{text:"At A draw North, measure 120° clockwise, draw the ray, then mark 5 cm from A."}],answer:"B is the point 5 cm along the 120° ray."}},
{title:"13. Finding a bearing from a drawing",body:["To measure the bearing of B from A, centre the protractor at A, align 0° with the North line at A and read clockwise to AB. Reverse the reference point when asked for A from B."]},
{title:"14. Reverse direction as a check",body:["After finding a bearing, its reverse should differ by 180°. This is a powerful check on measured or calculated answers."],example:{q:"A measured bearing is 146°. Find and check its reverse.",steps:[{text:"A reverse bearing points in the exactly opposite direction along the same straight line. Opposite directions differ by 180°."},{text:"The original bearing 146° is less than 180°, so adding 180° keeps the result within the three-digit bearing range below 360°.",math:["146°+180°=326°"]},{text:"Write the answer with three digits. Then check by reversing 326°: because 326° is above 180°, subtract 180°.",math:["326°−180°=146° ✓"]}],answer:"The reverse bearing is 326°."}},
{title:"15. Multi-stage location problem",body:["When a journey changes direction, each new bearing starts from a North reference at the new point, not from the previous path."],example:{q:"At 1 cm:2 km, B is 8 km from A on 090°, then C is 6 km from B on 180°. Give drawing lengths.",steps:[{text:"Convert each leg.",math:["AB=8/2=4 cm","BC=6/2=3 cm"]},{text:"Draw 4 cm East from A; at B draw a new North line and then 3 cm South."}],answer:"AB=4 cm and BC=3 cm."}},
{title:"16. Bearing mastery",body:["Mastery requires major/minor cardinal points, three-digit and compass forms, locating an object, converting scale distance both ways, measuring a bearing from a completed drawing, finding reverse bearing and completing multi-point problems."]},
{title:"17. Bearings by quadrant: four families",body:["Do not memorise conversions as isolated tricks. First decide which quadrant the direction lies in. The quadrant tells you whether the compass form starts from North or South and whether the turn is toward East or West.","Quadrant I: 000°–090° gives NθE. Quadrant II: 090°–180° gives S(180°−θ)E. Quadrant III: 180°–270° gives S(θ−180°)W. Quadrant IV: 270°–360° gives N(360°−θ)W."],examples:[{q:"Convert 065° to compass bearing.",steps:[{text:"065° lies between North 000° and East 090°, so it is in the north-east quadrant. Start from North and turn toward East."},{text:"The clockwise turn from North is already 65°.",math:["065° = N65°E"]}],answer:"N65°E"},{q:"Convert 145° to compass bearing.",steps:[{text:"145° lies between East 090° and South 180°, so use South as the nearer north/south reference and turn toward East."},{text:"Find the angle between 145° and South 180°.",math:["180°−145°=35°"]}],answer:"S35°E"},{q:"Convert 225° to compass bearing.",steps:[{text:"225° lies between South 180° and West 270°. Start from South and turn toward West."},{text:"Find the turn beyond South.",math:["225°−180°=45°"]}],answer:"S45°W"},{q:"Convert 315° to compass bearing.",steps:[{text:"315° lies between West 270° and North 360°. Start from North and turn toward West."},{text:"Find the smaller angle from North.",math:["360°−315°=45°"]}],answer:"N45°W"}]},
{title:"18. Compass bearing back to three-digit bearing",body:["Reverse the quadrant reasoning carefully. Three-digit bearings always start at North and move clockwise, even when the compass bearing starts from South."],examples:[{q:"Convert S25°E to a three-digit bearing.",steps:[{text:"South is 180°. S25°E means begin at South and turn 25° toward East. East lies before South when measuring clockwise from North, so subtract 25° from 180°.",math:["180°−25°=155°"]}],answer:"155°"},{q:"Convert N40°W.",steps:[{text:"North is both 000° and 360°. N40°W means approach North from the western side, so subtract 40° from 360°.",math:["360°−40°=320°"]}],answer:"320°"}]},
{title:"19. ‘B from A’ versus ‘A from B’",body:["The word FROM identifies the starting/reference point. In ‘bearing of B from A’, stand at A, draw North at A, then measure clockwise until the line AB. Reversing the wording changes the starting point and normally changes the bearing by 180°."],examples:[{q:"B is on bearing 082° from A. State clearly what this means.",steps:[{text:"The phrase ‘B from A’ puts the observer at A."},{text:"Draw the North line through A and turn clockwise 82°. B lies somewhere on that ray."}],answer:"From A, B lies in direction 082°."},{q:"If B from A is 082°, find A from B.",steps:[{text:"The reverse direction is half a turn, or 180°, away.",math:["082°+180°=262°"]}],answer:"262°"}]},
{title:"20. Constructing a location accurately",body:["A scale-bearing construction has a fixed order: mark the starting point → draw its North reference → measure the bearing clockwise → draw a thin direction ray → convert the real distance to drawing distance → measure that distance from the starting point along the ray → label the endpoint.","Do not measure the distance before establishing the correct ray; otherwise a correct length can still place the object in the wrong position."],example:{q:"A health centre H is 18 km from school S on bearing 135°. Use 1 cm:3 km.",steps:[{text:"The drawing needs one centimetre for every 3 km. Divide the actual distance by 3 km per centimetre.",math:["SH=18 km÷3 km per cm","=6 cm"]},{text:"At S draw North. Measure 135° clockwise from North and draw the ray."},{text:"Measure exactly 6 cm from S along that ray and mark H."},{text:"Check both independent conditions: direction should read 135° and scaled distance 6 cm should represent 18 km.",math:["6×3 km=18 km ✓"]}],answer:"H is 6 cm from S along the 135° ray."}},
{title:"21. Measuring an unknown bearing from a map",body:["When a diagram already gives the positions, the bearing is obtained by measurement rather than by guessing a compass direction. The protractor centre must sit exactly at the requested starting point, its 0°/North reference must align with the North line, and the reading must be taken clockwise."],example:{q:"A measured clockwise angle from North at P to PQ is 47°. How should the bearing be reported?",steps:[{text:"The measured direction is 47° clockwise from North."},{text:"Three-digit notation requires three figures, so place a leading zero before 47.",math:["47° → 047°"]}],answer:"Bearing of Q from P = 047°."}},
{title:"22. Scale drawing: recover a real distance",body:["If the map distance is measured in centimetres, multiply by the real distance represented by each centimetre. Keep the bearing angle separate: the scale changes lengths, not angles."],examples:[{q:"On a scale drawing 1 cm:4 km, A and B are 7.5 cm apart. Find the real distance.",steps:[{text:"Each one centimetre represents 4 km. There are 7.5 such centimetres.",math:["actual distance=7.5×4 km","=30 km"]},{text:"Check the unit: a map measurement in centimetres has been converted to a real distance in kilometres."}],answer:"30 km"},{q:"A real distance is 42 km and the scale is 1 cm:6 km. Find its drawing length.",steps:[{text:"Each centimetre can represent 6 km. Ask how many groups of 6 km are contained in 42 km.",math:["drawing length=42÷6","=7 cm"]}],answer:"7 cm"}]},
{title:"23. Multi-point bearing construction",body:["For a second journey leg, create a new North line at the new starting point. All North lines on the same map must be parallel because geographic North has not changed.","A common error is measuring the second bearing from the first journey line. Bearings are measured from North, not from the previous route."],example:{q:"B is 10 km from A on 060°. C is 8 km from B on 150°. Use 1 cm:2 km.",steps:[{text:"Convert both real distances to drawing lengths.",math:["AB=10÷2=5 cm","BC=8÷2=4 cm"]},{text:"At A draw North, measure 060° clockwise and mark B 5 cm along the ray."},{text:"At B draw another North line parallel to the North line at A. Measure 150° clockwise from this new North line."},{text:"Mark C exactly 4 cm from B along the 150° ray."}],answer:"The completed scale drawing has AB=5 cm on 060° and BC=4 cm on 150°."}},
{title:"24. Quantitative reasoning: missing scale",body:["Sometimes the drawing and real distance are known but the scale is missing. Find how much real distance one drawing centimetre represents."],example:{q:"Two towns are 36 km apart and 6 cm apart on a map. Express the scale as 1 cm : ? km.",steps:[{text:"Six drawing centimetres represent 36 km. Divide the real distance equally among the six centimetres.",math:["36 km÷6=6 km per cm"]},{text:"State the scale in the requested form."}],answer:"1 cm : 6 km"}},
{title:"25. Quantitative reasoning: reverse plus scale",body:["A problem may combine direction and distance. Treat them separately: reverse the direction using 180°, and convert the distance using the scale. Then bring both results together."],example:{q:"B is 24 km from A on bearing 118°. Find the bearing of A from B and the map length at 1 cm:4 km.",steps:[{text:"118° is below 180°, so add 180° for the opposite direction.",math:["118°+180°=298°"]},{text:"Convert 24 km to map centimetres.",math:["24÷4=6 cm"]}],answer:"A from B is 298°, and AB is 6 cm on the map."}},
{title:"26. Bearing error clinic",body:["If an answer is wrong, diagnose the type of error. An anticlockwise measurement is a direction error. Missing a leading zero is a notation error. Measuring from the destination instead of the reference point is a viewpoint error. Scaling the angle is a category error. Using the previous route instead of a new North line is a multi-stage construction error.","A learner who can name the error is less likely to repeat it."]},
{title:"27. NERDC mastery task",body:["To demonstrate full curriculum mastery, the learner should be able to identify major/minor cardinal points, interpret and convert three-digit and compass bearings, locate objects from a reference point, construct a bearing-and-distance diagram to scale, measure a bearing from a completed drawing, and determine real distance from a scale drawing.","Reverse bearings and multi-stage routes deepen the core work and provide textbook-standard quantitative reasoning."],example:{q:"On a map, market M is 5 cm from school S on bearing 210°. Scale 1 cm:3 km. State the compass bearing, real distance and reverse bearing.",steps:[{text:"210° lies between South 180° and West 270°. Find the angle west of South.",math:["210°−180°=30°","compass bearing=S30°W"]},{text:"Convert the 5 cm map distance using 3 km for every centimetre.",math:["5×3=15 km"]},{text:"Find the opposite direction. Since 210° is above 180°, subtract 180°.",math:["210°−180°=030°"]},{text:"Check: 210° and 030° differ by 180°, and the distance remains 15 km in either direction."}],answer:"M from S is S30°W (210°), distance 15 km; S from M is 030°."}}],mistakes:["Measure three-digit bearings clockwise from North.","Use the correct starting point.","Keep leading zeroes such as 045°.","Do not confuse bearing with distance.","Reverse bearings differ by 180°.","Apply the scale to distance, not to the bearing angle.","Use parallel North references in multi-point drawings."]},
"Construction":{title:"Geometrical Construction",objectives:["Explain the purpose of geometrical construction","Use ruler, compasses and protractor appropriately","Construct triangles from three sides","Construct triangles from two sides and the included angle","Construct triangles from two angles and the included side","Bisect an angle accurately","Retain construction arcs as mathematical evidence","Check completed constructions by measurement"],sections:[
{title:"1. Construction is more than a sketch",body:["A sketch shows an approximate shape. A geometrical construction creates a figure from stated measurements and geometric relationships. Accuracy and visible construction marks matter.","Use a sharp pencil, ruler for straight lines, compasses for equal radii and arcs, and a protractor when the stated school method requires measured angles."]},
{title:"2. Before constructing a triangle",body:["Read which measurements are known and identify the construction case. JSS2 work includes three sides (SSS), two sides and the included angle (SAS), and two angles with the side between them (ASA).","A labelled rough plan can help decide which measurement belongs at each vertex before the accurate construction begins."]},
{title:"3. SSS: three sides known",body:["Draw one known side as a base. From one endpoint draw an arc whose radius equals the second side. From the other endpoint draw an arc whose radius equals the third side. Their intersection fixes the third vertex."],example:{q:"Construct ABC with AB=6 cm, AC=5 cm and BC=4 cm.",steps:[{text:"Begin with the stated base because it gives two fixed vertices. Use a ruler to draw it to the exact given length and label both endpoints before using the compasses.",math:["AB=6 cm"]},{text:"Use A as centre with radius 5 cm; draw an arc.",math:["AC=5 cm"]},{text:"Use B as centre with radius 4 cm; draw an intersecting arc.",math:["BC=4 cm"]},{text:"Call the intersection C and join AC and BC. Check all three sides."}],answer:"The three given lengths determine triangle ABC."}},
{title:"4. Why SSS arcs work",body:["Every point on the arc centred at A is exactly the chosen distance from A. Every point on the arc centred at B is the chosen distance from B. Their intersection therefore satisfies both required side lengths at once."]},
{title:"5. SAS: two sides and included angle",body:["The included angle is the angle between the two given sides. Draw one side, construct or measure the included angle at its correct endpoint, mark the second side length along that ray, then join the remaining vertices."],example:{q:"Construct PQ=7 cm, PR=5 cm and angle QPR=60°.",steps:[{text:"Draw PQ=7 cm."},{text:"At P construct a 60° ray from PQ."},{text:"On the ray mark R so PR=5 cm."},{text:"Join R to Q and verify the given measurements."}],answer:"Triangle PQR is constructed by SAS."}},
{title:"6. Common SAS error",body:["If the question gives two sides and their included angle, placing the angle at the wrong vertex changes the triangle. Read the three-letter angle name carefully: the middle letter is the vertex."],example:{q:"In angle ABC, which point is the vertex?",steps:[{text:"The middle letter names the vertex.",math:["∠ABC → vertex B"]}],answer:"B"}},
{title:"7. ASA: two angles and included side",body:["Draw the given side first. At each endpoint construct the stated angle on the same side of the base. Extend the two rays until they intersect; that intersection is the third vertex."],example:{q:"Construct XY=6 cm, angle YXZ=50° and angle XYZ=70°.",steps:[{text:"Draw XY=6 cm."},{text:"At X draw a 50° ray."},{text:"At Y draw a 70° ray on the same side of XY."},{text:"Their intersection is Z. Join and check."}],answer:"Triangle XYZ is fixed by the side and two angles."}},
{title:"8. Bisecting an angle",body:["To bisect means divide into two equal parts. The compass method creates a point equally related to the two arms, allowing a line from the vertex to split the angle equally."],example:{q:"Bisect angle A.",steps:[{text:"Centre at A and draw an arc cutting the two arms at P and Q."},{text:"Without changing to unequal radii, draw arcs from P and Q that intersect at R."},{text:"Join A to R.",math:["∠PAR=∠RAQ"]}],answer:"AR is the angle bisector."}},
{title:"9. Why equal compass radii matter",body:["The intersecting arcs from P and Q must use the same radius. That symmetry is what places R equally from P and Q and makes AR the bisecting line. Random unequal arcs do not establish the required equality."]},
{title:"10. Verification",body:["Measure the completed sides and angles against the given data. Small drawing tolerances may occur, but a large difference indicates an inaccurate arc, wrong radius, wrong vertex or wrong protractor reading.","Do not erase the useful arcs before checking; they show how the construction was obtained."]},
{title:"11. Quantitative reasoning",body:["A construction question tests reading as much as drawing. Identify the case, assign each measurement to the correct side or vertex, perform one construction action at a time, then verify.","NERDC specifically requires triangle construction and angle bisection, so learners should be able to explain the procedure as well as reproduce it."]}
,{title:"12. Construction existence check",body:["Before drawing SSS, the two shorter side lengths together must be greater than the longest side. If not, the required arcs cannot meet to form a triangle."],example:{q:"Can sides 3 cm,4 cm,8 cm form a triangle?",steps:[{text:"Add the two shorter sides.",math:["3+4=7"]},{text:"Compare with the longest side.",math:["7<8"]}],answer:"No. The sides cannot form a triangle."}},
{title:"13. SSS with verification",body:["After the two arcs intersect, join the vertex and measure all three sides. The verification is part of the construction process, not an optional decoration."],example:{q:"For sides 7 cm,6 cm,5 cm, which radii can be used if 7 cm is the base?",steps:[{text:"Draw the 7 cm base."},{text:"Use the remaining given side lengths as radii from opposite endpoints."}],answer:"Use radii 6 cm and 5 cm."}},
{title:"14. SAS construction reasoning",body:["SAS determines a triangle only when the stated angle is the included angle between the two known sides. Read the angle notation before putting the protractor at a vertex."]},
{title:"15. ASA and the third angle",body:["Two given angles already determine the third angle because triangle angles total 180°. This provides a verification after construction."],example:{q:"A triangle is constructed with angles 50° and 70°. What should the third angle measure?",steps:[{text:"The three interior angles of every triangle add to 180°. The two known angles use part of that total.",math:["50°+70°=120°"]},{text:"The third angle is the part of 180° that remains, so subtract the known total.",math:["third angle=180°−120°","=60°"]},{text:"Check by adding all three angles.",math:["50°+70°+60°=180° ✓"]}],answer:"The third angle should measure 60°."}},
{title:"16. Angle-bisector proof check",body:["After constructing the bisector, use a protractor to check that the two resulting angles are equal. If the original angle is 86°, each should be about 43°."],example:{q:"An 86° angle is bisected. Find each part.",steps:[{text:"Bisect means divide into two equal angles.",math:["86/2=43°"]}],answer:"43° and 43°"}},
{title:"17. Diagnose construction errors",body:["If arcs do not meet, check whether the radii match the stated sides and whether a triangle is possible. If an angle is wrong, check the correct vertex, protractor baseline and direction of reading. If a bisector is unequal, check that equal-radius arcs were used."]},
{title:"18. Construction mastery",body:["A learner should be able to identify SSS/SAS/ASA from words, plan the base, carry out the construction in order, retain meaningful arcs, label the result and verify every given measurement."]},{title:"19. Deep mastery: SSS, SAS, ASA and bisection",body:["Construction is a sequence of geometric constraints, not a sketch. Every ruler line, measured ray and compass arc must have a reason, and the final figure must be checked against the given data."],examples:[{q:"Construct a triangle with sides 5 cm,6 cm,7 cm.",steps:[{text:"Use 7 cm as a convenient base AB.",math:["AB=7 cm"]},{text:"C must be exactly 5 cm from A, so draw an arc centred at A with radius 5 cm."},{text:"C must also be exactly 6 cm from B, so draw an arc centred at B with radius 6 cm. Their intersection satisfies both distance conditions."},{text:"Join AC and BC, then measure all three sides to verify."}],answer:"The intersection of the 5 cm and 6 cm arcs fixes C and completes the SSS triangle."},{q:"Bisect an 80° angle without measuring 40° directly.",steps:[{text:"With the compass centred at the vertex, draw one arc cutting both arms. The two cut points are equally distant from the vertex."},{text:"Using the same compass radius from those two cut points, draw arcs that intersect inside the angle."},{text:"Join the original vertex to the new arc intersection. Equal-radius construction makes the two resulting angles equal."},{text:"A protractor check should show approximately 40° and 40°."}],answer:"The constructed ray is the angle bisector."}]}],mistakes:["A freehand sketch is not an exact construction.","Keep useful construction arcs visible.","In SAS use the included angle at the correct vertex.","In ASA put both angles at the correct endpoints of the given side.","Use equal compass radii when required.","Read the middle letter of an angle name as its vertex.","Verify the completed figure against the given measurements."]},
"Data Presentation":{title:"Data Presentation",objectives:["Distinguish raw and ordered data","Organise observations into frequency tables","Check frequencies against the data total","Explain and calculate pie-chart sector angles","Construct and interpret pie charts","Find median and quartiles using a stated school convention","Calculate and interpret interquartile range","Describe the five-number summary","Construct and compare box plots","Interpret data in everyday contexts"],sections:[
{title:"1. What data are",body:["Data are collected facts, measurements or observations. Raw data appear in the order collected. Before analysing them, we often organise them so patterns become visible.","Data may come from school, home, market, community or simple investigations. The source and what each value represents should be stated clearly."]},
{title:"2. Ordered data",body:["Arrange numerical data from least to greatest before locating median, quartiles or range. Ordering does not change the observations; it changes only their presentation."],example:{q:"Order 8,3,5,3,10,6.",steps:[{text:"Place values from smallest to largest and keep repeated values.",math:["3,3,5,6,8,10"]}],answer:"3,3,5,6,8,10"}},
{title:"3. Frequency",body:["Frequency is the number of times a value or category occurs. Tally marks can help count repeated observations before writing numerical frequencies.","A vital check is that the sum of frequencies equals the total number of observations."]},
{title:"4. Frequency table",body:["List each distinct value or category once, then record its frequency."],example:{q:"Make frequencies for 2,3,2,5,3,2,4.",steps:[{text:"Go through the raw data systematically and tally every occurrence. Each observation must contribute to exactly one frequency so that none is lost or counted twice.",math:["2 → 3","3 → 2","4 → 1","5 → 1"]},{text:"Add all category frequencies and compare the sum with the number of raw observations. Equality confirms that every observation has been accounted for.",math:["3+2+1+1=7","number of observations=7 ✓"]}],answer:"2:3, 3:2, 4:1, 5:1"}},
{title:"5. Pie chart foundation",body:["A pie chart represents the whole data set by a complete circle of 360°. Each category receives a sector proportional to its frequency.","Sector angle = category frequency ÷ total frequency × 360°. Establish this relationship before substituting numbers."],board:["sector angle = category frequency/total frequency × 360°"]},
{title:"6. Calculate sector angles",body:["Find the total first, then calculate each category angle. The completed sector angles should add to 360°."],example:{q:"In a survey of 40 learners, 10 choose football. Find the football sector.",steps:[{text:"Football is 10 out of 40.",math:["angle=10/40×360°","=1/4×360°","=90°"]}],answer:"90°"}},
{title:"7. Read a pie chart backwards",body:["If a sector angle is known, sector fraction = angle/360°. Multiply that fraction by the total number of observations to recover the category frequency."],example:{q:"A 90° sector represents books in a survey of 80 learners. How many chose books?",steps:[{text:"First identify what the 90° means. A complete pie chart is one full circle, and a full circle contains 360°. The books sector occupies 90° out of those 360°, so the fraction of all learners represented by books is sector angle divided by the whole-circle angle.",math:["fraction for books = 90°/360°"]},{text:"Now simplify 90/360. Both numerator and denominator are divisible by 90. Dividing both by the same number does not change the value of the fraction.",math:["90÷90 = 1","360÷90 = 4","90/360 = 1/4"]},{text:"So one quarter of all 80 learners chose books. To find one quarter of 80, divide 80 into 4 equal groups. This is the same as multiplying 80 by 1/4.",math:["1/4 × 80 = 80÷4","= 20"]},{text:"Interpret the answer in the original survey. The calculation produced a number of learners, not an angle. Check it by reversing the process: 20 out of 80 is 1/4, and 1/4 of 360° is 90°.",math:["20/80 = 1/4","1/4 × 360° = 90° ✓"]}],answer:"20 learners chose books."}},
{title:"8. Constructing a pie chart",body:["Calculate all sector angles, check their sum is 360°, draw a circle, mark a radius, measure each sector successively with a protractor, then label sectors or provide a clear key.","Rounding should be controlled so the final angles still make a complete circle."]},
{title:"9. Median and quartile foundation",body:["The median divides ordered data into lower and upper halves. Q1 describes the centre of the lower half and Q3 the centre of the upper half.","For school work, use the convention taught by the course consistently. AVORA uses the median-of-halves convention in its worked examples and states it explicitly when an even data set is involved."]},
{title:"10. Interquartile range",body:["The interquartile range, IQR, measures the spread of the middle 50% of the ordered data. It is calculated as Q3−Q1. It is not the same as the full range maximum−minimum."],example:{q:"For 2,4,5,7,8,10,12,14 find IQR using median-of-halves.",steps:[{text:"Lower half is 2,4,5,7. Find its median.",math:["Q1=(4+5)/2=4.5"]},{text:"Upper half is 8,10,12,14.",math:["Q3=(10+12)/2=11"]},{text:"Interquartile range measures the width of the middle half of the data, so subtract the lower quartile Q1 from the upper quartile Q3, keeping the order Q3−Q1.",math:["IQR=Q3−Q1","=11−4.5","=6.5"]}],answer:"6.5"}},
{title:"11. Five-number summary",body:["A box plot is built from minimum, Q1, median, Q3 and maximum. These five values describe position and spread without listing every observation."],board:["minimum | Q1 | median | Q3 | maximum"]},
{title:"12. Constructing a box plot",body:["Draw a suitable number-line scale. Mark Q1 and Q3 and draw the box between them. Mark the median inside the box. Extend whiskers from the box to the minimum and maximum.","The box width represents the IQR. The whiskers show the outer spread to the minimum and maximum."]},
{title:"13. Comparing box plots",body:["Compare medians to discuss typical central position and compare IQRs to discuss the spread of the middle half. A larger IQR means the middle 50% is more spread out.","Do not claim that one data set is universally ‘better’ from a box plot alone; state the specific comparison supported by the graph."]},
{title:"14. Data interpretation",body:["A good interpretation returns to the real context: what was measured, how many observations were collected, which category is largest, or how spread differs.","NERDC expects learners to present and interpret data, so calculation without a meaningful statement is incomplete."]}
,{title:"15. Collecting and cleaning local data",body:["NERDC expects data from familiar settings such as home, school and market. State the question being investigated, collect observations consistently, then check for omissions or impossible entries before presenting them."],example:{q:"A class records books read by 10 learners: 2,1,3,2,4,2,1,3,2,5. What should happen before graphing?",steps:[{text:"Order or tabulate the values and confirm there are 10 observations."},{text:"Count frequencies.",math:["1→2","2→4","3→2","4→1","5→1","total=10"]}],answer:"Use the checked frequency table as the basis for presentation."}},
{title:"16. Pie chart with several categories",body:["For a complete pie chart, calculate every sector, not one isolated angle. Check the total is 360° before drawing."],example:{q:"Preferences A=12, B=9, C=6, D=3. Find all sector angles.",steps:[{text:"A pie chart represents every observation in one 360° circle. First find how many observations the whole circle represents.",math:["total=12+9+6+3","=30"]},{text:"Category A contains 12 of the 30 observations. Its sector must therefore occupy 12/30 of the full 360°.",math:["A angle=12/30×360°","=12×12°","=144°"]},{text:"Repeat the same fraction-of-the-whole reasoning for B, C and D.",math:["B=9/30×360°=108°","C=6/30×360°=72°","D=3/30×360°=36°"]},{text:"Check that no part of the circle is missing or counted twice. All sector angles must total one complete revolution.",math:["144°+108°+72°+36°=360° ✓"]}],answer:"A=144°, B=108°, C=72°, D=36°."}},
{title:"17. Reading frequency from a sector",body:["Reverse a pie-chart calculation when an angle and total are known."],example:{q:"A 72° sector belongs to a survey of 150 people. Find its frequency.",steps:[{text:"A full pie chart is 360°. Divide the given sector angle by 360° to determine what fraction of the complete data set that sector represents.",math:["72/360=1/5"]},{text:"The sector fraction tells us what part of all 150 observations belongs to the category. Multiply that fraction by 150 to convert the share into an actual frequency.",math:["1/5×150=30"]}],answer:"30 people"}},
{title:"18. Quartiles with odd-sized data",body:["Order the values first and state the convention. With the median-of-halves convention used in AVORA, exclude the overall median before finding Q1 and Q3 for an odd number of observations."],example:{q:"Find Q1, median and Q3 for 2,4,5,7,9,10,13.",steps:[{text:"The middle value is 7.",math:["median=7"]},{text:"Lower half is 2,4,5; upper half is 9,10,13.",math:["Q1=4","Q3=10"]}],answer:"Q1=4, median=7, Q3=10"}},
{title:"19. Build the five-number summary",body:["Find minimum, Q1, median, Q3 and maximum in that order before drawing a box plot."],example:{q:"For 2,4,5,7,9,10,13, give the five-number summary.",steps:[{text:"Use the ordered data and quartiles.",math:["minimum=2","Q1=4","median=7","Q3=10","maximum=13"]}],answer:"(2,4,7,10,13)"}},
{title:"20. Compare two data sets using IQR",body:["Use the median to compare central position and IQR to compare the spread of the middle 50%. Avoid conclusions not supported by these summaries."],example:{q:"Class A has Q1=42,Q3=58; Class B has Q1=45,Q3=54. Which middle half is more spread?",steps:[{text:"Calculate both IQRs.",math:["A:58−42=16","B:54−45=9"]}],answer:"Class A has the larger middle-half spread."}},
{title:"21. Interpret, do not merely calculate",body:["After a table, pie chart or box plot, state what the result means in context: largest category, relative share, typical position or spread. This fulfils the curriculum expectation to interpret data and explain usefulness in everyday life."]},
{title:"22. Data-presentation mastery",body:["Mastery means collecting sensible data, ordering it, building/checking frequencies, converting between frequencies and pie sectors, finding quartiles and IQR, constructing a five-number summary/box plot, comparing distributions and writing a contextual interpretation."]},{title:"23. Deep mastery: from raw data to judgment",body:["Statistics should move from organising data to interpreting it. Frequency, pie sectors, quartiles, IQR and box plots are representations of the same underlying observations, and conclusions must be tied to what those measures actually show."],examples:[{q:"For 2,4,5,7,8,10,12,14 find Q1, Q3 and IQR using the median-of-halves method.",steps:[{text:"The data are already ordered. Split the eight values into two equal halves.",math:["lower: 2,4,5,7","upper: 8,10,12,14"]},{text:"Q1 is the median of the lower half.",math:["Q1=(4+5)/2=4.5"]},{text:"Q3 is the median of the upper half.",math:["Q3=(10+12)/2=11"]},{text:"IQR measures the width of the middle 50%.",math:["IQR=Q3−Q1=11−4.5=6.5"]}],answer:"Q1=4.5, Q3=11, IQR=6.5."},{q:"Class A has IQR 4 and Class B has IQR 11 for the same kind of test score. What can you judge?",steps:[{text:"IQR measures the spread of the middle half of each data set."},{text:"A smaller IQR means those middle observations occupy a narrower interval."}],answer:"Class A has the more tightly clustered middle 50%; this alone does not tell us which class has the higher typical score."}]}],mistakes:["Order data before locating quartiles.","Do not drop repeated values when ordering.","Frequency totals must match the number of observations.","Pie-chart sectors must total 360°.","Use category/total×360° for a sector angle.","IQR is Q3−Q1, not maximum−minimum.","State the quartile convention used.","A box plot needs all five summary values.","Interpret results in the context of the data."]},
"Probability":{title:"Probability and Chance",objectives:["Discuss chance events in everyday life","Use the probability scale from 0 to 1","Identify outcomes, events and sample spaces","Calculate probability of simple equally likely events","Perform and interpret coin and dice experiments","Distinguish theoretical and experimental probability","Represent uncertain events using fractions, decimals and percentages","Use complements in simple situations","Make careful inferences from chance data"],sections:[
{title:"1. Chance in everyday life",body:["A chance event is an event whose outcome is uncertain before it happens. Examples include whether rain falls on a particular day, the face obtained when a coin is tossed, or the number obtained when a fair die is rolled.","Probability describes likelihood; it does not promise what will happen in one trial."]},
{title:"2. Probability scale",body:["Probability ranges from 0 to 1 inclusive. Probability 0 means impossible; probability 1 means certain. Values nearer 1 represent greater likelihood than values nearer 0."],board:["0 ───────── 1/2 ───────── 1","impossible     even chance     certain"]},
{title:"3. Outcomes, experiments and events",body:["A probability experiment is an action with an uncertain result. An outcome is one possible result. An event is one outcome or a collection of outcomes being considered.","Listing possibilities before calculating prevents missing or double-counting outcomes."]},
{title:"4. Sample space",body:["The sample space lists all possible outcomes. For one coin toss S={H,T}. For one fair die roll S={1,2,3,4,5,6}."],example:{q:"List the outcomes greater than 4 on a fair die.",steps:[{text:"List every possible outcome first. The sample space supplies the denominator and prevents us from accidentally omitting or double-counting an outcome.",math:["S={1,2,3,4,5,6}"]},{text:"Now apply the event condition to each member of the sample space. Keep only outcomes strictly greater than 4; these become the favourable outcomes counted in the numerator.",math:["E={5,6}"]}],answer:"{5,6}"}},
{title:"5. Equally likely outcomes",body:["When all outcomes are equally likely, probability of an event equals the number of favourable outcomes divided by the total number of possible outcomes."],board:["P(event)=favourable outcomes/total equally likely outcomes"],example:{q:"Find P(even number) on a fair die.",steps:[{text:"Write the complete sample space first so no possible result is forgotten.",math:["S={1,2,3,4,5,6}","total outcomes=6"]},{text:"An even number is divisible by 2 with no remainder. From the sample space, 2,4 and 6 are even, so there are three favourable outcomes.",math:["E={2,4,6}","favourable outcomes=3"]},{text:"Because the six faces of a fair die are equally likely, use favourable outcomes over total outcomes.",math:["P(even)=3/6"]},{text:"Simplify by dividing both 3 and 6 by 3.",math:["3÷3=1","6÷3=2","3/6=1/2"]},{text:"The result 1/2 means half of the six equally likely faces are even. This also matches the count: three of six faces."}],answer:"P(even number)=1/2"}},
{title:"6. Two coin tosses",body:["With two tosses, ordered outcomes are HH, HT, TH and TT. HT and TH are different sequences even though both contain one head and one tail."],example:{q:"Find P(exactly one head in two fair tosses).",steps:[{text:"List all possible equally likely outcomes before counting the event. This establishes the total number of possibilities that belongs in the probability denominator.",math:["S={HH,HT,TH,TT}"]},{text:"HT and TH are favourable.",math:["P=2/4=1/2"]}],answer:"1/2"}},
{title:"7. Experimental probability",body:["NERDC asks learners to perform chance experiments and record observations. Experimental probability uses what actually occurred: observed frequency divided by total trials."],board:["experimental P(event)=observed event frequency/number of trials"],example:{q:"A coin gives 27 heads in 50 tosses. Find the experimental probability of a head.",steps:[{text:"This is an experiment, so use what was actually observed rather than automatically using the theoretical value 1/2. Heads occurred 27 times, and the coin was tossed 50 times altogether.",math:["observed head frequency=27","total trials=50"]},{text:"Experimental probability is observed event frequency divided by the total number of trials.",math:["experimental P(head)=27/50"]},{text:"To write the fraction as a decimal, perform 27÷50. An equivalent denominator of 100 makes the conversion easy: multiply numerator and denominator by 2.",math:["27/50=54/100","=0.54"]},{text:"A decimal is converted to a percentage by multiplying by 100%.",math:["0.54×100%=54%"]},{text:"Interpret carefully: heads occurred in 54% of these 50 recorded tosses. This experimental result does not mean the next toss is guaranteed to be a head."}],answer:"Experimental P(head)=27/50=0.54=54%"}},
{title:"8. Theoretical versus experimental",body:["Theoretical probability comes from a mathematical model of equally likely outcomes. Experimental probability comes from collected results. A short experiment need not match the theoretical value exactly.","Repeating an experiment more times often makes the observed proportion more stable, but no exact short-run pattern is guaranteed."]},
{title:"9. Complementary events",body:["An event and its complement 'not the event' cover all possibilities, so their probabilities add to 1."],board:["P(not A)=1−P(A)"],example:{q:"If P(rain)=0.3, find P(no rain).",steps:[{text:"Rain and no rain are complementary events: exactly one of them must occur, so together their probabilities make the whole probability 1.",math:["P(no rain)=1−0.3=0.7"]}],answer:"0.7"}},
{title:"10. Equivalent probability forms",body:["A probability can be written as a fraction, decimal or percentage. These forms must represent the same value."],example:{q:"Write 3/5 as decimal and percentage.",steps:[{text:"A fraction is also a division statement. Divide the numerator by the denominator to express the same probability as a decimal without changing its value.",math:["3/5=0.6"]},{text:"Percent means ‘out of 100’. Multiply the decimal probability by 100% to express the same likelihood as a percentage.",math:["0.6×100%=60%"]}],answer:"0.6 or 60%"}},
{title:"11. Everyday inference",body:["Probability can support careful reasoning about uncertain events. A probability of 0.7 indicates greater likelihood than 0.3 but does not guarantee the next result.","When a probability is estimated from real observations, the amount and quality of data affect the strength of the inference."]},
{title:"12. Quantitative checks",body:["Every valid probability lies between 0 and 1 inclusive. Check that the sample space is complete, favourable outcomes belong to the event and the denominator includes all relevant equally likely outcomes."],example:{q:"Find P(rolling 7 on an ordinary die).",steps:[{text:"Check the sample space.",math:["S={1,2,3,4,5,6}","7 is not an outcome"]},{text:"Because the requested result is absent from the sample space, no possible outcome satisfies the event. The favourable-outcome count is therefore zero.",math:["P=0/6=0"]}],answer:"0"}}
,{title:"13. Natural chance language",body:["Words such as impossible, unlikely, even chance, likely and certain can be connected to the 0-to-1 probability scale. They describe degrees of likelihood rather than guaranteed short-run outcomes."]},
{title:"14. Ludo/die experiment",body:["A ludo die provides six outcomes, 1 to 6, when it is fair. NERDC specifically expects learners to generate chance events using familiar experiments such as ludo and coin tossing."],example:{q:"For one fair ludo die, find P(number greater than 4).",steps:[{text:"Start with every result that can appear on one fair die. There are six faces, numbered 1 to 6. Because the die is fair, these six outcomes are treated as equally likely.",math:["S={1,2,3,4,5,6}","total possible outcomes = 6"]},{text:"The event says ‘number greater than 4’. Test the outcomes against that condition: 1,2,3 and 4 are not greater than 4; 5 and 6 are. Therefore there are exactly two favourable outcomes.",math:["E={5,6}","favourable outcomes = 2"]},{text:"For equally likely outcomes, probability compares favourable outcomes with all possible outcomes. This explains where both numbers in the fraction come from: 2 favourable outcomes out of 6 possible outcomes.",math:["P(E)=favourable outcomes/total possible outcomes","=2/6"]},{text:"Simplify 2/6 by dividing numerator and denominator by their common factor 2. Dividing both by the same non-zero number keeps the fraction equivalent.",math:["2÷2=1","6÷2=3","2/6=1/3"]},{text:"Check the result. A probability must lie from 0 to 1, and 1/3 does. It means one third of the equally likely die outcomes satisfy the condition; it does not promise one success in every three actual rolls."}],answer:"P(number greater than 4)=1/3"}},
{title:"15. Combined description of an event",body:["Translate words carefully into a set of favourable outcomes before forming the fraction."],example:{q:"Find P(odd number less than 5) on a fair die.",steps:[{text:"Odd die outcomes are 1,3,5; those below 5 are 1 and 3.",math:["E={1,3}"]},{text:"There are 2 favourable outcomes from 6.",math:["P=2/6=1/3"]}],answer:"1/3"}},
{title:"16. Experimental table",body:["Record outcomes and frequencies rather than relying on memory. The frequencies must sum to the number of trials."],example:{q:"A die is rolled 60 times and 6 appears 8 times. Find experimental P(6).",steps:[{text:"Use observed frequency over total trials.",math:["P(6)=8/60=2/15"]}],answer:"2/15"}},
{title:"17. Compare experiment with theory",body:["For a fair die, theoretical P(6)=1/6. An experimental result such as 8/60 need not equal 1/6 exactly. Compare them and explain that random variation occurs."],example:{q:"Compare 8/60 with theoretical 1/6.",steps:[{text:"Convert or estimate.",math:["8/60≈0.133","1/6≈0.167"]}],answer:"The experiment produced a lower proportion, but this does not by itself prove the die is unfair."}},
{title:"18. Predict an expected frequency carefully",body:["Probability can estimate how often an event may occur over many trials: expected frequency = probability × number of trials. This is an expectation, not a promise."],example:{q:"A fair coin is tossed 200 times. About how many heads are expected?",steps:[{text:"For a fair coin P(head)=1/2.",math:["expected=1/2×200=100"]}],answer:"About 100 heads."}},
{title:"19. Complement in context",body:["Use complements when 'not' is easier than listing many outcomes."],example:{q:"A fair die is rolled. Find P(not 6).",steps:[{text:"P(6)=1/6.",math:["P(not 6)=1−1/6=5/6"]}],answer:"5/6"}},
{title:"20. Check impossible probability claims",body:["Any calculated probability below 0 or above 1 signals an error. Also check that favourable outcomes cannot exceed total outcomes."],example:{q:"A learner writes P(A)=7/6. What is wrong?",steps:[{text:"7/6 is greater than 1."},{text:"An event cannot have more favourable equally likely outcomes than all possible outcomes."}],answer:"7/6 cannot be a valid probability."}},
{title:"21. Statistical inference with probability",body:["When using experimental results to discuss future chance, describe them as evidence or estimates. A larger, well-recorded set of trials generally gives a more stable experimental proportion than a tiny set, but it still does not guarantee the next outcome."]},
{title:"22. Probability mastery investigation",body:["A learner should be able to run a coin or ludo/die experiment, create a frequency record, calculate experimental probability, calculate the corresponding theoretical probability where appropriate, compare them, use complements and explain the result in everyday language."],example:{q:"In 80 coin tosses, heads occurs 46 times. Give experimental probabilities of head and tail.",steps:[{text:"Tail frequency is the remaining trials.",math:["tails=80−46=34"]},{text:"Form both probabilities.",math:["P(H)=46/80=23/40","P(T)=34/80=17/40"]},{text:"Check they sum to 1.",math:["23/40+17/40=1"]}],answer:"P(H)=23/40 and P(T)=17/40."}},{title:"23. Deep mastery: chance, experiment and inference",body:["Probability is not only fraction calculation. Learners must distinguish theoretical likelihood from observed experimental frequency, interpret uncertainty responsibly and use data to make cautious predictions rather than guarantees."],examples:[{q:"A fair die is rolled 120 times. Predict how many sixes may occur.",steps:[{text:"For a fair die, one of six equally likely faces is a six.",math:["P(6)=1/6"]},{text:"Expected frequency applies that theoretical fraction to 120 trials.",math:["120×1/6=20"]},{text:"This is a prediction, not a guarantee. A real experiment may give somewhat more or fewer sixes."}],answer:"About 20 sixes are expected."},{q:"Rain occurred on 18 of 60 observed days. Find and interpret the experimental probability.",steps:[{text:"Use the observed frequency over the total number of recorded days.",math:["18/60"]},{text:"Simplify and convert if useful.",math:["18/60=3/10=0.3=30%"]},{text:"Interpret the statistic as a description of this observed data. It does not guarantee rain on exactly 3 of every next 10 days."}],answer:"Experimental probability=0.3 or 30% for the recorded period."}]}],mistakes:["Probability must lie between 0 and 1 inclusive.","List the sample space before counting favourable outcomes.","Use favourable/total only when outcomes are equally likely.","Do not confuse theoretical probability with experimental frequency.","Experimental probability uses observed frequency over total trials.","Complementary probabilities add to 1.","A high probability does not guarantee one particular outcome."]}

};
export default function JSS2PremiumMathLesson({topic,onExercise}:{topic:string;onExercise:()=>void}){const l=lessons[topic];if(!l)return null;return <article className="wn-lesson fractions-premium-lesson"><header className="wn-hero"><span>JSS2 MATHEMATICS · NERDC SEPTEMBER 2025</span><h1>{l.title}</h1><p>Concept-first teaching, fully worked reasoning and curriculum-level application.</p></header><section className="wn-objectives"><h2>Learning Objectives</h2><ul>{l.objectives.map(x=><li key={x}>{x}</li>)}</ul></section>{l.sections.map(s=><section className="wn-section" key={s.title}><h3>{s.title}</h3>{topic==="Bearing"?<BearingVisualForSection title={s.title}/>:<CoreTopicVisual topic={topic} title={s.title}/>} {s.body.map((p,i)=><p key={i}>{p}</p>)}{s.board&&<div className="formula-board">{s.board.map((x,i)=><div className="formula-line" key={i}><MathText text={x}/></div>)}</div>}{[...(s.example?[s.example]:[]),...(s.examples||[])].map((ex,ei)=><div className="fraction-working" key={ei}><div className="example-question"><span>{ei===0?'WORKED EXAMPLE':`COMPLEMENTARY EXAMPLE ${ei+1}`}</span><strong>{ex.q}</strong></div><div className="math-stack">{ex.steps.map((x,i)=>typeof x==='string'?<LegacyStep text={x} key={i}/>:<div className="math-line math-teaching-step" key={i}><div className="step-explanation">{x.text}</div>{x.math&&<div className="vertical-working">{x.math.map((line,j)=><div className="vertical-equation" key={j}><MathText text={line}/></div>)}</div>}{x.rows&&<div className="equation-board">{x.rows.map((r,j)=><div className="equation-row" key={j}><span className={r.cancelLeft?'equation-cell cancelled':'equation-cell'}><MathText text={r.left}/>{r.operatorLeft&&<span className="equation-operator">{r.operatorLeft}</span>}</span>{r.right!==undefined&&<><span className="equation-equals">=</span><span className={r.cancelRight?'equation-cell cancelled':'equation-cell'}><MathText text={r.right}/>{r.operatorRight&&<span className="equation-operator">{r.operatorRight}</span>}</span></>}</div>)}</div>}{x.note&&<div className="step-note">{x.note}</div>}</div>)}<div className="math-line math-result">{ex.answer}</div></div></div>)}</section>)}<section className="wn-section"><h3>Common Mistakes and Misconceptions</h3><div className="lesson-rule">{l.mistakes.map(x=><span key={x}>{x}</span>)}</div></section><section className="wn-section"><h3>Mastery Standard</h3><p>Do not move on because a rule has been memorised. You should be able to explain the idea, complete the method accurately, solve an unfamiliar application and check whether the answer is reasonable.</p></section><div className="teacher-actions"><button className="primary" onClick={onExercise}>Go to Exercise →</button></div></article>}
export const jss2PremiumMathTopics=Object.keys(lessons);